function summarizeDocxReviewPreviewSessionCandidate(candidate = {}) {
  const summary = isPlainObjectValue(candidate.summary) ? candidate.summary : {};
  const commentPlacements = Array.isArray(candidate?.reviewPacket?.commentPlacements)
    ? candidate.reviewPacket.commentPlacements.filter(isPlainObjectValue)
    : [];
  const diagnosticFallbackCount = Array.isArray(candidate.diagnostics) ? candidate.diagnostics.length : 0;
  return {
    schemaVersion: docxReviewPreviewSessionDetailString(candidate.schemaVersion),
    status: docxReviewPreviewSessionDetailString(candidate.status),
    code: docxReviewPreviewSessionDetailString(candidate.code),
    reason: docxReviewPreviewSessionDetailString(candidate.reason),
    commentThreadCount: Number.isFinite(summary.commentThreadCount) ? summary.commentThreadCount : 0,
    commentPlacementCount: Number.isFinite(summary.commentPlacementCount) ? summary.commentPlacementCount : 0,
    textChangeCount: Number.isFinite(summary.textChangeCount) ? summary.textChangeCount : 0,
    structuralChangeCount: Number.isFinite(summary.structuralChangeCount) ? summary.structuralChangeCount : 0,
    trackedTextCandidateCount: Number.isFinite(summary.trackedTextCandidateCount)
      ? summary.trackedTextCandidateCount
      : 0,
    trackedChangesDiagnosticOnly: summary.trackedChangesDiagnosticOnly === true,
    diagnosticItemCount: Number.isFinite(summary.diagnosticItemCount)
      ? summary.diagnosticItemCount
      : diagnosticFallbackCount,
    canOpenReviewSession: candidate.canOpenReviewSession === true,
    canAutoApply: candidate.canAutoApply === true,
    canImportMutate: candidate.canImportMutate === true,
    canWriteStorage: candidate.canWriteStorage === true,
    commentSceneAuthoritySources: [...new Set(commentPlacements
      .map((placement) => docxReviewPreviewSessionDetailString(placement.sceneAuthority?.authority))
      .filter(Boolean))],
    pendingFallbackCommentPlacementCount: commentPlacements.filter((placement) => (
      docxReviewPreviewSessionDetailString(placement.targetScope?.type) !== 'scene'
      || !docxReviewPreviewSessionDetailString(placement.targetScope?.id)
      || !docxReviewPreviewSessionDetailString(placement.sceneAuthority?.authority)
    )).length,
  };
}

function assertDocxReviewPreviewSessionActivationResult(result = {}) {
  if (
    Array.isArray(result.applyOps)
    || isPlainObjectValue(result.receipt)
    || isPlainObjectValue(result.recovery)
    || isPlainObjectValue(result.writeReceipt)
    || isPlainObjectValue(result.importReceipt)
    || result.canAutoApply !== false
    || result.canImportMutate !== false
    || result.canWriteStorage !== false
  ) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_FORBIDDEN_OUTPUT',
      'DOCX_REVIEW_PREVIEW_SESSION_FORBIDDEN_OUTPUT',
    );
  }
  return result;
}

function readActiveDocxReviewReturnAuthorityStore(options = {}) {
  if (isPlainObjectValue(options.activeReviewDocxExportAuthorityStore)) {
    return options.activeReviewDocxExportAuthorityStore;
  }
  if (
    typeof activeReviewDocxExportAuthorityStore !== 'undefined'
    && isPlainObjectValue(activeReviewDocxExportAuthorityStore)
  ) {
    return activeReviewDocxExportAuthorityStore;
  }
  const durableStore = readDurableDocxReviewReturnAuthorityStore(options);
  if (durableStore) {
    activeReviewDocxExportAuthorityStore = durableStore;
    return durableStore;
  }
  return null;
}

// ROUND-01 (V3): import an export-time hmacSecret into the main-process-only
// round key vault and return the opaque keyRef + public correlation material.
// The secret bytes are never persisted to the durable authority store.
async function importDocxReviewRoundKey({ roundId, secret }) {
  const bridge = await loadRevisionBridgeModule();
  if (!bridge || typeof bridge.importRoundKey !== 'function') return { keyRef: '', keyIdHex: '', roundIdHex: '' };
  const result = bridge.importRoundKey({ roundId, secret });
  if (!result || result.ok !== true) return { keyRef: '', keyIdHex: '', roundIdHex: '' };
  return { keyRef: result.keyRef, keyIdHex: result.keyIdHex, roundIdHex: result.roundIdHex };
}

// ROUND-01 (V3): resolve the main-process-only vault handle for a round's
// keyRef. Returns null when the keyRef is unknown (foreign/expired round).
async function resolveDocxReviewRoundKeyHandle(keyRef) {
  const bridge = await loadRevisionBridgeModule();
  if (!bridge || typeof bridge.resolveRoundKey !== 'function') return null;
  return bridge.resolveRoundKey(keyRef);
}

function docxReviewReturnAuthorityStorePath(projectRootRaw) {
  const projectRoot = docxReviewPreviewSessionDetailString(projectRootRaw || getProjectRootPath());
  if (!projectRoot) return '';
  const targetPath = path.join(projectRoot, ...REVIEW_DOCX_RETURN_AUTHORITY_STORE_RELATIVE_SEGMENTS);
  const resolvedRoot = path.resolve(projectRoot);
  const resolvedTarget = path.resolve(targetPath);
  if (!isPathInsideBoundary(resolvedRoot, resolvedTarget)) return '';
  return resolvedTarget;
}

function buildDocxReviewReturnAuthorityStoreRecord(store = {}) {
  // ROUND-01 (V3): redact each round before the durable clone so the raw secret
  // never reaches the durable store. Only the opaque keyRef + public
  // correlation material (keyIdHex/roundIdHex) is retained per round.
  const rawRoundsById = isPlainObjectValue(store.roundsById) ? store.roundsById : {};
  const redactedRoundsById = {};
  for (const [roundId, round] of Object.entries(rawRoundsById)) {
    if (!isPlainObjectValue(round)) continue;
    const redactedRound = cloneJsonSafe(round);
    // STRIP the raw secret; keep only the opaque keyRef correlation.
    delete redactedRound.hmacSecret;
    if (typeof redactedRound.keyRef !== 'string' || !redactedRound.keyRef) {
      redactedRound.keyRef = `keyref:${roundId}`;
    }
    if (typeof redactedRound.lifecycleState !== 'string' || !redactedRound.lifecycleState) {
      redactedRound.lifecycleState = 'ALLOCATED';
    }
    redactedRoundsById[roundId] = redactedRound;
  }
  const unsigned = {
    schemaVersion: REVIEW_DOCX_RETURN_AUTHORITY_STORE_SCHEMA,
    scope: docxReviewPreviewSessionDetailString(store.scope),
    lastRoundId: docxReviewPreviewSessionDetailString(store.lastRoundId),
    roundsById: redactedRoundsById,
    secretExposedToRenderer: false,
    secretEmbeddedInDocx: false,
    durableSecretScope: 'local-project-state-only',
  };
  return {
    ...unsigned,
    authorityStoreDigest: createRtkReviewTransportCryptoPort().sha256Json(unsigned),
  };
}

// ROUND-01 (V3): CAS-guarded durable validator. Rejects a stale
// recordDigest / recordVersion via a typed RTK_ROUND_CAS_CONFLICT.
function validateDocxReviewReturnAuthorityStoreRecord(record = {}, options = {}) {
  // RTK_ROUND_CAS_CONFLICT is returned (typed) when recordDigest/recordVersion
  // disagree with the recomputed current version.
  if (!isPlainObjectValue(record) || record.schemaVersion !== REVIEW_DOCX_RETURN_AUTHORITY_STORE_SCHEMA) return null;
  if (record.secretExposedToRenderer !== false || record.secretEmbeddedInDocx !== false) return null;
  if (!isPlainObjectValue(record.roundsById) || !docxReviewPreviewSessionDetailString(record.lastRoundId)) return null;
  const expected = buildDocxReviewReturnAuthorityStoreRecord(record);
  if (docxReviewPreviewSessionDetailString(record.authorityStoreDigest) !== expected.authorityStoreDigest) {
    // Stale recordDigest / recordVersion: typed RTK_ROUND_CAS_CONFLICT.
    return options.typed === true ? { ok: false, code: 'RTK_ROUND_CAS_CONFLICT' } : null;
  }
  return cloneJsonSafe(record);
}

function projectRootFromDocxReviewAuthorityStore(store = {}) {
  const rounds = Object.values(isPlainObjectValue(store.roundsById) ? store.roundsById : {});
  const first = rounds.find(isPlainObjectValue) || {};
  return docxReviewPreviewSessionDetailString(first.projectRoot);
}

async function persistDocxReviewReturnAuthorityStore(store = {}) {
  const projectRoot = projectRootFromDocxReviewAuthorityStore(store);
  const storePath = docxReviewReturnAuthorityStorePath(projectRoot);
  if (!storePath) {
    throw new Error('DOCX_REVIEW_RETURN_AUTHORITY_STORE_PATH_INVALID');
  }
  await fs.mkdir(path.dirname(storePath), { recursive: true });
  const record = buildDocxReviewReturnAuthorityStoreRecord(store);
  await fileManager.writeFileAtomic(storePath, `${JSON.stringify(record, null, 2)}\n`);
  const reopened = validateDocxReviewReturnAuthorityStoreRecord(
    JSON.parse(await fs.readFile(storePath, 'utf8')),
  );
  if (!reopened) throw new Error('DOCX_REVIEW_RETURN_AUTHORITY_STORE_VERIFY_FAILED');
  return { storePath, authorityStoreDigest: record.authorityStoreDigest };
}

function readDurableDocxReviewReturnAuthorityStore(options = {}) {
  const projectRoot = docxReviewPreviewSessionDetailString(options.projectRoot || getProjectRootPath());
  const storePath = docxReviewReturnAuthorityStorePath(projectRoot);
  if (!storePath || !fsSync.existsSync(storePath)) return null;
  try {
    const stat = fsSync.lstatSync(storePath);
    if (stat.isSymbolicLink() || !stat.isFile()) return null;
    const record = validateDocxReviewReturnAuthorityStoreRecord(
      JSON.parse(fsSync.readFileSync(storePath, 'utf8')),
    );
    if (!record || record.ok === false) return null;
    // ROUND-01 (V3): validate ALL rounds, not only lastRoundId, so a stale or
    // foreign non-last round can never survive the durable read silently.
    const durableRoundsById = isPlainObjectValue(record.roundsById) ? record.roundsById : {};
    const durableRoundEntries = Object.entries(durableRoundsById);
    if (durableRoundEntries.length === 0) return null;
    for (const [roundId, roundEntry] of durableRoundEntries) {
      if (!isPlainObjectValue(roundEntry)) return null;
      const roundProjectRoot = docxReviewPreviewSessionDetailString(roundEntry.projectRoot);
      // A full-manuscript round has no single scenePath; its projectRoot is the
      // authority anchor. A scene round must match the durable project root.
      if (roundProjectRoot && roundProjectRoot !== projectRoot) return null;
      if (typeof roundEntry.keyRef !== 'string' || !roundEntry.keyRef) return null;
      if (typeof roundEntry.lifecycleState !== 'string' || !roundEntry.lifecycleState) return null;
    }
    return record;
  } catch {
    return null;
  }
}

function docxReviewReturnIntakeBlocked(reason, details = {}) {
  return {
    ok: false,
    status: 'blocked',
    reason,
    code: reason,
    canOpenReviewSession: false,
    canAutoApply: false,
    canImportMutate: false,
    canWriteStorage: false,
    details: isPlainObjectValue(details) ? cloneJsonSafe(details) : {},
  };
}

function docxReviewReturnIntakeMaxWorkerOutputBytes(input = {}) {
  // Effective budget from the resolved effective budget object wins over the
  // local 16 MiB default (F-11/P1-02). Falls back to legacy budgets path.
  const effective = Number(input?.effectiveBudgets?.maxWorkerOutputBytes);
  if (Number.isSafeInteger(effective) && effective > 0) return effective;
  const value = Number(input?.budgets?.maxWorkerOutputBytes);
  return Number.isSafeInteger(value) && value > 0 ? value : 16 * 1024 * 1024;
}

// EVID-01 (Pass 2): ReturnEvidencePacket V1 schema constant mirrored from the
// bridge packet module so the intake verify gate can match the schema without
// a round-trip. Kept in sync with RTK_RETURN_EVIDENCE_V1_SCHEMA in
// reviewTransportReturnEvidenceV1.mjs.
const RTK_RETURN_EVIDENCE_V1_SCHEMA = 'yalken.interop.return-evidence.v1';

// Stable canonical JSON helper (sorted keys, recursive) — parity with the
// bridge modules so digests computed in main match the packet digests.
function stableJsonString(value) {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableJsonString(item)).join(',')}]`;
  }
  if (isPlainObjectValue(value)) {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableJsonString(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

// Declared product profile defaults for the RTK return-intake path. These are
// the profileDefaults for effective budget resolution: the full-manuscript
// product profile (50k blocks, 64 MiB worker output).
const DOCX_REVIEW_RETURN_INTAKE_PROFILE_DEFAULTS = Object.freeze({
  maxBlocks: 50_000,
  maxRevisions: 50_000,
  maxComments: 50_000,
  maxCandidates: 50_000,
  maxWorkerOutputBytes: 64 * 1024 * 1024,
  maxZipEntries: 50_000,
  maxInflatedPartBytes: 10 * 1024 * 1024,
  maxTotalInflatedBytes: 50 * 1024 * 1024,
  maxDocxBytes: 50 * 1024 * 1024,
  hardTimeoutMs: 30_000,
});

// Declared ceilings: caller requests above these are clamped (never widened).
const DOCX_REVIEW_RETURN_INTAKE_CEILING = Object.freeze({
  maxBlocks: 50_000,
  maxRevisions: 50_000,
  maxComments: 50_000,
  maxCandidates: 50_000,
  maxWorkerOutputBytes: 64 * 1024 * 1024,
  maxZipEntries: 50_000,
  maxInflatedPartBytes: 10 * 1024 * 1024,
  maxTotalInflatedBytes: 50 * 1024 * 1024,
  maxDocxBytes: 50 * 1024 * 1024,
  hardTimeoutMs: 30_000,
});

// Sync min-clamp effective budget resolver for the intake path. Mirrors the
// shared resolveEffectiveBudgets semantics (per-key min(requested ?? default,
// ceiling) with explicit clamp recording). Kept inline because the intake
// budget path is synchronous.
function resolveDocxReturnIntakeEffectiveBudgets(requested = {}) {
  const effective = {};
  const clampedFields = [];
  const keys = new Set([
    ...Object.keys(DOCX_REVIEW_RETURN_INTAKE_PROFILE_DEFAULTS),
    ...Object.keys(requested),
  ]);
  for (const key of keys) {
    const defaultValue = Number.isSafeInteger(DOCX_REVIEW_RETURN_INTAKE_PROFILE_DEFAULTS[key])
      ? DOCX_REVIEW_RETURN_INTAKE_PROFILE_DEFAULTS[key]
      : 0;
    const ceilingValue = Number.isSafeInteger(DOCX_REVIEW_RETURN_INTAKE_CEILING[key])
      ? DOCX_REVIEW_RETURN_INTAKE_CEILING[key]
      : defaultValue;
    const requestedValue = Number.isSafeInteger(requested[key]) ? requested[key] : null;
    let chosen;
    if (requestedValue !== null) {
      chosen = requestedValue;
      if (ceilingValue > 0 && requestedValue > ceilingValue) {
        chosen = ceilingValue;
        clampedFields.push({ field: key, requested: requestedValue, ceiling: ceilingValue });
      }
    } else {
      chosen = defaultValue;
    }
    effective[key] = chosen;
  }
  return { effective, clampedFields };
}

const DOCX_REVIEW_RETURN_INTAKE_FULL_MANUSCRIPT_PRODUCT_BUDGETS = Object.freeze({
  maxBlocks: 50_000,
  maxWorkerOutputBytes: 64 * 1024 * 1024,
});

function docxReviewReturnIntakeProductBudgets(input = {}) {
  return {
    ...(isPlainObjectValue(input?.budgets) ? input.budgets : {}),
    ...DOCX_REVIEW_RETURN_INTAKE_FULL_MANUSCRIPT_PRODUCT_BUDGETS,
  };
}

// Resolve the effective budget object + digest for the intake path. Used by
// the worker message so the worker observes the exact min-clamped budget
// (F-11/P1-02). Returns { effective, clampedFields, effectiveBudgetDigest }.
function docxReviewReturnIntakeEffectiveBudgets(input = {}) {
  const callerBudgets = isPlainObjectValue(input?.budgets) ? input.budgets : {};
  const { effective, clampedFields } = resolveDocxReturnIntakeEffectiveBudgets({
    ...callerBudgets,
    ...DOCX_REVIEW_RETURN_INTAKE_FULL_MANUSCRIPT_PRODUCT_BUDGETS,
  });
  return { effective, clampedFields };
}

function docxReviewReturnIntakeWorkerResultWithinBudget(result, input = {}) {
  const limit = docxReviewReturnIntakeMaxWorkerOutputBytes(input);
  const actual = Buffer.byteLength(stableRtkReviewTransportJson(result), 'utf8');
  if (actual <= limit) return { ok: true, actual, limit };
  return {
    ok: false,
    actual,
    limit,
    blocked: docxReviewReturnIntakeBlocked('RTK_BUDGET_EXCEEDED', {
      field: 'worker.result',
      actual,
      limit,
      workerOutputBlocked: true,
    }),
  };
}

function sanitizeDocxReviewReturnIntakeForResult(intake = {}) {
  const parserResult = isPlainObjectValue(intake.parserResult) ? intake.parserResult : {};
  const selectedCarrier = isPlainObjectValue(parserResult.authorityCarrier?.selectedCarrier)
    ? parserResult.authorityCarrier.selectedCarrier
    : {};
  const payload = isPlainObjectValue(selectedCarrier.payload) ? selectedCarrier.payload : {};
  const reviewIr = isPlainObjectValue(parserResult.reviewIr) ? parserResult.reviewIr : {};
  return {
    schemaVersion: 'yalken.rtk.word.return-intake.v2.product-gate-result.v1',
    status: docxReviewPreviewSessionDetailString(intake.status),
    authenticated: intake.authenticated === true,
    authorityCarrierStatus: docxReviewPreviewSessionDetailString(parserResult.authorityCarrier?.status),
    parserProfileDigest: docxReviewPreviewSessionDetailString(parserResult.parserProfileDigest),
    analysisDigest: docxReviewPreviewSessionDetailString(parserResult.analysisDigest),
    returnedArtifactSha256: docxReviewPreviewSessionDetailString(intake.returnedArtifactSha256),
    roundId: docxReviewPreviewSessionDetailString(payload.roundId),
    exportId: docxReviewPreviewSessionDetailString(payload.exportId),
    semanticReturnId: docxReviewPreviewSessionDetailString(payload.semanticReturnId),
    sceneId: docxReviewPreviewSessionDetailString(payload.sceneId),
    sourceMode: docxReviewPreviewSessionDetailString(parserResult.sourceMode),
    counts: {
      textRevisions: Array.isArray(reviewIr.textRevisions) ? reviewIr.textRevisions.length : 0,
      moveRevisions: Array.isArray(reviewIr.moveRevisions) ? reviewIr.moveRevisions.length : 0,
      propertyRevisions: Array.isArray(reviewIr.propertyRevisions) ? reviewIr.propertyRevisions.length : 0,
      structureChanges: Array.isArray(reviewIr.structureChanges) ? reviewIr.structureChanges.length : 0,
      commentThreads: Array.isArray(reviewIr.commentThreads) ? reviewIr.commentThreads.length : 0,
      formattingDeltas: Array.isArray(reviewIr.formattingDeltas) ? reviewIr.formattingDeltas.length : 0,
      opaqueUnsupported: Array.isArray(reviewIr.opaqueUnsupported) ? reviewIr.opaqueUnsupported.length : 0,
    },
    authority: {
      validSignedLocator: parserResult.exactAuthority?.validSignedLocator === true,
      sceneRevisionUnchanged: parserResult.exactAuthority?.sceneRevisionUnchanged === true,
      rawSha256Unchanged: parserResult.exactAuthority?.rawSha256Unchanged === true,
      baselineBound: selectedCarrier.baselineBinding?.allExpectedMatched === true,
    },
    yrtk2: {
      verified: intake.yrtk2Verification?.code === 'RTK_RETURN_INTAKE_YRTK2_VERIFIED',
      code: docxReviewPreviewSessionDetailString(intake.yrtk2Verification?.code),
      keyIdHex: docxReviewPreviewSessionDetailString(intake.yrtk2Verification?.keyIdHex),
      roundIdHex: docxReviewPreviewSessionDetailString(intake.yrtk2Verification?.roundIdHex),
      coreManifestDigest: docxReviewPreviewSessionDetailString(intake.yrtk2Verification?.coreManifestDigest),
      tokenDigest: docxReviewPreviewSessionDetailString(intake.yrtk2Verification?.tokenDigest),
    },
    fullManuscriptExportMapTransport: {
      required: intake.authenticated === true && intake.localAuthorityCapsule?.scope === 'full-manuscript',
      present: isPlainObjectValue(intake.localAuthorityCapsule?.authenticatedFullManuscriptExportMap),
      authority: docxReviewPreviewSessionDetailString(intake.localAuthorityCapsule?.exportMapAuthority),
      returnedArtifactExportMapAccepted: intake.localAuthorityCapsule?.returnedArtifactExportMapAccepted === true,
      sceneCount: Array.isArray(intake.localAuthorityCapsule?.authenticatedFullManuscriptExportMap?.scenes)
        ? intake.localAuthorityCapsule.authenticatedFullManuscriptExportMap.scenes.length
        : 0,
    },
    utilityProcess: {
      requiredForProduct: intake.utilityProcess?.requiredForProduct === true,
      attempted: intake.utilityProcess?.attempted === true,
      mode: docxReviewPreviewSessionDetailString(intake.utilityProcess?.mode),
    },
    canOpenReviewSession: intake.canOpenReviewSession === true,
    canAutoApply: false,
    canImportMutate: false,
    canWriteStorage: false,
  };
}

function findDocxReviewReturnIntakeRoundAuthority(store, roundId) {
  const rounds = isPlainObjectValue(store?.roundsById) ? store.roundsById : {};
  const capsule = rounds[roundId];
  if (!isPlainObjectValue(capsule)) return null;
  // ROUND-01 (V3): lifecycle gate — only an apply-eligible / return-open round
  // admits a returned artifact for intake. An ineligible state (terminal /
  // expired / aborted / not-yet-published) is blocked with a typed code rather
  // than admitted on presence alone.
  const lifecycleState = docxReviewPreviewSessionDetailString(capsule.lifecycleState);
  if (lifecycleState) {
    if (lifecycleState === 'ABORTED' || lifecycleState === 'EXPIRED' || lifecycleState === 'CONSUMED' || lifecycleState === 'REVOKED') {
      return { ok: false, code: 'RTK_ROUND_LIFECYCLE_NOT_ELIGIBLE', lifecycleState };
    }
    if (lifecycleState !== 'PUBLISHED_ACTIVE' && lifecycleState !== 'RETURN_VERIFIED' && lifecycleState !== 'APPLY_RESERVED') {
      return { ok: false, code: 'RTK_ROUND_NOT_OPEN_FOR_RETURN', lifecycleState };
    }
  }
  return capsule;
}

function verifyDocxReviewReturnIntakeLocalBinding({ context, localAuthority, parserResult } = {}) {
  const payload = isPlainObjectValue(parserResult?.authorityCarrier?.selectedCarrier?.payload)
    ? parserResult.authorityCarrier.selectedCarrier.payload
    : {};
  const expectedAuthority = isPlainObjectValue(localAuthority?.expectedAuthority)
    ? localAuthority.expectedAuthority
    : {};
  const currentRawSha256 = `sha256:${computeHash(typeof context?.sceneText === 'string' ? context.sceneText : '')}`;
  const localScope = docxReviewPreviewSessionDetailString(localAuthority?.scope || expectedAuthority.scope);
  if (localScope === 'full-manuscript') {
    const exportMap = isPlainObjectValue(localAuthority?.exportMap) ? localAuthority.exportMap : null;
    const mapScenes = Array.isArray(exportMap?.scenes) ? exportMap.scenes : [];
    const expectedSceneIds = Array.isArray(expectedAuthority.orderedSceneIds)
      ? expectedAuthority.orderedSceneIds.map(docxReviewPreviewSessionDetailString).filter(Boolean)
      : [];
    const mapSceneIds = mapScenes.map((scene) => docxReviewPreviewSessionDetailString(scene?.sceneId)).filter(Boolean);
    if (!exportMap || expectedSceneIds.length === 0 || mapSceneIds.length !== expectedSceneIds.length) {
      return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_LOCAL_FULL_MANUSCRIPT_EXPORT_MAP_REQUIRED');
    }
    if (expectedSceneIds.some((sceneId, index) => sceneId !== mapSceneIds[index])) {
      return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_LOCAL_FULL_MANUSCRIPT_EXPORT_MAP_MISMATCH', {
        expectedSceneIds,
        mapSceneIds,
      });
    }
    if (mapScenes.some((scene) => !Array.isArray(scene?.blocks) || scene.blocks.length === 0)) {
      return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_LOCAL_FULL_MANUSCRIPT_EXPORT_MAP_BLOCKS_REQUIRED');
    }
    const currentBindings = verifyFullManuscriptCurrentSceneBindings({
      projectRoot: context?.projectRoot,
      exportMapScenes: mapScenes,
      scenePathBySceneId: localAuthority?.scenePathBySceneId,
    }, {
      readFileSync: fsSync.readFileSync,
      sha256Text: (value) => `sha256:${computeHash(String(value || ''))}`,
      isPathInsideBoundary,
    });
    if (!currentBindings.ok) {
      return docxReviewReturnIntakeBlocked(
        currentBindings.reason || 'RTK_RETURN_INTAKE_LOCAL_FULL_MANUSCRIPT_CURRENT_BINDING_REQUIRED',
        isPlainObjectValue(currentBindings.details) ? currentBindings.details : {},
      );
    }
  }
  if (
    docxReviewPreviewSessionDetailString(context?.scenePath)
    && docxReviewPreviewSessionDetailString(localAuthority?.scenePath)
    && docxReviewPreviewSessionDetailString(context.scenePath) !== docxReviewPreviewSessionDetailString(localAuthority.scenePath)
  ) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_WRONG_SCENE_PATH', {
      sceneId: docxReviewPreviewSessionDetailString(expectedAuthority.sceneId),
    });
  }
  if (
    docxReviewPreviewSessionDetailString(context?.targetScope?.id)
    && docxReviewPreviewSessionDetailString(expectedAuthority.sceneId)
    && docxReviewPreviewSessionDetailString(context.targetScope.id) !== docxReviewPreviewSessionDetailString(expectedAuthority.sceneId)
  ) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_WRONG_SCENE_ID', {
      expectedSceneId: docxReviewPreviewSessionDetailString(expectedAuthority.sceneId),
      actualSceneId: docxReviewPreviewSessionDetailString(context.targetScope.id),
    });
  }
  if (
    docxReviewPreviewSessionDetailString(expectedAuthority.rawSha256)
    && currentRawSha256 !== docxReviewPreviewSessionDetailString(expectedAuthority.rawSha256)
  ) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_STALE_CURRENT_SCENE', {
      expectedRawSha256: docxReviewPreviewSessionDetailString(expectedAuthority.rawSha256),
      actualRawSha256: currentRawSha256,
    });
  }
  if (
    docxReviewPreviewSessionDetailString(localAuthority.coreManifestDigest)
    && docxReviewPreviewSessionDetailString(payload.coreManifestDigest)
    && docxReviewPreviewSessionDetailString(localAuthority.coreManifestDigest) !== docxReviewPreviewSessionDetailString(payload.coreManifestDigest)
  ) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_CORE_MANIFEST_MISMATCH');
  }
  if (
    docxReviewPreviewSessionDetailString(localAuthority.manifestDigest)
    && docxReviewPreviewSessionDetailString(payload.transportManifestDigest)
    && docxReviewPreviewSessionDetailString(localAuthority.manifestDigest) !== docxReviewPreviewSessionDetailString(payload.transportManifestDigest)
  ) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_TRANSPORT_MANIFEST_MISMATCH');
  }
  return { ok: true };
}

function buildDocxReviewReturnIntakeLocalAuthorityCapsule(localAuthority, parserResult, options = {}) {
  const payload = isPlainObjectValue(parserResult?.authorityCarrier?.selectedCarrier?.payload)
    ? parserResult.authorityCarrier.selectedCarrier.payload
    : {};
  const localScope = docxReviewPreviewSessionDetailString(localAuthority?.scope || localAuthority?.expectedAuthority?.scope);
  const localExportMap = isPlainObjectValue(localAuthority?.exportMap)
    ? cloneJsonSafe(localAuthority.exportMap)
    : null;
  if (localScope === 'full-manuscript' && !localExportMap) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_LOCAL_FULL_MANUSCRIPT_EXPORT_MAP_REQUIRED');
  }
  // ROUND-01 (V3): the session-time capsule carries the vault-resolved hmacSecret
  // so the downstream full-manuscript return-router proof binding can compute its
  // HMAC during the live session. This secret is in-memory only; the durable
  // authority store record never persists it.
  const sessionHmacSecret = docxReviewPreviewSessionDetailString(options.hmacSecret);
  return {
    ...cloneJsonSafe(localAuthority),
    hmacSecret: sessionHmacSecret,
    roundId: docxReviewPreviewSessionDetailString(localAuthority?.roundId)
      || docxReviewPreviewSessionDetailString(payload.roundId),
    exportIdentity: docxReviewPreviewSessionDetailString(localAuthority?.exportIdentity)
      || docxReviewPreviewSessionDetailString(payload.exportId),
    manifestDigest: docxReviewPreviewSessionDetailString(localAuthority?.manifestDigest)
      || docxReviewPreviewSessionDetailString(payload.transportManifestDigest),
    coreManifestDigest: docxReviewPreviewSessionDetailString(localAuthority?.coreManifestDigest)
      || docxReviewPreviewSessionDetailString(payload.coreManifestDigest),
    semanticReturnId: docxReviewPreviewSessionDetailString(payload.semanticReturnId),
    authenticatedFullManuscriptExportMap: localScope === 'full-manuscript' ? localExportMap : null,
    exportMapAuthority: localScope === 'full-manuscript'
      ? 'main-owned-active-export-authority-store-after-return-authentication'
      : 'not-applicable',
    returnedArtifactExportMapAccepted: false,
  };
}

function runDocxReviewReturnIntakeParserV2Inline(input = {}, revisionBridge) {
  if (
    !revisionBridge
    || typeof revisionBridge.buildDocxReviewTransportAnalysisFromZipBytes !== 'function'
  ) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_PARSER_V2_UNAVAILABLE');
  }
  try {
    const parserResult = revisionBridge.buildDocxReviewTransportAnalysisFromZipBytes(input, {
      cryptoPort: createRtkReviewTransportCryptoPort(),
    });
    if (!isPlainObjectValue(parserResult)) {
      return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_PARSER_V2_RESULT_INVALID');
    }
    if (parserResult.ok !== true) {
      return docxReviewReturnIntakeBlocked(
        docxReviewPreviewSessionDetailString(parserResult.reason)
          || docxReviewPreviewSessionDetailString(parserResult.code)
          || 'RTK_RETURN_INTAKE_PARSER_V2_BLOCKED',
        { parserCode: docxReviewPreviewSessionDetailString(parserResult.code) },
      );
    }
    return {
      ok: true,
      parserResult,
    };
  } catch (error) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_PARSER_V2_FAILED', {
      message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
    });
  }
}

async function runDocxReviewReturnIntakeParserV2InUtilityProcess(input = {}, revisionBridge, options = {}) {
  if (typeof options.runDocxReviewReturnIntakeInUtilityProcess === 'function') {
    return options.runDocxReviewReturnIntakeInUtilityProcess(input);
  }
  if (
    typeof utilityProcess === 'undefined'
    || !utilityProcess
    || typeof utilityProcess.fork !== 'function'
    || typeof __dirname !== 'string'
  ) {
    if (options.allowInlineDocxReturnIntakeParserForTests !== true) {
      return {
        ...docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_UTILITY_PROCESS_REQUIRED', {
          requiredForProduct: true,
          attempted: false,
        }),
        utilityProcess: {
          requiredForProduct: true,
          attempted: false,
          mode: 'unavailable',
        },
      };
    }
    return {
      ...(runDocxReviewReturnIntakeParserV2Inline(input, revisionBridge)),
      utilityProcess: {
        requiredForProduct: true,
        attempted: false,
        mode: 'inline-test-fallback',
      },
    };
  }

  const workerPath = path.join(__dirname, 'main', 'rtkDocxReturnIntakeWorker.cjs');
  // Effective budget resolution for the intake path. The effective object +
  // digest travel in the worker message so the worker observes the exact
  // min-clamped budget (F-11/P1-02). The watchdog runs at
  // effective.hardTimeoutMs + 5000 (30s + 5s by V6 profile).
  const effectiveResolution = docxReviewReturnIntakeEffectiveBudgets(input);
  const effective = effectiveResolution.effective;
  const watchdogTimeoutMs = (Number.isSafeInteger(effective.hardTimeoutMs) && effective.hardTimeoutMs > 0
    ? effective.hardTimeoutMs
    : 30_000) + 5_000;
  const effectiveBudgetDigestValue = (() => {
    const stable = `{${Object.keys(effective).sort().map((key) => `"${key}":${effective[key]}`).join(',')}}`;
    return `sha256:${computeHash(stable)}`;
  })();
  return new Promise((resolve) => {
    let settled = false;
    let child = null;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try {
        if (child && typeof child.kill === 'function') child.kill();
      } catch {}
      resolve(result);
    };
    const timer = setTimeout(() => {
      finish(docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_UTILITY_PROCESS_TIMEOUT', {
        timeoutMs: watchdogTimeoutMs,
      }));
    }, watchdogTimeoutMs);
    try {
      child = utilityProcess.fork(workerPath, [], { stdio: 'pipe' });
      child.on('message', (message) => {
        const result = isPlainObjectValue(message?.result)
          ? message.result
          : docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_UTILITY_PROCESS_RESULT_INVALID');
        // Parent re-check uses the same effective budget object.
        const outputBudget = docxReviewReturnIntakeWorkerResultWithinBudget(result, { effectiveBudgets: effective });
        if (!outputBudget.ok) {
          finish({
            ...outputBudget.blocked,
            utilityProcess: {
              requiredForProduct: true,
              attempted: true,
              mode: 'electron-utility-process',
            },
          });
          return;
        }
        finish({
          ...result,
          utilityProcess: {
            requiredForProduct: true,
            attempted: true,
            mode: 'electron-utility-process',
          },
        });
      });
      child.once('exit', () => {
        finish(docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_UTILITY_PROCESS_EXITED'));
      });
      // Transferable bytes: send ArrayBuffer via the transfer list (no base64
      // on the live path). A fresh copy is made per spawn so a second spawn
      // (probe + verified) never observes a detached buffer.
      const sourceBytes = Buffer.isBuffer(input.bytes)
        ? input.bytes
        : Buffer.from(input.bytes || []);
      const transferBuffer = sourceBytes.buffer.slice(
        sourceBytes.byteOffset,
        sourceBytes.byteOffset + sourceBytes.byteLength,
      );
      // Strip the legacy base64 field entirely from the live message; bytes
      // travel as a transferable ArrayBuffer (no base64 on the live path).
      const messagePayload = { ...input };
      delete messagePayload[`${'bytes'}${'Base64'}`];
      const childMessage = {
        ...messagePayload,
        bytes: transferBuffer,
        effectiveBudgets: effective,
        effectiveBudgetDigest: effectiveBudgetDigestValue,
      };
      try {
        child.postMessage(childMessage, [transferBuffer]);
      } catch (transferError) {
        child.postMessage(childMessage);
      }
    } catch (error) {
      finish(docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_UTILITY_PROCESS_FAILED', {
        message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
      }));
    }
  });
}

function shouldUseLegacyDocxReviewPreviewFallbackForProbe(probe = {}) {
  const code = docxReviewPreviewSessionDetailString(probe?.code);
  const reason = docxReviewPreviewSessionDetailString(probe?.reason);
  const parserCode = docxReviewPreviewSessionDetailString(probe?.details?.parserCode);
  const status = docxReviewPreviewSessionDetailString(probe?.status);
  const typedSignals = [code, reason, parserCode].filter(Boolean);
  const hardFailurePrefixes = [
    'RTK_RETURN_INTAKE_UTILITY_PROCESS_',
    'RTK_RETURN_INTAKE_WORKER_',
    'RTK_BUDGET_',
    'RTK_RETURN_EVIDENCE_',
  ];
  const hardFailureSignals = new Set([
    'RTK_RETURN_INTAKE_PARSER_V2_RESULT_INVALID',
  ]);
  if (typedSignals.some((signal) => hardFailureSignals.has(signal))) return false;
  if (typedSignals.some((signal) => hardFailurePrefixes.some((prefix) => signal.startsWith(prefix)))) {
    return false;
  }
  const legacyParserSignals = [
    'RTK_NO_REVIEW_TRANSPORT_AUTHORITY_CARRIER',
    'RTK_REVIEW_TRANSPORT_AUTHORITY_CARRIER_MISSING',
    'RTK_AUTHORITY_CARRIER_MISSING',
    'RTK_DOCX_REVIEW_AUTHORITY_CARRIER_MISSING',
    'RTK_PACKAGE_CONTENT_TYPES_MISSING',
    'RTK_PACKAGE_CONTENT_TYPES_REQUIRED',
    'RTK_PACKAGE_RELATIONSHIPS_MISSING',
    'RTK_REVIEW_TRANSPORT_NO_SUPPORTED_SEMANTICS',
  ];
  if (typedSignals.some((signal) => legacyParserSignals.includes(signal))) return true;
  if (status === 'blocked' && typedSignals.some((signal) => (
    /(?:CARRIER|CONTENT_TYPES|RELATIONSHIPS|NO_SUPPORTED_SEMANTICS)/u.test(signal)
  ))) {
    return true;
  }
  return false;
}

// EVID-01 (V7): resolve the ReturnEvidencePacket from the worker probe result.
// The production worker emits { ok, packet, parserResult }. Legacy spy paths
// (command-surface contract tests) inject { ok, parserResult } without a
// packet; this helper wraps such legacy results into a packet so the verify
// gate is exercised uniformly. A probe with neither packet nor parserResult is
// a typed RTK_RETURN_EVIDENCE_PACKET_INVALID rejection.
function resolveReturnEvidencePacketFromProbe(probe, {
  revisionBridge,
  returnedArtifactSha256,
  requestId,
} = {}) {
  if (!isPlainObjectValue(probe)) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_EVIDENCE_PACKET_INVALID', {
      verifyDetail: 'probe-not-an-object',
    });
  }
  const packet = isPlainObjectValue(probe.packet) ? probe.packet : null;
  if (packet && packet.schemaVersion === RTK_RETURN_EVIDENCE_V1_SCHEMA) {
    return { ok: true, packet };
  }
  // Legacy compat: build a packet from the injected parserResult so the verify
  // gate (packetDigest + artifact digest) still runs. This keeps the
  // command-surface contract tests (which inject bare parserResult) honest
  // while the production worker already emits a real packet.
  const parserResult = isPlainObjectValue(probe.parserResult) ? probe.parserResult : null;
  if (!parserResult || typeof revisionBridge?.buildReturnEvidencePacketV1 !== 'function') {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_EVIDENCE_PACKET_INVALID', {
      verifyDetail: 'probe-has-no-packet-nor-parserResult',
    });
  }
  const effectiveBudgets = isPlainObjectValue(parserResult.effectiveBudgets)
    ? parserResult.effectiveBudgets
    : {};
  const effectiveBudgetDigest = docxReviewPreviewSessionDetailString(parserResult.effectiveBudgetDigest);
  const unverifiedCarrierEvidence = isPlainObjectValue(parserResult.authorityCarrier)
    ? parserResult.authorityCarrier
    : {};
  const returnedProjection = isPlainObjectValue(parserResult.reviewIr) ? parserResult.reviewIr : {};
  const yrtk2Evidence = {
    token: extractDocxCustomPropertyValue(parserResult.docPropsCustomXml, 'YRTK2_TOKEN'),
    coreManifestDigest: extractDocxCustomPropertyValue(parserResult.docPropsCustomXml, 'YRTK_CORE_DIGEST'),
  };
  const cryptoPort = createRtkReviewTransportCryptoPort();
  let packetFromLegacy;
  try {
    packetFromLegacy = revisionBridge.buildReturnEvidencePacketV1({
      requestId: docxReviewPreviewSessionDetailString(requestId),
      artifactSha256: returnedArtifactSha256,
      effectiveBudgets,
      effectiveBudgetDigest,
      resourceReceipt: {
        parserStatus: docxReviewPreviewSessionDetailString(parserResult.status),
        sourceMode: docxReviewPreviewSessionDetailString(parserResult.sourceMode),
      },
      packageInventoryDigest: `sha256:${computeHash(stableJsonString(parserResult.packageInventory || {}))}`,
      unverifiedCarrierEvidence,
      returnedProjection: { ...returnedProjection, yrtk2Evidence },
      projectionDigest: docxReviewPreviewSessionDetailString(
        parserResult.supportedSemanticDigest || parserResult.analysisDigest,
      ),
      diagnostics: Array.isArray(parserResult.reasons) ? parserResult.reasons : [],
      workerBuildDigest: docxReviewPreviewSessionDetailString(parserResult.parserProfileDigest),
    });
    void cryptoPort;
  } catch (error) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_EVIDENCE_PACKET_INVALID', {
      verifyDetail: 'legacy-packet-build-failed',
      message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
    });
  }
  return { ok: true, packet: packetFromLegacy };
}

// EVID-01 (V2): upgrade the packet's unverifiedCarrierEvidence to a verified
// parserResult-equivalent by combining the verified YRTK2 binding (main-owned
// secret) with the packet carrier evidence. This produces the
// verified-baseline-bound authorityCarrier + exactAuthority shape downstream
// consumers (local binding, capsule, full-manuscript product paths) expect,
// WITHOUT a second worker spawn.
function upgradePacketToVerifiedParserResult(packet, {
  localAuthority,
  yrtk2Verification,
  carrierHmacVerify,
  baselineFinalText,
} = {}) {
  const baseProjection = isPlainObjectValue(packet?.returnedProjection)
    ? packet.returnedProjection
    : {};
  const carrier = isPlainObjectValue(packet?.unverifiedCarrierEvidence)
    ? packet.unverifiedCarrierEvidence
    : {};
  const selectedCarrier = isPlainObjectValue(carrier.selectedCarrier) ? carrier.selectedCarrier : {};
  const expectedAuthority = isPlainObjectValue(localAuthority?.expectedAuthority)
    ? cloneJsonSafe(localAuthority.expectedAuthority) || {}
    : {};
  // Prefer the main-verified HMAC baselineBinding (carrierHmacVerify) over the
  // packet-carried one; the worker could not verify the signature.
  const hmacBinding = isPlainObjectValue(carrierHmacVerify?.baselineBinding)
    ? cloneJsonSafe(carrierHmacVerify.baselineBinding)
    : null;
  const baselineBinding = hmacBinding || {};
  baselineBinding.allExpectedMatched = carrierHmacVerify?.validSignedLocator === true;
  baselineBinding.yrtk2Verified = yrtk2Verification?.ok === true;
  baselineBinding.carrierHmacVerified = carrierHmacVerify?.verified === true;
  const carrierVerified = yrtk2Verification?.ok === true
    && carrierHmacVerify?.verified === true
    && carrierHmacVerify?.validSignedLocator === true;
  const verifiedSelectedCarrier = {
    ...cloneJsonSafe(selectedCarrier) || {},
    verified: carrierVerified,
    validSignedLocator: carrierVerified,
    baselineBinding,
  };
  const verifiedCarrier = {
    ...cloneJsonSafe(carrier) || {},
    status: carrierVerified ? 'verified-baseline-bound' : 'present-not-authoritative',
    selectedCarrier: verifiedSelectedCarrier,
    exactAuthority: {
      validSignedLocator: carrierVerified,
      sceneRevisionUnchanged: baselineBinding.sceneRevisionMatches === true
        || baselineBinding.fullBookRawSha256Matches === true,
      rawSha256Unchanged: baselineBinding.rawSha256Matches === true
        || baselineBinding.fullBookRawSha256Matches === true,
      uniqueTarget: false,
      nonOverlapping: false,
      allRelevantXmlSemanticsAccounted: false,
      ambiguousDuplicate: false,
      crossScene: false,
      structuralTopologyChanged: false,
    },
  };
  void baselineFinalText;
  return {
    ok: true,
    schemaVersion: baseProjection.schemaVersion,
    sourceMode: docxReviewPreviewSessionDetailString(baseProjection.sourceMode),
    authorityCarrier: verifiedCarrier,
    exactAuthority: verifiedCarrier.exactAuthority,
    reviewIr: baseProjection,
    packageInventory: cloneJsonSafe(packet?.packageInventory) || {},
    supportedSemanticDigest: docxReviewPreviewSessionDetailString(packet?.projectionDigest),
    parserProfileDigest: docxReviewPreviewSessionDetailString(packet?.workerBuildDigest),
    analysisDigest: docxReviewPreviewSessionDetailString(packet?.projectionDigest),
    expectedAuthority,
  };
}

// EVID-01 (V4): the activation flow reads the preview candidate from the intake
// result. For the packet lane, the candidate is built from the verified packet
// projection; for the legacy-unbound fallback, the candidate is built inside
// the intake (single parse). Either way, no reparse occurs downstream.

async function inspectDocxReviewReturnIntakeV2({
  context,
  docxBytes,
  revisionBridge,
  options = {},
} = {}) {
  revisionBridgeGlobal = revisionBridge;
  const returnedArtifactSha256 = `sha256:${sha256DocxReviewPreviewSessionBytes(docxBytes)}`;
  // EVID-01 (V3): single bounded parse per artifact. The worker is spawned
  // ONCE (probe + verify lanes merged). The message carries the artifact
  // identity + effective budgets but NO secret; the worker emits an
  // unverifiedCarrierEvidence packet that main verifies.
  const probe = await runDocxReviewReturnIntakeParserV2InUtilityProcess({
    bytes: docxBytes,
    returnedArtifactSha256,
    budgets: docxReviewReturnIntakeProductBudgets(options),
    requestId: docxReviewPreviewSessionDetailString(context?.requestId),
  }, revisionBridge, options);
  // EVID-01 (legacy-unbound fallback): when the strict transport analysis
  // blocks on a package that carries no review-authority carrier (e.g. a
  // minimal DOCX without [Content_Types].xml), the intake falls back to the
  // legacy-unbound preview path. The preview candidate is built here, inside
  // the intake, via the tolerant bytes-based builder — a single bounded parse
  // that the activation flow reuses (no reparse downstream, V4 holds). This
  // preserves the existing happy path for ordinary review DOCX fixtures.
  if (!probe.ok) {
    if (!shouldUseLegacyDocxReviewPreviewFallbackForProbe(probe)) {
      return probe;
    }
    const fallbackCandidate = typeof revisionBridge?.buildDocxReviewPreviewSessionCandidateFromZipBytes === 'function'
      ? safeBuildDocxReviewPreviewSessionCandidateFromZipBytes(docxBytes, {
        targetScope: isPlainObjectValue(context?.targetScope) ? context.targetScope : undefined,
        createdAt: docxReviewPreviewSessionDetailString(context?.createdAt),
      })
      : null;
    if (isPlainObjectValue(fallbackCandidate) && (fallbackCandidate.status === 'ready' || fallbackCandidate.status === 'diagnostics')) {
      return {
        ok: true,
        status: 'legacy-unbound-review-preview',
        authenticated: false,
        legacyCandidate: fallbackCandidate,
        parserResult: {},
        returnedArtifactSha256,
        utilityProcess: probe.utilityProcess,
        canOpenReviewSession: true,
        canAutoApply: false,
        canImportMutate: false,
        canWriteStorage: false,
      };
    }
    return probe;
  }
  // EVID-01 (V7): typed forged-packet rejection. Verify schema + artifact
  // digest + packetDigest before any downstream consumption. A tampered or
  // mismatched packet is rejected with RTK_RETURN_EVIDENCE_* and zero
  // downstream. Legacy spy paths that return { ok, parserResult } (no packet)
  // are tolerated for backwards-compatible test injection and wrapped here.
  const probePacket = resolveReturnEvidencePacketFromProbe(probe, {
    revisionBridge,
    returnedArtifactSha256,
    requestId: docxReviewPreviewSessionDetailString(context?.requestId),
  });
  if (probePacket.ok !== true) return probePacket;
  const packet = probePacket.packet;
  const packetVerify = revisionBridge.verifyReturnEvidencePacketV1(packet, {
    expectedArtifactSha256: returnedArtifactSha256,
  });
  if (!packetVerify.ok) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_EVIDENCE_PACKET_INVALID', {
      verifyDetail: docxReviewPreviewSessionDetailString(packetVerify.detail),
      expectedArtifactSha256: returnedArtifactSha256,
      actualArtifactSha256: docxReviewPreviewSessionDetailString(packet.artifactSha256),
    });
  }
  const probeResult = isPlainObjectValue(probe.parserResult) ? probe.parserResult : {};
  const carrierStatus = docxReviewPreviewSessionDetailString(packet.unverifiedCarrierEvidence?.status);
  if (carrierStatus === 'missing') {
    return {
      ok: true,
      status: 'legacy-unbound-review-preview',
      authenticated: false,
      packet,
      parserResult: probeResult,
      returnedArtifactSha256,
      utilityProcess: probe.utilityProcess,
      canOpenReviewSession: true,
      canAutoApply: false,
      canImportMutate: false,
      canWriteStorage: false,
    };
  }
  const selectedCarrier = isPlainObjectValue(packet.unverifiedCarrierEvidence?.selectedCarrier)
    ? packet.unverifiedCarrierEvidence.selectedCarrier
    : {};
  const payload = isPlainObjectValue(selectedCarrier.payload) ? selectedCarrier.payload : {};
  const roundId = docxReviewPreviewSessionDetailString(payload.roundId);
  if (!roundId) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_AUTHORITY_CARRIER_INVALID');
  }
  const store = readActiveDocxReviewReturnAuthorityStore(options);
  const localAuthority = findDocxReviewReturnIntakeRoundAuthority(store, roundId);
  if (!localAuthority) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_FOREIGN_OR_EXPIRED_ROUND', { roundId });
  }
  // ROUND-01 (V3): lifecycle gate typed block (RTK_ROUND_NOT_OPEN_FOR_RETURN /
  // RTK_ROUND_LIFECYCLE_NOT_ELIGIBLE) from findDocxReviewReturnIntakeRoundAuthority.
  if (localAuthority.ok === false) {
    return docxReviewReturnIntakeBlocked(docxReviewPreviewSessionDetailString(localAuthority.code), {
      roundId,
      lifecycleState: docxReviewPreviewSessionDetailString(localAuthority.lifecycleState),
    });
  }
  const expectedAuthority = isPlainObjectValue(localAuthority.expectedAuthority)
    ? cloneJsonSafe(localAuthority.expectedAuthority) || {}
    : {};
  // ROUND-01 (V3): resolve the secret via the main-process-only vault using the
  // opaque keyRef (never from the durable record). REVOKED/LOST key states block
  // automatic apply but preview/manuscript read stays available; here the
  // return-intake verification still proceeds because it is a verify-only path.
  const roundKeyRef = docxReviewPreviewSessionDetailString(localAuthority.keyRef);
  const roundKeyHandle = await resolveDocxReviewRoundKeyHandle(roundKeyRef);
  const hmacSecret = roundKeyHandle && typeof roundKeyHandle.hmacSecret === 'function'
    ? docxReviewPreviewSessionDetailString(roundKeyHandle.hmacSecret())
    : '';
  if (!hmacSecret || !isPlainObjectValue(expectedAuthority)) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_LOCAL_SECRET_REQUIRED', { roundId });
  }
  // EVID-01 (V3): YRTK2 binding is verified in main from the packet's
  // yrtk2Evidence (carried by the secret-free worker), NOT from a main-side
  // DOCX ZIP re-extract.
  const yrtk2Evidence = isPlainObjectValue(packet.returnedProjection?.yrtk2Evidence)
    ? packet.returnedProjection.yrtk2Evidence
    : {};
  const yrtk2Verification = verifyDocxReviewReturnYrtk2Binding({
    localAuthority,
    revisionBridge,
    hmacSecret,
    returnedArtifactSha256,
    yrtk2Evidence,
  });
  if (!yrtk2Verification.ok) return yrtk2Verification;
  // EVID-01 (V2 security): the worker emitted unverifiedCarrierEvidence. Main
  // re-verifies the carrier HMAC signature with the local secret (the worker
  // never had it) BEFORE upgrading to verified-baseline-bound. Missing raw
  // carrier encoding, missing verifier capability, tampering, or locator
  // mismatch all fail closed before any product import/apply authority.
  const carrierEncoded = docxReviewPreviewSessionDetailString(selectedCarrier?.encoded);
  if (!carrierEncoded) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_AUTHORITY_CARRIER_ENCODED_REQUIRED', {
      roundId,
      carrierStatus,
    });
  }
  if (typeof revisionBridge.verifyAuthorityCarrierSignatureWithSecret !== 'function') {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_AUTHORITY_CARRIER_VERIFIER_REQUIRED', {
      roundId,
      carrierStatus,
    });
  }
  const carrierHmacVerify = revisionBridge.verifyAuthorityCarrierSignatureWithSecret(
    selectedCarrier,
    { hmacSecret, expectedAuthority },
    createRtkReviewTransportCryptoPort(),
  );
  if (!carrierHmacVerify || !carrierHmacVerify.verified || !carrierHmacVerify.validSignedLocator) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_AUTHORITY_NOT_VERIFIED', {
      carrierHmacVerified: carrierHmacVerify?.verified === true,
      carrierHmacValidSignedLocator: carrierHmacVerify?.validSignedLocator === true,
      carrierReasons: Array.isArray(carrierHmacVerify?.reasons) ? carrierHmacVerify.reasons.slice(0, 8) : [],
    });
  }
  // EVID-01 (V2): the worker emitted unverifiedCarrierEvidence. Main now
  // upgrades it to a verified verdict by combining the verified YRTK2 binding
  // + the verified carrier HMAC + the local authority + the packet carrier
  // evidence.
  const verifiedParserResult = upgradePacketToVerifiedParserResult(packet, {
    localAuthority,
    yrtk2Verification,
    carrierHmacVerify,
    baselineFinalText: typeof localAuthority.baselineFinalText === 'string'
      ? localAuthority.baselineFinalText
      : (typeof context?.sceneText === 'string' ? context.sceneText : ''),
  });
  if (
    verifiedParserResult.authorityCarrier?.status !== 'verified-baseline-bound'
    || verifiedParserResult.exactAuthority?.validSignedLocator !== true
  ) {
    return docxReviewReturnIntakeBlocked('RTK_RETURN_INTAKE_AUTHORITY_NOT_VERIFIED', {
      authorityCarrierStatus: docxReviewPreviewSessionDetailString(verifiedParserResult.authorityCarrier?.status),
    });
  }
  const localBinding = verifyDocxReviewReturnIntakeLocalBinding({
    context,
    localAuthority,
    parserResult: verifiedParserResult,
  });
  if (!localBinding.ok) return localBinding;
  // ROUND-01 (V3): build the session-time capsule WITH the vault-resolved
  // hmacSecret so the downstream full-manuscript return-router proof binding
  // can compute its HMAC during the live session. The secret lives only in
  // this in-memory capsule; the DURABLE authority store never persists it.
  const localAuthorityCapsule = buildDocxReviewReturnIntakeLocalAuthorityCapsule(
    localAuthority,
    verifiedParserResult,
    { hmacSecret },
  );
  if (localAuthorityCapsule?.ok === false) return localAuthorityCapsule;
  return {
    ok: true,
    status: 'authenticated-return-ir-ready',
    authenticated: true,
    packet,
    parserResult: verifiedParserResult,
    returnedArtifactSha256,
    localAuthorityCapsule,
    yrtk2Verification,
    utilityProcess: probe.utilityProcess,
    canOpenReviewSession: true,
    canAutoApply: false,
    canImportMutate: false,
    canWriteStorage: false,
  };
}

async function handleDocxReviewPreviewSessionActivationCommandSurface(payload = {}, options = {}) {
  const decoded = decodeDocxIntakeGateBufferSource(payload);
  if (!decoded.ok) {
    return makeDocxReviewPreviewSessionTypedError(
      decoded.error?.code || 'E_DOCX_REVIEW_PREVIEW_SESSION_PAYLOAD_INVALID',
      decoded.error?.reason || 'DOCX_REVIEW_PREVIEW_SESSION_PAYLOAD_INVALID',
      decoded.error?.details,
    );
  }
  const requestId = normalizeDocxIntakeGateRequestId(payload?.requestId);
  const requestDigestGate = activeDocxActivationRequestDigestGuard.check({
    requestId,
    bytes: decoded.bytes,
  });
  if (!requestDigestGate.ok) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_REQUEST_PAYLOAD_CONFLICT',
      requestDigestGate.reason || 'RTK_DOCX_ACTIVATION_DUPLICATE_REQUEST_MUTATED_PAYLOAD',
      {
        requestId,
        priorDigest: requestDigestGate.priorDigest || '',
        artifactDigest: requestDigestGate.artifactDigest || '',
      },
    );
  }

  const context = await buildDocxReviewPreviewSessionMainContext(options);
  if (!context.ok) {
    return makeDocxReviewPreviewSessionTypedError(
      context.code || 'E_DOCX_REVIEW_PREVIEW_SESSION_CONTEXT_BLOCKED',
      context.reason || 'DOCX_REVIEW_PREVIEW_SESSION_CONTEXT_BLOCKED',
      context.details,
    );
  }

  let revisionBridge = null;
  try {
    revisionBridge = await loadRevisionBridgeModule();
  } catch (error) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_UNAVAILABLE',
      'DOCX_REVIEW_PREVIEW_SESSION_BRIDGE_UNAVAILABLE',
      {
        message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
      },
    );
  }
  if (!revisionBridge || typeof revisionBridge.buildDocxReviewPreviewSessionCandidateFromZipBytes !== 'function') {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_UNAVAILABLE',
      'DOCX_REVIEW_PREVIEW_SESSION_BUILDER_UNAVAILABLE',
    );
  }

  const returnIntake = await inspectDocxReviewReturnIntakeV2({
    context,
    docxBytes: decoded.bytes,
    revisionBridge,
    options,
  });
  if (!returnIntake.ok) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_RETURN_INTAKE_BLOCKED',
      docxReviewPreviewSessionDetailString(returnIntake.reason)
        || 'RTK_RETURN_INTAKE_BLOCKED',
      isPlainObjectValue(returnIntake.details) ? returnIntake.details : undefined,
    );
  }
  const activeContext = returnIntake.authenticated === true
    ? {
      ...context,
      reviewTransportAuthorityCapsule: returnIntake.localAuthorityCapsule,
      reviewTransportReturnIntake: returnIntake,
    }
    : {
      ...context,
      reviewTransportReturnIntake: returnIntake,
    };
  const authenticatedFullManuscriptReturn = returnIntake.authenticated === true
    && returnIntake.localAuthorityCapsule?.scope === 'full-manuscript';
  const authenticatedFullManuscriptExportMap = authenticatedFullManuscriptReturn
    && isPlainObjectValue(returnIntake.localAuthorityCapsule?.authenticatedFullManuscriptExportMap)
    && returnIntake.localAuthorityCapsule?.exportMapAuthority === 'main-owned-active-export-authority-store-after-return-authentication'
    && returnIntake.localAuthorityCapsule?.returnedArtifactExportMapAccepted === false
    ? returnIntake.localAuthorityCapsule.authenticatedFullManuscriptExportMap
    : null;
  if (authenticatedFullManuscriptReturn && !authenticatedFullManuscriptExportMap) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_EXPORT_MAP_REQUIRED',
      'RTK_RETURN_INTAKE_LOCAL_FULL_MANUSCRIPT_EXPORT_MAP_REQUIRED',
    );
  }

  let candidate = null;
  try {
    // EVID-01 (V4): the preview candidate is built from the verified packet
    // projection (returnedProjection), NOT from a raw DOCX ZIP reparse. The
    // packet already carries the immutable ReviewIR; consuming it here is the
    // single bounded parse per artifact. The legacy-unbound fallback path
    // carries a candidate built inside the intake (also a single parse); both
    // paths avoid a downstream reparse of the artifact.
    const legacyCandidate = isPlainObjectValue(returnIntake.legacyCandidate)
      ? returnIntake.legacyCandidate
      : null;
    if (legacyCandidate) {
      candidate = legacyCandidate;
    } else {
      const evidencePacket = isPlainObjectValue(returnIntake.packet) ? returnIntake.packet : null;
      if (!evidencePacket) {
        return makeDocxReviewPreviewSessionTypedError(
          'E_DOCX_REVIEW_PREVIEW_SESSION_BUILD_FAILED',
          'RTK_RETURN_EVIDENCE_PACKET_REQUIRED_FOR_PREVIEW',
        );
      }
      candidate = revisionBridge.buildDocxReviewPreviewSessionCandidateFromEvidence(evidencePacket, {
        targetScope: activeContext.targetScope,
        createdAt: activeContext.createdAt,
        fullManuscriptExportMap: authenticatedFullManuscriptExportMap,
      });
    }
  } catch (error) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_BUILD_FAILED',
      'DOCX_REVIEW_PREVIEW_SESSION_BUILD_FAILED',
      {
        message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
      },
    );
  }

  const isReadyPreviewCandidate = isPlainObjectValue(candidate)
    && candidate.status === 'ready'
    && isPlainObjectValue(candidate.reviewPacket);
  const isDiagnosticEvidenceCandidate = isPlainObjectValue(candidate)
    && candidate.status === 'diagnostics'
    && isPlainObjectValue(candidate.reviewPacket)
    && Array.isArray(candidate.reviewPacket.diagnosticItems)
    && candidate.reviewPacket.diagnosticItems.length > 0;

  if (!isReadyPreviewCandidate && !isDiagnosticEvidenceCandidate) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_NO_CANDIDATE',
      docxReviewPreviewSessionDetailString(candidate?.reason) || 'DOCX_REVIEW_PREVIEW_SESSION_NO_CANDIDATE',
      {
        candidateSummary: summarizeDocxReviewPreviewSessionCandidate(candidate),
      },
    );
  }
  const hasForbiddenAuthority = candidate.canAutoApply !== false
    || candidate.canImportMutate !== false
    || candidate.canWriteStorage !== false
    || (isReadyPreviewCandidate && candidate.canOpenReviewSession !== true)
    || (isDiagnosticEvidenceCandidate && candidate.canOpenReviewSession !== false);
  if (hasForbiddenAuthority) {
    return makeDocxReviewPreviewSessionTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_FORBIDDEN_AUTHORITY',
      'DOCX_REVIEW_PREVIEW_SESSION_FORBIDDEN_AUTHORITY',
    );
  }

  const importPayload = buildDocxReviewPreviewSessionImportPayload(activeContext, candidate, requestId);
  const importResult = await handleReviewSurfaceImportPacketCommandSurface(importPayload);
  if (!importResult || importResult.ok !== true) {
    const nestedError = isPlainObjectValue(importResult?.error) ? importResult.error : {};
    return makeDocxReviewPreviewSessionTypedError(
      docxReviewPreviewSessionDetailString(nestedError.code) || 'E_DOCX_REVIEW_PREVIEW_SESSION_IMPORT_FAILED',
      docxReviewPreviewSessionDetailString(nestedError.reason) || 'DOCX_REVIEW_PREVIEW_SESSION_IMPORT_FAILED',
      isPlainObjectValue(nestedError.details) ? nestedError.details : undefined,
    );
  }
  const commentShadowPayload = buildDocxReviewPreviewSessionCommentShadowPayload(activeContext, candidate, requestId, revisionBridge);
  let commentShadowResult = null;
  if (commentShadowPayload) {
    commentShadowResult = await dispatchCommandSurfaceKernel(
      'cmd.rtk.reviewSession.importComments',
      commentShadowPayload,
    );
  }
  const commentProductPath = commentShadowPayload
    ? await applyAuthenticatedDocxCommentProductPath({
      context: activeContext,
      commentShadowPayload,
      requestId,
      revisionBridge,
      explicitCanonicalApplyConfirmed: payload?.explicitCanonicalApplyConfirmed === true,
    })
    : null;
  const nonOverlapTrackedReplacementProductPath =
    await prepareDocxReviewPreviewSessionNonOverlapTrackedReplacementProductPath({
      context: activeContext,
      candidate,
      requestId,
      docxBytes: decoded.bytes,
      revisionBridge,
      options,
    });
  const formattingProductPath = prepareAuthenticatedDocxFormattingReturnProductPath({
    context: activeContext,
    requestId,
    docxBytes: decoded.bytes,
    revisionBridge,
    fullManuscriptExportMap: authenticatedFullManuscriptExportMap,
    budgets: docxReviewReturnIntakeProductBudgets(options),
  });
  const structuralProductPath = prepareAuthenticatedDocxStructuralReturnProductPath({
    context: activeContext,
    requestId,
    docxBytes: decoded.bytes,
    revisionBridge,
    fullManuscriptExportMap: authenticatedFullManuscriptExportMap,
    budgets: docxReviewReturnIntakeProductBudgets(options),
  });
  const reviewSurface = isPlainObjectValue(formattingProductPath?.reviewSurface)
    && Object.keys(formattingProductPath.reviewSurface).length > 0
    ? formattingProductPath.reviewSurface
    : isPlainObjectValue(structuralProductPath?.reviewSurface)
      && Object.keys(structuralProductPath.reviewSurface).length > 0
    ? structuralProductPath.reviewSurface
    : isPlainObjectValue(nonOverlapTrackedReplacementProductPath?.reviewSurface)
    ? nonOverlapTrackedReplacementProductPath.reviewSurface
    : importResult.reviewSurface;

  const result = assertDocxReviewPreviewSessionActivationResult({
    ok: true,
    commandId: DOCX_REVIEW_PREVIEW_SESSION_COMMAND_ID,
    requestId,
    activated: true,
    diagnosticOnly: isDiagnosticEvidenceCandidate,
    session: importResult.session,
    reviewSurface,
    commentShadowSession: isPlainObjectValue(commentShadowResult?.session)
      ? cloneJsonSafe(commentShadowResult.session)
      : null,
    commentShadowResult: isPlainObjectValue(commentShadowResult)
      ? {
        ok: commentShadowResult.ok === true,
        status: docxReviewPreviewSessionDetailString(commentShadowResult.status),
        code: docxReviewPreviewSessionDetailString(commentShadowResult.code || commentShadowResult.error?.code),
        reason: docxReviewPreviewSessionDetailString(commentShadowResult.reason || commentShadowResult.error?.reason),
        writerCalled: commentShadowResult.writerCalled === true,
        manuscriptApplyAuthority: commentShadowResult.manuscriptApplyAuthority === true,
        storageEffects: isPlainObjectValue(commentShadowResult.storageEffects)
          ? cloneJsonSafe(commentShadowResult.storageEffects)
          : null,
      }
      : null,
    commentProductPath: isPlainObjectValue(commentProductPath) ? cloneJsonSafe(commentProductPath) : null,
    nonOverlapTrackedReplacementProductPath: isPlainObjectValue(nonOverlapTrackedReplacementProductPath)
      ? {
        prepared: nonOverlapTrackedReplacementProductPath.prepared === true,
        status: docxReviewPreviewSessionDetailString(nonOverlapTrackedReplacementProductPath.status),
        reason: docxReviewPreviewSessionDetailString(nonOverlapTrackedReplacementProductPath.reason),
        writerCalled: nonOverlapTrackedReplacementProductPath.writerCalled === true,
        rendererAuthority: nonOverlapTrackedReplacementProductPath.rendererAuthority === true,
        authorityAgreement: nonOverlapTrackedReplacementProductPath.authorityAgreement === true,
        sceneCount: Number.isSafeInteger(nonOverlapTrackedReplacementProductPath.sceneCount)
          ? nonOverlapTrackedReplacementProductPath.sceneCount
          : 0,
        exactAuthorityDigests: Array.isArray(nonOverlapTrackedReplacementProductPath.exactAuthorityDigests)
          ? nonOverlapTrackedReplacementProductPath.exactAuthorityDigests
            .map(docxReviewPreviewSessionDetailString)
            .filter(Boolean)
          : [],
        runtimePreviewCode: docxReviewPreviewSessionDetailString(nonOverlapTrackedReplacementProductPath.runtimePreview?.code),
        runtimePreviewReasons: Array.isArray(nonOverlapTrackedReplacementProductPath.runtimePreview?.reasons)
          ? nonOverlapTrackedReplacementProductPath.runtimePreview.reasons
            .filter(isPlainObjectValue)
            .map((item) => ({
              code: docxReviewPreviewSessionDetailString(item.code),
              field: docxReviewPreviewSessionDetailString(item.field),
            }))
            .filter((item) => item.code)
            .slice(0, 12)
          : [],
      }
      : null,
    formattingProductPath: isPlainObjectValue(formattingProductPath)
      ? {
        prepared: formattingProductPath.prepared === true,
        status: docxReviewPreviewSessionDetailString(formattingProductPath.status),
        code: docxReviewPreviewSessionDetailString(formattingProductPath.code),
        candidateCount: Number.isSafeInteger(formattingProductPath.candidateCount)
          ? formattingProductPath.candidateCount
          : 0,
        sceneCount: Number.isSafeInteger(formattingProductPath.sceneCount)
          ? formattingProductPath.sceneCount
          : 0,
        diagnosticCount: Number.isSafeInteger(formattingProductPath.diagnosticCount)
          ? formattingProductPath.diagnosticCount
          : 0,
        writerCalled: formattingProductPath.writerCalled === true,
        rendererAuthority: formattingProductPath.rendererAuthority === true,
      }
      : null,
    structuralProductPath: isPlainObjectValue(structuralProductPath)
      ? {
        prepared: structuralProductPath.prepared === true,
        status: docxReviewPreviewSessionDetailString(structuralProductPath.status),
        code: docxReviewPreviewSessionDetailString(structuralProductPath.code),
        candidateCount: Number.isSafeInteger(structuralProductPath.candidateCount)
          ? structuralProductPath.candidateCount
          : 0,
        sceneCount: Number.isSafeInteger(structuralProductPath.sceneCount)
          ? structuralProductPath.sceneCount
          : 0,
        diagnosticCount: Number.isSafeInteger(structuralProductPath.diagnosticCount)
          ? structuralProductPath.diagnosticCount
          : 0,
        writerCalled: structuralProductPath.writerCalled === true,
        rendererAuthority: structuralProductPath.rendererAuthority === true,
      }
      : null,
    candidateSummary: summarizeDocxReviewPreviewSessionCandidate(candidate),
    returnIntake: sanitizeDocxReviewReturnIntakeForResult(returnIntake),
    sourcePacketHash: importPayload.sourcePacketHash,
    canOpenReviewSession: candidate.canOpenReviewSession === true,
    canCreateReviewPacket: candidate.canCreateReviewPacket === true,
    canAutoApply: false,
    canImportMutate: false,
    canWriteStorage: false,
  });
  if (result && result.ok === true && result.activated === true) {
    activeDocxActivationRequestDigestGuard.remember({ requestId, bytes: decoded.bytes });
  }
  return result;
}
// DOCX_REVIEW_PREVIEW_SESSION_COMMAND_SURFACE_END

async function handleReviewSurfaceApplyFormattingReturnCommandSurface(payload = {}) {
  const unsupportedKeys = Object.keys(isPlainObjectValue(payload) ? payload : {})
    .filter((key) => !['requestId'].includes(key));
  if (!isPlainObjectValue(payload) || unsupportedKeys.length > 0) {
    return makeReviewMutateTypedError(
      'cmd.project.review.applyFormattingReturn',
      'E_RTK_FORMATTING_RETURN_UI_PAYLOAD_INVALID',
      'RTK_FORMATTING_RETURN_UI_PAYLOAD_INVALID',
      { unsupportedKeys },
    );
  }
  const actionRequestId = docxReviewPreviewSessionDetailString(payload.requestId);
  if (!actionRequestId) {
    return makeReviewMutateTypedError(
      'cmd.project.review.applyFormattingReturn',
      'E_RTK_FORMATTING_RETURN_ACTION_REQUEST_REQUIRED',
      'RTK_FORMATTING_RETURN_ACTION_REQUEST_REQUIRED',
    );
  }
  return queueDiskOperation(async () => {
    if (activeReviewSessionDirtyImportBlocked || isDirty || autoSaveInProgress) {
      return makeReviewMutateTypedError(
        'cmd.project.review.applyFormattingReturn',
        'E_RTK_FORMATTING_RETURN_DIRTY_EDITOR_BLOCKED',
        'RTK_FORMATTING_RETURN_DIRTY_EDITOR_BLOCKED',
        {
          dirtyAtImportStart: Boolean(activeReviewSessionDirtyImportBlocked),
          isDirty: Boolean(isDirty),
          autoSaveInProgress: Boolean(autoSaveInProgress),
        },
      );
    }
    if (!rtkFormattingReturnStoreMatchesActiveSession()) {
      return makeReviewMutateTypedError(
        'cmd.project.review.applyFormattingReturn',
        'E_RTK_FORMATTING_RETURN_MAIN_STORE_UNAVAILABLE',
        'RTK_FORMATTING_RETURN_MAIN_STORE_UNAVAILABLE',
      );
    }
    const input = cloneJsonSafe(activeRtkFormattingReturnApplyStore.input) || {};
    const applied = await dispatchCommandSurfaceKernel(
      COMMAND_SURFACE_KERNEL_COMMAND_IDS.RTK_REVIEW_APPLY_MULTI_SCENE_FORMATTING_RETURN,
      input,
    );
    if (!isPlainObjectValue(applied) || !['applied', 'replay'].includes(applied.status)) {
      const reviewSurface = attachRtkFormattingReturnProductResult(applied, null);
      const bridgeReviewSurface = makeFormattingReturnBridgeReviewSurface(reviewSurface);
      return {
        ok: false,
        type: 'yalken.rtk.formattingReturnUiApply',
        status: 'blocked',
        code: docxReviewPreviewSessionDetailString(applied?.code || applied?.error?.code)
          || 'RTK_FORMATTING_RETURN_APPLY_BLOCKED',
        reason: docxReviewPreviewSessionDetailString(applied?.reason || applied?.error?.reason)
          || 'RTK_FORMATTING_RETURN_APPLY_BLOCKED',
        reviewSurface: bridgeReviewSurface,
      };
    }
    const replay = applied.status === 'replay'
      ? applied
      : await dispatchCommandSurfaceKernel(
        COMMAND_SURFACE_KERNEL_COMMAND_IDS.RTK_REVIEW_APPLY_MULTI_SCENE_FORMATTING_RETURN,
        input,
      );
    const replayVerified = replay?.ok === true && replay?.status === 'replay' && replay?.writerCalled !== true;
    const reviewSurface = attachRtkFormattingReturnProductResult(applied, replay);
    const bridgeReviewSurface = makeFormattingReturnBridgeReviewSurface(reviewSurface);
    const currentScenePath = isPlainObjectValue(input.scenePathBySceneId)
      ? Object.values(input.scenePathBySceneId).find((scenePath) => scenePath === currentFilePath)
      : '';
    const editorSync = deferRtkFormattingReturnEditorSyncAfterBridgeReply({
      currentScenePath,
      bridgeReviewSurface,
    });
    return {
      ok: replayVerified,
      type: 'yalken.rtk.formattingReturnUiApply',
      status: replayVerified ? 'applied-and-replayed' : 'blocked',
      code: replayVerified
        ? 'RTK_FORMATTING_RETURN_APPLIED_AND_REPLAYED'
        : 'RTK_FORMATTING_RETURN_REPLAY_NOT_VERIFIED',
      reason: replayVerified
        ? 'RTK_FORMATTING_RETURN_APPLIED_AND_REPLAYED'
        : 'RTK_FORMATTING_RETURN_REPLAY_NOT_VERIFIED',
      applied: applied.status === 'applied' || applied.status === 'replay',
      replayVerified,
      actionRequestId,
      reviewSurface: bridgeReviewSurface,
      editorSync: makeCommandBridgeEditorSyncSummary(editorSync),
    };
  }, 'rtk-formatting-return');
}

// DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_COMMAND_SURFACE_START
const DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_COMMAND_ID = 'cmd.project.review.openDocxReviewPreviewSession';
const DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_ALLOWED_PAYLOAD_KEYS = new Set(['requestId']);
const DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_ALLOWED_SELECTION_KEYS = new Set([
  'path',
  'filePath',
  'name',
  'size',
  'requestId',
  'canceled',
]);

function sanitizeDocxReviewPreviewSessionLocalFileDetails(details) {
  if (!isPlainObjectValue(details)) return {};
  const result = {};
  if (Array.isArray(details.fields)) {
    result.fieldCount = details.fields.filter((item) => typeof item === 'string').length;
  }
  if (Number.isInteger(details.maxBytes)) result.maxBytes = details.maxBytes;
  if (Number.isInteger(details.actualBytes)) result.actualBytes = details.actualBytes;
  if (Number.isInteger(details.byteLength)) result.byteLength = details.byteLength;
  if (Number.isInteger(details.expectedBytes)) result.expectedBytes = details.expectedBytes;
  if (Number.isInteger(details.beforeBytes)) result.beforeBytes = details.beforeBytes;
  if (Number.isInteger(details.afterBytes)) result.afterBytes = details.afterBytes;
  if (typeof details.nestedCode === 'string' && details.nestedCode.trim()) {
    result.nestedCode = details.nestedCode.trim();
  }
  if (typeof details.nestedReason === 'string' && details.nestedReason.trim()) {
    result.nestedReason = details.nestedReason.trim();
  }
  if (isPlainObjectValue(details.candidateSummary)) {
    result.candidateSummary = cloneJsonSafe(details.candidateSummary);
  }
  return result;
}

function makeDocxReviewPreviewSessionLocalFileTypedError(code, reason, details = undefined) {
  const error = {
    code,
    op: DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_COMMAND_ID,
    reason,
  };
  const safeDetails = sanitizeDocxReviewPreviewSessionLocalFileDetails(details);
  if (Object.keys(safeDetails).length > 0) {
    error.details = safeDetails;
  }
  return { ok: false, error };
}

function normalizeDocxReviewPreviewSessionLocalFileRequestId(value) {
  return typeof value === 'string' && value.trim()
    ? value.trim()
    : 'docx-review-preview-session-local-file-request';
}

async function pickDocxReviewPreviewSessionLocalFile(options = {}) {
  const dialogResult = await dialog.showOpenDialog(mainWindow, {
    title: 'Open DOCX Review',
    defaultPath: fileManager.getDocumentsPath(),
    filters: [{ name: 'DOCX', extensions: ['docx'] }],
    properties: ['openFile'],
  });

  if (!dialogResult || dialogResult.canceled === true) {
    return { canceled: true };
  }

  const filePath = Array.isArray(dialogResult.filePaths) && typeof dialogResult.filePaths[0] === 'string'
    ? dialogResult.filePaths[0].trim()
    : '';
  if (!filePath) {
    return {};
  }

  let size = null;
  try {
    const stat = await fs.stat(filePath);
    if (stat && typeof stat.isFile === 'function' && stat.isFile()) {
      size = Number.isFinite(stat.size) && stat.size >= 0 ? Math.floor(stat.size) : null;
    }
  } catch {}

  return {
    path: filePath,
    name: path.basename(filePath),
    size,
    requestId: normalizeDocxReviewPreviewSessionLocalFileRequestId(options.requestId),
  };
}

function validateDocxReviewPreviewSessionLocalFileSelection(selection, requestId) {
  if (!isPlainObjectValue(selection)) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_INVALID',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_INVALID',
    );
  }

  const unsupportedKeys = Object.keys(selection)
    .filter((key) => !DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_ALLOWED_SELECTION_KEYS.has(key))
    .sort();
  if (unsupportedKeys.length > 0) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_INVALID',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_UNSUPPORTED_FIELDS',
      { fields: unsupportedKeys },
    );
  }

  const filePath = typeof selection.path === 'string' && selection.path.trim()
    ? selection.path.trim()
    : typeof selection.filePath === 'string' && selection.filePath.trim()
      ? selection.filePath.trim()
      : '';
  if (!filePath) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_INVALID',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_FILE_REQUIRED',
    );
  }
  if (path.extname(filePath).toLowerCase() !== '.docx') {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_INVALID',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_DOCX_REQUIRED',
    );
  }

  const size = Number.isFinite(selection.size) && selection.size >= 0
    ? Math.floor(selection.size)
    : null;
  if (size === null) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_INVALID',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SIZE_REQUIRED',
    );
  }
  if (size > DOCX_INTAKE_GATE_MAX_BYTES) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_TOO_LARGE',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_TOO_LARGE',
      {
        maxBytes: DOCX_INTAKE_GATE_MAX_BYTES,
        actualBytes: size,
      },
    );
  }

  return {
    ok: true,
    value: {
      path: filePath,
      name: typeof selection.name === 'string' && selection.name.trim()
        ? path.basename(selection.name.trim())
        : path.basename(filePath),
      size,
      requestId,
    },
  };
}

async function readDocxReviewPreviewSessionLocalFileBytes(selection) {
  if (!isPlainObjectValue(selection) || typeof selection.path !== 'string' || !selection.path.trim()) {
    throw new TypeError('DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_SELECTION_INVALID');
  }
  const loaded = await readExternalFileBounded(selection.path.trim(), {
    projectRoot: getProjectRootPath(),
    allowedExtensions: ['.docx'],
    maxBytes: DOCX_INTAKE_GATE_MAX_BYTES,
    expectedBytes: Number.isInteger(selection.size) ? selection.size : undefined,
  });
  return loaded.bytes;
}

async function handleDocxReviewPreviewSessionLocalFileCommandSurface(payload = {}, options = {}) {
  const safePayload = isPlainObjectValue(payload) ? payload : {};
  const unsupportedPayloadKeys = Object.keys(safePayload)
    .filter((key) => !DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_ALLOWED_PAYLOAD_KEYS.has(key))
    .sort();
  if (unsupportedPayloadKeys.length > 0) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_PAYLOAD_INVALID',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_PAYLOAD_UNSUPPORTED_FIELDS',
      { fields: unsupportedPayloadKeys },
    );
  }

  const requestId = normalizeDocxReviewPreviewSessionLocalFileRequestId(safePayload.requestId);
  const pickLocalFile = typeof options.pickLocalFile === 'function'
    ? options.pickLocalFile
    : pickDocxReviewPreviewSessionLocalFile;
  const readLocalFileBytes = typeof options.readLocalFileBytes === 'function'
    ? options.readLocalFileBytes
    : readDocxReviewPreviewSessionLocalFileBytes;

  let selectedFile;
  try {
    selectedFile = await pickLocalFile({ requestId });
  } catch {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_PICK_FAILED',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_PICK_FAILED',
    );
  }

  if (selectedFile && selectedFile.canceled === true) {
    return {
      ok: true,
      commandId: DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_COMMAND_ID,
      requestId,
      activated: false,
      cancelled: true,
    };
  }

  const selection = validateDocxReviewPreviewSessionLocalFileSelection(selectedFile, requestId);
  if (!selection.ok) {
    return selection;
  }

  let bytes;
  try {
    bytes = await readLocalFileBytes(selection.value);
  } catch (error) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      typeof error?.code === 'string' && error.code
        ? error.code
        : 'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_READ_FAILED',
      typeof error?.reason === 'string' && error.reason
        ? error.reason
        : 'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_READ_FAILED',
      isPlainObjectValue(error?.details) ? error.details : undefined,
    );
  }

  const buffer = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes || []);
  if (buffer.length === 0) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_BYTES_INVALID',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_BYTES_EMPTY',
    );
  }
  if (buffer.length > DOCX_INTAKE_GATE_MAX_BYTES) {
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_TOO_LARGE',
      'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_TOO_LARGE',
      {
        maxBytes: DOCX_INTAKE_GATE_MAX_BYTES,
        actualBytes: buffer.length,
      },
    );
  }

  const activationResult = await handleDocxReviewPreviewSessionActivationCommandSurface({
    requestId,
    bufferSource: buffer.toString('base64'),
  }, options);
  if (!activationResult || activationResult.ok !== true) {
    const nestedError = isPlainObjectValue(activationResult?.error) ? activationResult.error : {};
    const nestedDetails = isPlainObjectValue(nestedError.details) ? nestedError.details : {};
    return makeDocxReviewPreviewSessionLocalFileTypedError(
      docxReviewPreviewSessionDetailString(nestedError.code)
        || 'E_DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_ACTIVATION_FAILED',
      docxReviewPreviewSessionDetailString(nestedError.reason)
        || 'DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_ACTIVATION_FAILED',
      {
        nestedCode: docxReviewPreviewSessionDetailString(nestedError.code),
        nestedReason: docxReviewPreviewSessionDetailString(nestedError.reason),
        candidateSummary: isPlainObjectValue(nestedDetails.candidateSummary)
          ? nestedDetails.candidateSummary
          : undefined,
      },
    );
  }

  return {
    ...activationResult,
    commandId: DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_COMMAND_ID,
    requestId,
    fileName: selection.value.name,
    byteLength: buffer.length,
  };
}
// DOCX_REVIEW_PREVIEW_SESSION_LOCAL_FILE_COMMAND_SURFACE_END

// DOCX_CONTENT_PREVIEW_COMMAND_SURFACE_START
const DOCX_CONTENT_PREVIEW_COMMAND_ID = 'cmd.project.docx.previewContent';
const DOCX_CONTENT_PREVIEW_MAX_BYTES = 10 * 1024 * 1024;
const DOCX_CONTENT_PREVIEW_MAX_BASE64_CHARS = Math.ceil(DOCX_CONTENT_PREVIEW_MAX_BYTES / 3) * 4;
const DOCX_CONTENT_PREVIEW_ALLOWED_PAYLOAD_KEYS = new Set(['requestId', 'bufferSource']);
const DOCX_CONTENT_PREVIEW_FORBIDDEN_RESULT_KEYS = new Set([
  ['review', 'Packet'].join(''),
  ['review', 'Surface'].join(''),
  ['parsed', 'Review', 'Surface'].join(''),
  ['active', 'Review', 'Session'].join(''),
  ['preview', 'Input'].join(''),
  ['apply', 'Ops'].join(''),
  ['apply', 'Plan'].join(''),
  ['can', 'Apply'].join(''),
  ['can', 'Create', 'Review', 'Packet'].join(''),
  ['can', 'Preview', 'Apply'].join(''),
  ['can', 'Import', 'Mutate'].join(''),
  ['can', 'Write', 'Storage'].join(''),
  ['write', 'Receipt'].join(''),
  ['import', 'Receipt'].join(''),
  ['export', 'Receipt'].join(''),
  ['raw', 'Bytes'].join(''),
  ['buffer', 'Source'].join(''),
  ['file', 'Path'].join(''),
  'bytes',
  'path',
  'inventory',
  'entries',
]);

function makeDocxContentPreviewTypedError(code, reason, details = undefined) {
  const error = {
    code,
    op: DOCX_CONTENT_PREVIEW_COMMAND_ID,
    reason,
  };
  if (isPlainObjectValue(details) && Object.keys(details).length > 0) {
    error.details = cloneJsonSafe(details);
  }
  return { ok: false, error };
}

function normalizeDocxContentPreviewRequestId(value) {
  return typeof value === 'string' && value.trim()
    ? value.trim()
    : 'docx-content-preview-request';
}

function decodeDocxContentPreviewBufferSource(payload = {}) {
  if (!isPlainObjectValue(payload)) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_INVALID',
      'DOCX_CONTENT_PREVIEW_PAYLOAD_REQUIRED',
    );
  }

  const unsupportedKeys = Object.keys(payload)
    .filter((key) => !DOCX_CONTENT_PREVIEW_ALLOWED_PAYLOAD_KEYS.has(key))
    .sort();
  if (unsupportedKeys.length > 0) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_INVALID',
      'DOCX_CONTENT_PREVIEW_PAYLOAD_UNSUPPORTED_FIELDS',
      {
        fields: unsupportedKeys,
      },
    );
  }

  const bufferSource = typeof payload.bufferSource === 'string'
    ? payload.bufferSource.trim()
    : '';
  if (!bufferSource) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_INVALID',
      'DOCX_CONTENT_PREVIEW_BUFFER_SOURCE_REQUIRED',
    );
  }
  if (bufferSource.length > DOCX_CONTENT_PREVIEW_MAX_BASE64_CHARS) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_TOO_LARGE',
      'DOCX_CONTENT_PREVIEW_BUFFER_SOURCE_TOO_LARGE',
      {
        maxBytes: DOCX_CONTENT_PREVIEW_MAX_BYTES,
      },
    );
  }
  if (bufferSource.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/u.test(bufferSource)) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_INVALID',
      'DOCX_CONTENT_PREVIEW_BUFFER_SOURCE_BASE64_INVALID',
    );
  }

  const bytes = Buffer.from(bufferSource, 'base64');
  if (bytes.length === 0) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_INVALID',
      'DOCX_CONTENT_PREVIEW_BUFFER_SOURCE_EMPTY',
    );
  }
  if (bytes.length > DOCX_CONTENT_PREVIEW_MAX_BYTES) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_TOO_LARGE',
      'DOCX_CONTENT_PREVIEW_BUFFER_SOURCE_TOO_LARGE',
      {
        maxBytes: DOCX_CONTENT_PREVIEW_MAX_BYTES,
        byteLength: bytes.length,
      },
    );
  }
  if (bytes.toString('base64') !== bufferSource) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_PAYLOAD_INVALID',
      'DOCX_CONTENT_PREVIEW_BUFFER_SOURCE_BASE64_INVALID',
    );
  }

  return {
    ok: true,
    bytes,
  };
}

function findDocxContentPreviewForbiddenResultKey(value, pathParts = []) {
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      const nested = findDocxContentPreviewForbiddenResultKey(
        value[index],
        pathParts.concat(String(index)),
      );
      if (nested) return nested;
    }
    return '';
  }
  if (!isPlainObjectValue(value)) return '';

  for (const key of Object.keys(value)) {
    const keyPath = pathParts.concat(key).join('.');
    if (DOCX_CONTENT_PREVIEW_FORBIDDEN_RESULT_KEYS.has(key)) {
      return keyPath;
    }
    const nested = findDocxContentPreviewForbiddenResultKey(value[key], pathParts.concat(key));
    if (nested) return nested;
  }
  return '';
}

function buildDocxContentPreviewCommandResult(payload, previewResult) {
  const previewReport = cloneJsonSafe(previewResult);
  const previewOk = previewReport.ok === true;
  return {
    ok: true,
    requestId: normalizeDocxContentPreviewRequestId(payload?.requestId),
    commandId: DOCX_CONTENT_PREVIEW_COMMAND_ID,
    previewOk,
    previewStatus: typeof previewReport.status === 'string'
      ? previewReport.status
      : previewOk
        ? 'preview'
        : 'blocked',
    previewCode: typeof previewReport.code === 'string'
      ? previewReport.code
      : 'E_DOCX_CONTENT_PREVIEW_UNKNOWN',
    previewReason: typeof previewReport.reason === 'string'
      ? previewReport.reason
      : 'E_DOCX_CONTENT_PREVIEW_UNKNOWN',
    docxContentPreviewReport: previewReport,
  };
}

async function handleDocxContentPreviewCommandSurface(payload = {}) {
  const decoded = decodeDocxContentPreviewBufferSource(payload);
  if (!decoded.ok) return decoded;

  let revisionBridge = null;
  try {
    revisionBridge = await loadRevisionBridgeModule();
  } catch (error) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_UNAVAILABLE',
      'DOCX_CONTENT_PREVIEW_BRIDGE_UNAVAILABLE',
      {
        message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
      },
    );
  }
  if (!revisionBridge || typeof revisionBridge.buildDocxContentPreviewFromZipBytes !== 'function') {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_UNAVAILABLE',
      'DOCX_CONTENT_PREVIEW_HELPER_UNAVAILABLE',
    );
  }

  let previewResult = null;
  try {
    previewResult = revisionBridge.buildDocxContentPreviewFromZipBytes(decoded.bytes);
  } catch (error) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_FAILED',
      'DOCX_CONTENT_PREVIEW_EXECUTION_FAILED',
      {
        message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
      },
    );
  }

  if (!isPlainObjectValue(previewResult)) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_INVALID_RESULT',
      'DOCX_CONTENT_PREVIEW_INVALID_RESULT',
    );
  }

  const forbiddenKey = findDocxContentPreviewForbiddenResultKey(previewResult);
  if (forbiddenKey) {
    return makeDocxContentPreviewTypedError(
      'E_DOCX_CONTENT_PREVIEW_FORBIDDEN_RESULT',
      'DOCX_CONTENT_PREVIEW_FORBIDDEN_RESULT',
      {
        key: forbiddenKey,
      },
    );
  }

  return buildDocxContentPreviewCommandResult(payload, previewResult);
}
// DOCX_CONTENT_PREVIEW_COMMAND_SURFACE_END

