async function normalizeProjectManifest(manifest, projectName = DEFAULT_PROJECT_NAME) {
  const source = isPlainObjectValue(manifest) ? manifest : {};
  const stableProjectId = normalizeStableProjectId(source.projectId);
  const projectId = stableProjectId || createStableProjectId();
  const normalizedProjectName = typeof source.projectName === 'string' && source.projectName.trim().length > 0
    ? source.projectName.trim()
    : sanitizeFilename(projectName);
  const createdAtUtc = typeof source.createdAtUtc === 'string' && source.createdAtUtc.trim().length > 0
    ? source.createdAtUtc.trim()
    : new Date().toISOString();
  let bookProfile;

  if (Object.prototype.hasOwnProperty.call(source, 'bookProfile') && isPlainObjectValue(source.bookProfile)) {
    try {
      const { normalizeBookProfile } = await loadBookProfileModule();
      const normalizedBookProfileResult = normalizeBookProfile(source.bookProfile);
      if (normalizedBookProfileResult.ok) {
        bookProfile = normalizedBookProfileResult.value;
      }
    } catch (error) {
      logDevError('normalizeProjectManifest:bookProfile', error);
    }
  }

  const normalizedManifest = {
    ...canonicalizeComparableValue(source),
    schemaVersion: PROJECT_MANIFEST_SCHEMA_VERSION,
    projectId,
    projectName: normalizedProjectName,
    createdAtUtc,
  };

  if (bookProfile) {
    normalizedManifest.bookProfile = bookProfile;
  } else if (Object.prototype.hasOwnProperty.call(normalizedManifest, 'bookProfile')) {
    delete normalizedManifest.bookProfile;
  }

  return normalizedManifest;
}

async function readProjectManifest(projectName = DEFAULT_PROJECT_NAME) {
  const manifestPath = getProjectManifestPath(projectName);
  try {
    const raw = await fs.readFile(manifestPath, 'utf8');
    const parsed = JSON.parse(raw);
    const sourceManifest = isPlainObjectValue(parsed) ? parsed : null;
    return {
      raw,
      manifest: await normalizeProjectManifest(sourceManifest || {}, projectName),
      sourceManifestComparable: getProjectManifestComparable(sourceManifest)
    };
  } catch {
    return null;
  }
}

async function ensureProjectManifest(projectName = DEFAULT_PROJECT_NAME) {
  const manifestPath = getProjectManifestPath(projectName);
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const existingManifestRecord = await readProjectManifest(projectName);
    const existingManifest = existingManifestRecord ? existingManifestRecord.manifest : null;
    const sourceManifestComparable = existingManifestRecord ? existingManifestRecord.sourceManifestComparable : null;
    const nextManifest = await normalizeProjectManifest(existingManifest || {}, projectName);
    const shouldWrite = !sourceManifestComparable
      || JSON.stringify(sourceManifestComparable) !== JSON.stringify(getProjectManifestComparable(nextManifest));
    const nextText = shouldWrite
      ? JSON.stringify(nextManifest, null, 2)
      : existingManifestRecord.raw;

    if (shouldWrite) {
      const authority = await getMainProjectManifestAuthority();
      try {
        await authority.commitManifestText({
          projectId: nextManifest.projectId,
          targetPath: manifestPath,
          expectedText: existingManifestRecord?.raw ?? null,
          nextText,
          label: 'ensureProjectManifest',
        });
      } catch (error) {
        if (error?.code === 'E_MAIN_PROJECT_MANIFEST_CAS_FAILED' && attempt < 2) continue;
        throw error;
      }
    }

    return {
      manifestPath,
      manifest: nextManifest,
      manifestRaw: nextText,
    };
  }
  throw new Error('PROJECT_MANIFEST_RETRY_EXHAUSTED');
}

async function migrateProjectNotesStorage(options = {}) {
  const { manifestPath, manifest } = await ensureProjectManifest(DEFAULT_PROJECT_NAME);
  const expectedProjectId = normalizeStableProjectId(options.projectId);
  if (expectedProjectId && expectedProjectId !== manifest.projectId) {
    return {
      ok: false,
      code: 'E_NOTES_PROJECT_MISMATCH',
      reason: 'NOTES_PROJECT_MISMATCH',
    };
  }
  const notesStorage = await loadNotesStorageModule();
  const projectRoot = path.dirname(manifestPath);
  return notesStorage.migrateNotesStorage({
    projectRoot,
    projectId: manifest.projectId,
    readFile: fs.readFile,
    writeFileAtomic: (filePath, content) => queueDiskOperation(
      () => fileManager.writeFileAtomic(filePath, content),
      'save project notes storage',
    ),
    ...(typeof options.now === 'function' ? { now: options.now } : {}),
  });
}

async function getProjectNotesContext(payload = {}) {
  const { manifestPath, manifest } = await ensureProjectManifest(DEFAULT_PROJECT_NAME);
  const expectedProjectId = normalizeStableProjectId(payload.projectId);
  if (expectedProjectId && expectedProjectId !== manifest.projectId) {
    return {
      ok: false,
      code: 'E_NOTES_PROJECT_MISMATCH',
      reason: 'NOTES_PROJECT_MISMATCH',
    };
  }
  const notesStorage = await loadNotesStorageModule();
  const projectRoot = path.dirname(manifestPath);
  return {
    ok: true,
    projectRoot,
    projectId: manifest.projectId,
    notesStorage,
  };
}

function makeNotesCommandError(commandId, code, reason, details = {}) {
  return {
    ok: false,
    code,
    op: commandId,
    reason,
    ...(isPlainObjectValue(details) && Object.keys(details).length > 0 ? { details } : {}),
  };
}

async function readProjectNotesDocument(context, options = {}) {
  const current = await context.notesStorage.readNotesStorage({
    projectRoot: context.projectRoot,
    projectId: context.projectId,
    readFile: fs.readFile,
    ...(typeof options.now === 'function' ? { now: options.now } : {}),
  });
  if (!current.ok) {
    return {
      ok: false,
      code: 'E_NOTES_STORAGE_CORRUPT',
      reason: 'NOTES_STORAGE_CORRUPT',
    };
  }
  return { ok: true, current };
}

async function writeProjectNotesDocument(context, current, document, commandId, options = {}) {
  const now = typeof options.now === 'function' ? options.now : () => new Date().toISOString();
  const beforeText = current && typeof current.sourceText === 'string' && current.sourceText.length > 0
    ? current.sourceText
    : `${JSON.stringify(context.notesStorage.buildEmptyNotesDocument(context.projectId, { now }), null, 2)}\n`;
  const notesPath = context.notesStorage.getNotesStoragePath(context.projectRoot);
  const recovery = await context.notesStorage.createNotesRecoverySnapshot({
    projectRoot: context.projectRoot,
    notesPath,
    sourceText: beforeText,
    now,
  });
  const writeResult = await queueDiskOperation(
    () => fileManager.writeFileAtomic(notesPath, `${JSON.stringify(document, null, 2)}\n`),
    'save project notes command',
  );
  if (!writeResult || writeResult.success !== true) {
    return makeNotesCommandError(
      commandId,
      'E_NOTES_STORAGE_WRITE_FAILED',
      'NOTES_STORAGE_WRITE_FAILED',
      { recovery },
    );
  }
  return {
    ok: true,
    recovery,
  };
}

function buildNotesMutationReceipt({ commandId, mutation, result, recovery }) {
  return {
    schemaVersion: 'notes-command-receipt.v1',
    commandId,
    operation: mutation.op,
    noteId: result.noteId,
    documentHash: result.hash,
    recovery: recovery || null,
  };
}

async function runNotesMutationCommand(commandId, payload = {}, mutationInput = {}, options = {}) {
  const context = await getProjectNotesContext(payload);
  if (!context.ok) {
    return makeNotesCommandError(commandId, context.code, context.reason);
  }
  const read = await readProjectNotesDocument(context, options);
  if (!read.ok) {
    return makeNotesCommandError(commandId, read.code, read.reason);
  }
  const mutation = {
    ...mutationInput,
    noteId: typeof payload.noteId === 'string' ? payload.noteId : mutationInput.noteId,
  };
  const result = context.notesStorage.applyNotesMutation(read.current.document, mutation, {
    projectId: context.projectId,
    ...(typeof options.now === 'function' ? { now: options.now } : {}),
  });
  if (!result.ok) {
    return makeNotesCommandError(commandId, result.code, result.reason);
  }
  const written = await writeProjectNotesDocument(context, read.current, result.document, commandId, options);
  if (!written.ok) {
    return written;
  }
  return {
    ok: true,
    note: result.note,
    receipt: buildNotesMutationReceipt({
      commandId,
      mutation,
      result,
      recovery: written.recovery,
    }),
  };
}

async function handleWorkspaceProjectNotesQuery(payload = {}) {
  const context = await getProjectNotesContext(payload);
  if (!context.ok) {
    return makeNotesCommandError('query.projectNotes', context.code, context.reason);
  }
  const read = await readProjectNotesDocument(context);
  if (!read.ok) {
    return {
      ok: true,
      schemaVersion: 'notes-read-model.v1',
      projectId: context.projectId,
      state: 'corrupt',
      unavailableReason: read.reason,
      notes: [],
      counts: { total: 0, deleted: 0, inbox: 0 },
    };
  }
  return context.notesStorage.buildNotesReadModel(read.current.document, {
    projectId: context.projectId,
    scope: typeof payload.scope === 'string' ? payload.scope : '',
    includeDeleted: payload.includeDeleted === true,
  });
}

function normalizeProjectSearchPayload(payload = {}) {
  const source = isPlainObjectValue(payload) ? payload : {};
  const nodeIdPattern = /^tree-node-[a-f0-9]{32}$/u;
  const query = typeof source.query === 'string' ? source.query.slice(0, 256) : '';
  const scope = typeof source.scope === 'string' ? source.scope.slice(0, 64) : 'project';
  const selectedNodeIds = Array.isArray(source.selectedNodeIds)
    ? source.selectedNodeIds
      .filter((value) => typeof value === 'string' && nodeIdPattern.test(value))
      .slice(0, 100)
    : [];
  return {
    query,
    scope,
    caseSensitive: source.caseSensitive === true,
    wholeWord: source.wholeWord === true,
    limit: Number.isFinite(Number(source.limit)) ? Number(source.limit) : 50,
    activeNodeId: typeof source.activeNodeId === 'string' && nodeIdPattern.test(source.activeNodeId)
      ? source.activeNodeId
      : '',
    scopeNodeId: typeof source.scopeNodeId === 'string' && nodeIdPattern.test(source.scopeNodeId)
      ? source.scopeNodeId
      : '',
    selectedNodeIds,
  };
}

function walkProjectTreeNodes(root, visitor) {
  if (!root || typeof root !== 'object' || Array.isArray(root)) return;
  visitor(root);
  if (Array.isArray(root.children)) {
    root.children.forEach((child) => walkProjectTreeNodes(child, visitor));
  }
}

function collectProjectSearchScopeNodeIds(roots, scopeNodeId) {
  if (!scopeNodeId) return null;
  let scopeRoot = null;
  Object.values(roots).forEach((root) => {
    walkProjectTreeNodes(root, (node) => {
      if (!scopeRoot && node && node.nodeId === scopeNodeId) {
        scopeRoot = node;
      }
    });
  });
  if (!scopeRoot) return new Set([scopeNodeId]);
  const ids = new Set();
  walkProjectTreeNodes(scopeRoot, (node) => {
    if (typeof node.nodeId === 'string' && node.nodeId) ids.add(node.nodeId);
  });
  return ids;
}

function projectSearchShouldIncludeDocument(node, options, scopeIds) {
  const nodeId = typeof node.nodeId === 'string' ? node.nodeId : '';
  if (!nodeId) return false;
  if (options.scope === 'current') return nodeId === options.activeNodeId;
  if (options.scope === 'selected') return options.selectedNodeIds.includes(nodeId);
  if (options.scope === 'structure') return scopeIds ? scopeIds.has(nodeId) : false;
  if (options.scope === 'notes' || options.scope === 'annotations') return false;
  return true;
}

async function buildProjectSearchDocumentSources(roots, options, projectContext) {
  const sources = [];
  const scopeIds = collectProjectSearchScopeNodeIds(roots, options.scopeNodeId || options.activeNodeId);
  const envelopeModule = await loadDocumentContentEnvelopeModule();
  const candidateNodes = [];
  Object.values(roots).forEach((root) => {
    walkProjectTreeNodes(root, (node) => {
      if (projectSearchShouldIncludeDocument(node, options, scopeIds)) {
        candidateNodes.push(node);
      }
    });
  });

  for (const node of candidateNodes) {
    let documentTarget;
    try {
      documentTarget = getResolvedTreeDocumentTarget({
        projectId: projectContext.projectId,
        projectRoot: projectContext.projectRoot,
        manifestPath: projectContext.manifestPath,
        manifest: projectContext.manifest,
        nodeId: node.nodeId,
        nodePath: typeof node.nodePath === 'string' ? node.nodePath : node.path,
        kind: node.kind,
      });
    } catch {
      continue;
    }
    const guard = sanitizePayloadWithinProjectRoot(
      { path: documentTarget.filePath },
      ['path'],
      projectContext.projectRoot,
    );
    if (!guard.ok || !guard.payload) continue;
    const relativePath = path.relative(projectContext.projectRoot, guard.payload.path);
    if (options.scope === 'manuscript' && relativePath.split(path.sep)[0] !== PROJECT_SUBFOLDERS.roman) {
      continue;
    }
    let content = '';
    try {
      content = await fs.readFile(guard.payload.path, 'utf8');
    } catch (error) {
      if (error && error.code !== 'ENOENT') logDevError('query.projectSearch:fileRead', error);
      continue;
    }
    let parsedText = content;
    try {
      const parsed = envelopeModule.parseObservablePayload(content);
      if (parsed && !parsed.issue) parsedText = parsed.text || '';
    } catch {
      parsedText = content;
    }
    const context = getDocumentContextFromPath(guard.payload.path);
    sources.push({
      type: 'document',
      sourceId: node.nodeId,
      nodeId: node.nodeId,
      kind: documentTarget.kind,
      title: typeof node.label === 'string' && node.label ? node.label : context.title,
      scope: options.scope === 'manuscript' ? 'manuscript' : 'project',
      field: 'body',
      text: parsedText,
      contentHash: computeHash(content),
    });
  }
  return sources;
}

async function buildProjectSearchNoteSources(options, projectId, projectRoot) {
  if (options.scope !== 'project' && options.scope !== 'notes') return [];
  const notesStorage = await loadNotesStorageModule();
  let readResult;
  try {
    readResult = await notesStorage.readNotesStorage({
      projectRoot,
      projectId,
      readFile: fs.readFile,
    });
  } catch (error) {
    if (error && error.code !== 'ENOENT') logDevError('query.projectSearch:notesRead', error);
    return [];
  }
  if (!readResult || readResult.ok !== true) return [];
  const notesResult = notesStorage.buildNotesReadModel(readResult.document, {
    projectId,
    scope: '',
    includeDeleted: false,
  });
  if (!notesResult || notesResult.ok !== true || !Array.isArray(notesResult.notes)) return [];
  return notesResult.notes.map((note) => ({
    type: 'note',
    sourceId: note.id,
    noteId: note.id,
    nodeId: typeof note.nodeId === 'string' ? note.nodeId : '',
    kind: 'note',
    title: typeof note.title === 'string' && note.title ? note.title : 'Заметка',
    scope: note.scope || 'note',
    field: 'body',
    text: [note.title, note.body].filter(Boolean).join('\n'),
    contentHash: typeof note.updatedAtUtc === 'string' ? computeHash(`${note.id}\n${note.updatedAtUtc}`) : '',
  }));
}

function pushReviewSurfaceAnnotationSources(target, surface, sourceName) {
  if (!isPlainObjectValue(surface)) return;
  const exactPreview = isPlainObjectValue(surface.exactTextPlanPreview)
    ? surface.exactTextPlanPreview
    : (isPlainObjectValue(surface.planPreview) ? surface.planPreview : {});
  if (Array.isArray(exactPreview.applyOps)) {
    exactPreview.applyOps.forEach((op, index) => {
      if (!isPlainObjectValue(op)) return;
      target.push({
        type: 'annotation',
        sourceId: `annotation-exact-${sourceName}-${index}`,
        annotationId: typeof op.changeId === 'string' ? op.changeId : `exact-${index}`,
        nodeId: typeof op.sceneId === 'string' ? op.sceneId : '',
        kind: 'review-exact-text',
        title: typeof op.changeId === 'string' ? op.changeId : 'Review change',
        scope: 'annotations',
        field: 'review',
        text: [op.expectedText, op.replacementText, op.applyReason].filter((value) => typeof value === 'string').join('\n'),
        contentHash: computeHash(JSON.stringify(op)),
      });
    });
  }
  const commentPreview = isPlainObjectValue(surface.commentSurvivalPreview)
    ? surface.commentSurvivalPreview
    : (isPlainObjectValue(surface.commentPreview) ? surface.commentPreview : {});
  if (Array.isArray(commentPreview.orphanComments)) {
    commentPreview.orphanComments.forEach((comment, index) => {
      if (!isPlainObjectValue(comment)) return;
      target.push({
        type: 'annotation',
        sourceId: `annotation-comment-${sourceName}-${index}`,
        annotationId: typeof comment.threadId === 'string' ? comment.threadId : `comment-${index}`,
        nodeId: typeof comment.sceneId === 'string' ? comment.sceneId : '',
        kind: 'review-comment',
        title: typeof comment.threadId === 'string' ? comment.threadId : 'Комментарий',
        scope: 'annotations',
        field: 'comment',
        text: [comment.body, comment.reason, ...(Array.isArray(comment.reasonCodes) ? comment.reasonCodes : [])]
          .filter((value) => typeof value === 'string')
          .join('\n'),
        contentHash: computeHash(JSON.stringify(comment)),
      });
    });
  }
}

function buildProjectSearchAnnotationSources(options) {
  if (options.scope !== 'project' && options.scope !== 'annotations') return [];
  const sources = [];
  pushReviewSurfaceAnnotationSources(sources, readActiveReviewSessionReviewSurface(), 'active');
  return sources;
}

async function handleWorkspaceProjectSearchQuery(payload = {}) {
  const options = normalizeProjectSearchPayload(payload);
  const manifestRecord = await readProjectManifest(DEFAULT_PROJECT_NAME);
  const manifest = manifestRecord && manifestRecord.manifest ? manifestRecord.manifest : null;
  if (!manifest) {
    return {
      ok: true,
      schemaVersion: 'project-search-read-model.v1',
      projectId: '',
      state: 'unavailable',
      options,
      results: [],
      counts: { total: 0, returned: 0, sources: 0 },
      stale: true,
      cancelled: false,
      unavailableReason: 'PROJECT_MANIFEST_UNAVAILABLE',
    };
  }
  const manifestPath = getProjectManifestPath(DEFAULT_PROJECT_NAME);
  const projectRoot = path.dirname(manifestPath);
  if (!options.query.trim()) {
    const searchModule = await loadProjectSearchReadModelModule();
    return searchModule.buildProjectSearchReadModel({
      projectId: manifest.projectId,
      options,
      sources: [],
    });
  }
  try {
    const { projectId, roots } = await buildProjectTreeRootsWithIdentitiesReadOnly();
    const searchModule = await loadProjectSearchReadModelModule();
    const documents = await buildProjectSearchDocumentSources(roots, options, {
      projectId,
      projectRoot,
      manifestPath,
      manifest,
    });
    const notes = await buildProjectSearchNoteSources(options, projectId, projectRoot);
    const annotations = buildProjectSearchAnnotationSources(options);
    return searchModule.buildProjectSearchReadModel({
      projectId,
      options,
      sources: [...documents, ...notes, ...annotations],
    });
  } catch (error) {
    logDevError('query.projectSearch', error);
    return {
      ok: true,
      schemaVersion: 'project-search-read-model.v1',
      projectId: manifest.projectId,
      state: 'unavailable',
      options,
      results: [],
      counts: { total: 0, returned: 0, sources: 0 },
      stale: true,
      cancelled: false,
      unavailableReason: error && typeof error.code === 'string' ? error.code : 'PROJECT_SEARCH_UNAVAILABLE',
    };
  }
}

