async function handleImportProjectArchive(payloadRaw = {}, options = {}) {
  const recovered = await recoverProjectLifecycleJournal();
  if (!recovered.ok) return recovered;

  const payload = normalizeProjectArchiveImportPayload(payloadRaw);
  if (!payload) {
    return makeTypedProjectArchiveImportError(
      'E_PROJECT_ARCHIVE_IMPORT_PAYLOAD_INVALID',
      'project_archive_import_payload_invalid',
    );
  }
  if (payload.ok === false) {
    return makeTypedProjectArchiveImportError(payload.code, payload.reason, payload.details);
  }
  if (payload.pathBoundaryError) {
    return makeTypedProjectArchiveImportError(
      'E_PATH_BOUNDARY_VIOLATION',
      'path_boundary_violation',
      buildPathBoundaryDetails(payload.pathBoundaryError),
    );
  }

  let resolvedPath;
  try {
    resolvedPath = await resolveProjectArchiveImportPath(payload);
  } catch (error) {
    return makeTypedProjectArchiveImportError(
      'E_PROJECT_ARCHIVE_IMPORT_OPEN_DIALOG_FAILED',
      'open_dialog_failed',
      { message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN' },
    );
  }
  if (resolvedPath?.canceled === true) {
    return {
      ok: true,
      canceled: true,
      preview: false,
      imported: false,
    };
  }
  if (resolvedPath?.pathBoundaryError) {
    return makeTypedProjectArchiveImportError(
      'E_PATH_BOUNDARY_VIOLATION',
      'path_boundary_violation',
      buildPathBoundaryDetails(resolvedPath.pathBoundaryError),
    );
  }
  if (resolvedPath?.error) {
    return makeTypedProjectArchiveImportError(
      resolvedPath.error.code,
      resolvedPath.error.reason,
      resolvedPath.error.details,
    );
  }

  let loaded;
  try {
    loaded = await readProjectArchiveImportSource(resolvedPath.archivePath);
  } catch (error) {
    return makeTypedProjectArchiveImportError(
      'E_PROJECT_ARCHIVE_IMPORT_SOURCE_UNAVAILABLE',
      typeof error?.reason === 'string' ? error.reason : 'archive_source_unavailable',
      {
        message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
        ...(isPlainObjectValue(error?.details) ? error.details : {}),
      },
    );
  }

  let archivePayload;
  try {
    archivePayload = readProjectArchivePayload(loaded.bytes);
  } catch (error) {
    return makeTypedProjectArchiveImportError(
      typeof error?.code === 'string' ? error.code : 'E_PROJECT_ARCHIVE_IMPORT_INVALID',
      typeof error?.reason === 'string' ? error.reason : 'archive_invalid',
      isPlainObjectValue(error?.details) ? error.details : {},
    );
  }

  const archiveSummary = summarizeProjectArchivePayload(archivePayload);
  const archiveProjectId = normalizeStableProjectId(archiveSummary.projectId);
  if (!archiveProjectId) {
    return makeTypedProjectArchiveImportError(
      'E_PROJECT_ARCHIVE_IMPORT_PROJECT_ID_MISSING',
      'project_id_missing',
    );
  }
  const mode = normalizeProjectArchiveImportMode(payload.mode);
  const existingBinding = await findProjectBindingByProjectId(archiveProjectId);
  const collision = Boolean(existingBinding && existingBinding.projectRoot);
  if (payload.confirmed !== true) {
    pendingProjectArchiveImportPreview = {
      requestId: payload.requestId,
      archivePath: resolvedPath.archivePath,
      archiveSha256: archiveSummary.archiveSha256,
      projectId: archiveProjectId,
      createdAtUtc: new Date().toISOString(),
    };
    return {
      ok: true,
      preview: true,
      imported: false,
      commandId: IMPORT_PROJECT_ARCHIVE_COMMAND_ID,
      requestId: payload.requestId,
      mode,
      archiveManifest: archiveSummary,
      collision,
      restoreAvailable: !collision,
      copyAvailable: true,
      authority: {
        pathsExposed: false,
        networkRequired: false,
      },
    };
  }
  if (mode === 'restore' && collision) {
    pendingProjectArchiveImportPreview = null;
    return makeTypedProjectArchiveImportError(
      'E_PROJECT_ARCHIVE_IMPORT_PROJECT_ID_COLLISION',
      'project_archive_import_project_id_collision',
      {
        projectId: archiveProjectId,
        restorePreservesProjectId: true,
        copyAvailable: true,
      },
    );
  }

  const preferredName = normalizeProjectLifecycleName(
    payload.projectName || archiveSummary.projectName,
    mode === 'copy' ? `${archiveSummary.projectName || 'Imported Project'} Copy` : (archiveSummary.projectName || 'Imported Project'),
  );
  const targetRoot = await getUniqueProjectLifecycleRoot(fileManager.getDocumentsPath(), preferredName);
  const tempRoot = makeProjectLifecycleTempPath(targetRoot, 'project-archive-import');
  const newProjectId = mode === 'copy' ? createStableProjectId() : archiveProjectId;
  const authority = await getMainProjectManifestAuthority();

  try {
    return await authority.withProjectLease(newProjectId, async (lease) => {
      await lease.assertOwned();
      const racedBinding = await findProjectBindingByProjectId(newProjectId);
      if (racedBinding?.projectRoot) {
        const error = new Error('PROJECT_ARCHIVE_IMPORT_PROJECT_ID_COLLISION');
        error.code = 'E_PROJECT_ARCHIVE_IMPORT_PROJECT_ID_COLLISION';
        error.reason = 'project_archive_import_project_id_collision';
        throw error;
      }
      await writeProjectLifecycleJournal({
        commandId: IMPORT_PROJECT_ARCHIVE_COMMAND_ID,
        projectId: newProjectId,
        sourceProjectId: archiveProjectId,
        phase: 'importing-to-temp',
        targetRoot,
        tempRoot,
      });
      if (typeof options.beforeExtract === 'function') await options.beforeExtract({ tempRoot, targetRoot });
      await queueDiskOperation(
        () => writeProjectArchivePayloadToTempRoot(archivePayload, tempRoot),
        'import project archive entries',
      );
      const tempManifestPath = joinPathSegmentsWithinRoot(tempRoot, [PROJECT_MANIFEST_FILENAME], {
        resolveSymlinks: false,
      });
      const rawRecord = await readProjectManifestRawAtPath(tempManifestPath);
      const sourceManifest = isPlainObjectValue(rawRecord.manifest) ? rawRecord.manifest : {};
      if (normalizeStableProjectId(sourceManifest.projectId) !== archiveProjectId) {
        throw new Error('PROJECT_ARCHIVE_IMPORT_PROJECT_ID_MISMATCH');
      }
      let nextManifest = sourceManifest;
      if (mode === 'copy') {
        nextManifest = {
          ...sourceManifest,
          schemaVersion: PROJECT_MANIFEST_SCHEMA_VERSION,
          projectId: newProjectId,
          projectName: preferredName,
          createdAtUtc: new Date().toISOString(),
          copiedFromProjectId: archiveProjectId,
        };
        delete nextManifest.treeIdentity;
        await writeProjectManifestRawAtomic(tempManifestPath, nextManifest, {
          expectedText: rawRecord.raw,
          expectedProjectId: archiveProjectId,
          lease,
        });
      }
      if (typeof options.afterExtractBeforeFinalMove === 'function') {
        await options.afterExtractBeforeFinalMove({ tempRoot, targetRoot });
      }
      if (await fileExists(targetRoot)) {
        throw new Error('PROJECT_ARCHIVE_IMPORT_TARGET_EXISTS');
      }
      await lease.publish(() => fs.rename(tempRoot, targetRoot));
      await writeProjectLifecycleJournal({
        commandId: IMPORT_PROJECT_ARCHIVE_COMMAND_ID,
        projectId: newProjectId,
        sourceProjectId: archiveProjectId,
        phase: 'final-moved',
        targetRoot,
        tempRoot,
      });

      const manifestPath = joinPathSegmentsWithinRoot(targetRoot, [PROJECT_MANIFEST_FILENAME], {
        resolveSymlinks: false,
      });
      const publishedManifestRecord = await readProjectManifestRawAtPath(manifestPath);
      if (normalizeStableProjectId(publishedManifestRecord.manifest?.projectId) !== newProjectId) {
        throw new Error('PROJECT_ARCHIVE_IMPORT_MANIFEST_READBACK_MISMATCH');
      }
      await lease.assertOwned();
      await clearProjectLifecycleJournal();
      const normalizedManifest = await normalizeProjectManifest(nextManifest, preferredName);
      const projectBinding = {
        projectId: newProjectId,
        projectRoot: targetRoot,
        manifestPath,
        manifest: normalizedManifest,
        sourceSchemaVersion: Number(nextManifest?.schemaVersion),
      };
      await replaceProjectLibraryIndexBinding('', projectBinding, {
        status: 'available',
        markOpened: payload.openAfterImport === true,
        dropSameProjectId: mode === 'restore',
      });
      if (payload.openAfterImport === true) {
        setActiveProjectNameFromRoot(targetRoot);
        const target = await resolveProjectContinueTarget(projectBinding, {});
        if (target.filePath) {
          await openProjectDocumentFile(target.filePath, {
            statusText: 'Архив проекта импортирован',
            projectId: newProjectId,
            projectBinding,
          });
        }
      }
      updateStatus('Архив проекта импортирован');
      pendingProjectArchiveImportPreview = null;
      return {
        ok: true,
        imported: true,
        mode,
        projectId: newProjectId,
        sourceProjectId: archiveProjectId,
        projectName: normalizedManifest.projectName || preferredName,
        archiveManifest: archiveSummary,
        receipt: makeProjectArchiveImportReceipt(IMPORT_PROJECT_ARCHIVE_COMMAND_ID, newProjectId, {
          mode,
          restored: mode === 'restore',
          copied: mode === 'copy',
          sourceProjectId: archiveProjectId,
          archiveSha256: archiveSummary.archiveSha256,
          fileCount: archiveSummary.fileCount,
          byteCount: archiveSummary.byteCount,
        }),
        authority: {
          pathsExposed: false,
          networkRequired: false,
        },
      };
    });
  } catch (error) {
    await fs.rm(tempRoot, { recursive: true, force: true }).catch(() => {});
    await clearProjectLifecycleJournal();
    pendingProjectArchiveImportPreview = null;
    logDevError('project archive import', error);
    return makeTypedProjectArchiveImportError(
      typeof error?.code === 'string' ? error.code : 'E_PROJECT_ARCHIVE_IMPORT_FAILED',
      typeof error?.reason === 'string'
        ? error.reason
        : (error && typeof error.message === 'string' ? error.message : 'project_archive_import_failed'),
    );
  }
}

async function handleImportMarkdownV1(payloadRaw) {
  const payload = normalizeMarkdownImportPayload(payloadRaw);
  if (!payload) {
    return makeTypedMarkdownError(IMPORT_MARKDOWN_V1_CHANNEL, 'E_MD_PAYLOAD_INVALID', 'import_payload_invalid');
  }
  if (payload.pathBoundaryError) {
    return makeTypedMarkdownError(
      IMPORT_MARKDOWN_V1_CHANNEL,
      'E_PATH_BOUNDARY_VIOLATION',
      'path_boundary_violation',
      buildPathBoundaryDetails(payload.pathBoundaryError),
    );
  }
  if (payload.externalPathAuthorityDenied) {
    return makeTypedMarkdownError(
      IMPORT_MARKDOWN_V1_CHANNEL,
      'E_MD_RENDERER_AUTHORITY_DENIED',
      'renderer_source_path_authority_denied',
    );
  }

  if (payload.safeCreate === true) {
    try {
      await ensureProjectStructure();
      const projectBinding = await resolveProjectBindingForFile(getProjectSectionPath('roman'));
      const safeCreateResult = await applyMarkdownImportSafeCreate(
        {
          previewPayload: payload.previewPayload,
        },
        {
          projectRoot: getProjectRootPath(),
          romanRoot: getProjectSectionPath('roman'),
          projectId: projectBinding && typeof projectBinding.projectId === 'string'
            ? projectBinding.projectId
            : '',
          previewSchemaVersion: MARKDOWN_IMPORT_PREVIEW_SCHEMA,
          reservedTopLevelRomanNames: [...ROMAN_SECTION_FILENAME_SET],
          queueDiskOperation,
          operationLabel: 'safe create import scene batch',
          writeBatchAtomic: writeFlowSceneBatchAtomic,
        },
      );
      if (safeCreateResult.ok) {
        return {
          ok: 1,
          safeCreate: true,
          created: true,
          createdSceneIds: Array.isArray(safeCreateResult.value.createdSceneIds)
            ? safeCreateResult.value.createdSceneIds
            : [],
          receipt: safeCreateResult.value.receipt,
        };
      }
      return makeTypedMarkdownError(
        IMPORT_MARKDOWN_V1_CHANNEL,
        safeCreateResult.error && typeof safeCreateResult.error.code === 'string'
          ? safeCreateResult.error.code
          : 'MDV1_SAFE_CREATE_WRITE_FAIL',
        safeCreateResult.error && typeof safeCreateResult.error.reason === 'string'
          ? safeCreateResult.error.reason
          : 'import_safe_create_failed',
        safeCreateResult.error && safeCreateResult.error.details && typeof safeCreateResult.error.details === 'object'
          ? safeCreateResult.error.details
          : {},
      );
    } catch (error) {
      return makeTypedMarkdownError(
        IMPORT_MARKDOWN_V1_CHANNEL,
        'MDV1_SAFE_CREATE_WRITE_FAIL',
        'import_safe_create_failed',
        { message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN' },
      );
    }
  }

  let transform;
  try {
    transform = await loadMarkdownTransformModule();
  } catch (error) {
    return makeTypedMarkdownError(
      IMPORT_MARKDOWN_V1_CHANNEL,
      'E_MD_TRANSFORM_LOAD_FAILED',
      'transform_module_load_failed',
      { message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN' },
    );
  }

  try {
    const markdownText = payload.text;
    const ioRecovery = null;

    const parsedScene = transform.parseMarkdownV1(markdownText, { limits: payload.limits });
    const converted = transform.markdownSceneV1ToDocument(parsedScene);
    const envelopeModule = await loadDocumentContentEnvelopeModule();
    const canonicalContent = envelopeModule.composeObservablePayload({ doc: converted.doc });
    const lossReport = transform.mergeLossReports(
      parsedScene && parsedScene.lossReport,
      converted && converted.lossReport,
    );
    const scene = {
      ...parsedScene,
      lossReport,
    };
    const out = {
      ok: 1,
      scene,
      preview: payload.preview === true,
      sourceName: payload.sourceName,
      lossReport,
    };
    if (payload.preview === true) {
      out.previewResult = buildMarkdownImportPreviewEnvelope(
        payload,
        scene,
        lossReport,
        canonicalContent,
        ioRecovery,
      );
    }
    if (ioRecovery) {
      out.recovery = ioRecovery;
    }
    return out;
  } catch (error) {
    let logRecord = null;
    let logPath = '';
    if (payload.preview !== true) {
      try {
        const markdownIo = await loadMarkdownIoModule();
        const log = await appendMarkdownReliabilityLog(markdownIo, {
          op: IMPORT_MARKDOWN_V1_CHANNEL,
          code: error && typeof error.code === 'string' ? error.code : 'E_MD_IMPORT_FAILED',
          reason: error && typeof error.reason === 'string' ? error.reason : 'import_failed',
          sourcePath: payload.sourcePath,
        });
        logRecord = log.logRecord;
        logPath = log.logPath;
      } catch {
        logRecord = null;
        logPath = '';
      }
    }
    return makeTypedMarkdownError(
      IMPORT_MARKDOWN_V1_CHANNEL,
      error && typeof error.code === 'string' ? error.code : 'E_MD_IMPORT_FAILED',
      error && typeof error.reason === 'string' ? error.reason : 'import_failed',
      {
        ...(error && error.details && typeof error.details === 'object' && !Array.isArray(error.details)
          ? error.details
          : {}),
        ...(logRecord ? { logRecord } : {}),
        ...(logPath ? { logPath } : {}),
      },
    );
  }
}

async function readCanonicalMarkdownExportSource() {
  if (isDirty || autoSaveInProgress) {
    throw new Error('Unsaved current scene state cannot be used as Markdown export source');
  }
  if (typeof currentFilePath !== 'string' || !currentFilePath.trim()) {
    throw new Error('No saved current scene is open');
  }
  if (!isAllowedFilePath(currentFilePath)) {
    throw new Error('Current scene path is not allowed');
  }
  const documentContext = getDocumentContextFromPath(currentFilePath);
  if (!documentContext || documentContext.kind !== 'scene') {
    throw new Error('Current file is not a saved scene');
  }

  const observableContent = await fs.readFile(currentFilePath, 'utf8');
  const envelopeModule = await loadDocumentContentEnvelopeModule();
  const parsed = envelopeModule.parseObservablePayload(observableContent || '');
  if (!parsed || typeof parsed.text !== 'string') {
    throw new Error('Current scene envelope could not be parsed');
  }
  if (parsed.issue && typeof parsed.issue === 'object') {
    throw new Error(
      typeof parsed.issue.userMessage === 'string' && parsed.issue.userMessage
        ? parsed.issue.userMessage
        : 'Current scene envelope is invalid',
    );
  }

  const transform = await loadMarkdownTransformModule();
  const scene = parsed.doc
    ? transform.documentToMarkdownSceneV1(parsed.doc)
    : transform.legacyTextToMarkdownSceneV1(parsed.text);
  const artifact = transform.serializeMarkdownV1WithLossReport(scene);
  return {
    scene,
    artifact,
    defaultName: `${path.basename(currentFilePath, path.extname(currentFilePath))}.md`,
  };
}

function summarizeMarkdownLossReport(lossReport) {
  const items = Array.isArray(lossReport?.items) ? lossReport.items : [];
  return items.slice(0, 6).map((item) => {
    const code = typeof item?.code === 'string' && item.code
      ? item.code
      : typeof item?.reasonCode === 'string' && item.reasonCode
        ? item.reasonCode
        : 'MDV1_DOWNGRADE';
    const message = typeof item?.message === 'string' && item.message
      ? item.message
      : typeof item?.note === 'string'
        ? item.note
        : 'Content will be downgraded.';
    return `${code}: ${message}`;
  }).join('\n');
}

async function confirmMarkdownExportLosses(lossReport) {
  const count = Number.isInteger(lossReport?.count) ? lossReport.count : 0;
  if (count <= 0) return true;
  if (!mainWindow) return false;
  const detail = summarizeMarkdownLossReport(lossReport);
  const result = await dialog.showMessageBox(mainWindow, {
    type: 'warning',
    title: 'Markdown export warnings',
    message: `Markdown export has ${count} conversion warning${count === 1 ? '' : 's'}.`,
    detail: detail || 'Some document semantics will be downgraded.',
    buttons: ['Export anyway', 'Cancel'],
    defaultId: 1,
    cancelId: 1,
    noLink: true,
  });
  return result && result.response === 0;
}

// MARKDOWN_LOCAL_FILE_AUTHORITY_COMMAND_SURFACE_START
function normalizeMarkdownLocalFileRequestId(value, fallback) {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback;
}

function validateMarkdownLocalFileIntentPayload(payload, allowedKeys, commandId) {
  if (!isPlainObjectValue(payload)) {
    return makeTypedMarkdownError(commandId, 'E_MD_PAYLOAD_INVALID', 'intent_payload_invalid');
  }
  const unsupportedKeys = Object.keys(payload)
    .filter((key) => !allowedKeys.has(key))
    .sort();
  if (unsupportedKeys.length > 0) {
    return makeTypedMarkdownError(
      commandId,
      'E_MD_PAYLOAD_INVALID',
      'renderer_authority_denied',
      { fieldCount: unsupportedKeys.length },
    );
  }
  if (
    payload.requestId !== undefined
    && (
      typeof payload.requestId !== 'string'
      || payload.requestId.trim().length > MARKDOWN_LOCAL_FILE_MAX_REQUEST_ID_CHARS
    )
  ) {
    return makeTypedMarkdownError(
      commandId,
      'E_MD_PAYLOAD_INVALID',
      'request_id_invalid',
    );
  }
  return { ok: 1 };
}

async function pickMarkdownLocalFile() {
  const result = await showOpenDialogWithAutonomousPath(mainWindow, {
    title: 'Импорт Markdown',
    defaultPath: fileManager.getDocumentsPath(),
    filters: [
      { name: 'Markdown', extensions: ['md', 'markdown'] },
    ],
    properties: ['openFile'],
  }, 'YALKEN_AUTONOMOUS_FILE_DIALOG_OPEN_MARKDOWN');
  if (!result || result.canceled === true) return { canceled: true };
  const filePath = Array.isArray(result.filePaths) && typeof result.filePaths[0] === 'string'
    ? result.filePaths[0].trim()
    : '';
  return filePath ? { filePath, sourceName: path.basename(filePath) } : {};
}

function sanitizeMarkdownLocalFilePreviewForRenderer(previewResult) {
  if (!isPlainObjectValue(previewResult)) return {};
  const plan = isPlainObjectValue(previewResult.safeCreatePlan)
    ? previewResult.safeCreatePlan
    : {};
  return {
    schemaVersion: typeof previewResult.schemaVersion === 'string' ? previewResult.schemaVersion : '',
    type: typeof previewResult.type === 'string' ? previewResult.type : '',
    status: typeof previewResult.status === 'string' ? previewResult.status : '',
    writeEffects: previewResult.writeEffects === false ? false : null,
    sourceName: typeof previewResult.sourceName === 'string' ? previewResult.sourceName : '',
    scene: cloneJsonSafe(previewResult.scene),
    lossReport: isPlainObjectValue(previewResult.lossReport)
      ? cloneJsonSafe(previewResult.lossReport)
      : { count: 0, items: [] },
    safeCreatePlan: {
      mode: typeof plan.mode === 'string' ? plan.mode : '',
      entries: Array.isArray(plan.entries)
        ? plan.entries
          .filter(isPlainObjectValue)
          .map((entry) => ({
            sceneId: typeof entry.sceneId === 'string' ? entry.sceneId : '',
            title: typeof entry.title === 'string' ? entry.title : '',
            contentTextHash: typeof entry.contentTextHash === 'string' ? entry.contentTextHash : '',
            expectedLabel: typeof entry.expectedLabel === 'string' ? entry.expectedLabel : '',
            content: typeof entry.content === 'string' ? entry.content : '',
          }))
        : [],
    },
  };
}

function sanitizeMarkdownLocalFileReceiptForRenderer(receipt) {
  if (!isPlainObjectValue(receipt)) return null;
  return {
    schemaVersion: typeof receipt.schemaVersion === 'string' ? receipt.schemaVersion : '',
    type: typeof receipt.type === 'string' ? receipt.type : '',
    reason: typeof receipt.reason === 'string' ? receipt.reason : '',
    projectId: typeof receipt.projectId === 'string' ? receipt.projectId : '',
    batchId: typeof receipt.batchId === 'string' ? receipt.batchId : '',
    inputHash: typeof receipt.inputHash === 'string' ? receipt.inputHash : '',
    outputHash: typeof receipt.outputHash === 'string' ? receipt.outputHash : '',
    createdSceneIds: Array.isArray(receipt.createdSceneIds)
      ? receipt.createdSceneIds.filter((sceneId) => typeof sceneId === 'string')
      : [],
    createdScenes: Array.isArray(receipt.createdScenes)
      ? receipt.createdScenes
        .filter(isPlainObjectValue)
        .map((scene) => ({
          sceneId: typeof scene.sceneId === 'string' ? scene.sceneId : '',
          kind: typeof scene.kind === 'string' ? scene.kind : '',
          bytesWritten: Number.isInteger(scene.bytesWritten) ? scene.bytesWritten : 0,
          outputHash: typeof scene.outputHash === 'string' ? scene.outputHash : '',
        }))
      : [],
  };
}

function remapMarkdownLocalFileError(commandId, result, fallbackCode, fallbackReason) {
  const error = isPlainObjectValue(result?.error) ? result.error : {};
  return makeTypedMarkdownError(
    commandId,
    typeof error.code === 'string' && error.code ? error.code : fallbackCode,
    typeof error.reason === 'string' && error.reason ? error.reason : fallbackReason,
  );
}

async function handleMarkdownImportLocalFilePreviewCommandSurface(payload = {}, options = {}) {
  const payloadState = validateMarkdownLocalFileIntentPayload(
    payload,
    new Set(['requestId']),
    MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
  );
  if (payloadState.ok !== 1) return payloadState;
  const requestId = normalizeMarkdownLocalFileRequestId(
    payload.requestId,
    'markdown-local-file-preview-request',
  );
  const pickLocalFile = typeof options.pickLocalFile === 'function'
    ? options.pickLocalFile
    : pickMarkdownLocalFile;
  let selected;
  try {
    selected = await pickLocalFile({ requestId });
  } catch {
    return makeTypedMarkdownError(
      MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
      'E_MD_IMPORT_PICK_FAILED',
      'local_file_picker_failed',
    );
  }
  if (selected?.canceled === true) {
    return {
      ok: 1,
      commandId: MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
      requestId,
      canceled: true,
      preview: false,
    };
  }
  const filePath = typeof selected?.filePath === 'string' && selected.filePath.trim()
    ? selected.filePath.trim()
    : typeof selected?.path === 'string' && selected.path.trim()
      ? selected.path.trim()
      : '';
  if (!filePath) {
    return makeTypedMarkdownError(
      MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
      'E_MD_IMPORT_SOURCE_REQUIRED',
      'local_file_required',
    );
  }

  const readLocalFile = typeof options.readLocalFile === 'function'
    ? options.readLocalFile
    : readExternalFileBounded;
  let loaded;
  try {
    loaded = await readLocalFile(filePath, {
      projectRoot: getProjectRootPath(),
      allowedExtensions: ['.md', '.markdown'],
      maxBytes: MARKDOWN_LOCAL_FILE_MAX_BYTES,
    });
  } catch (error) {
    return makeTypedMarkdownError(
      MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
      'E_MD_IMPORT_SOURCE_DENIED',
      typeof error?.reason === 'string' && error.reason
        ? error.reason
        : 'local_file_read_failed',
    );
  }
  if (!loaded || !Buffer.isBuffer(loaded.bytes) || loaded.bytes.length === 0) {
    return makeTypedMarkdownError(
      MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
      'E_MD_IMPORT_SOURCE_INVALID',
      'local_file_bytes_invalid',
    );
  }

  const sourceName = typeof selected?.sourceName === 'string' && selected.sourceName.trim()
    ? path.basename(selected.sourceName.trim())
    : path.basename(filePath);
  const preview = await handleImportMarkdownV1({
    text: loaded.bytes.toString('utf8'),
    sourceName,
    preview: true,
  });
  if (!preview || preview.ok !== 1 || !isPlainObjectValue(preview.previewResult)) {
    return remapMarkdownLocalFileError(
      MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
      preview,
      'E_MD_IMPORT_PREVIEW_FAILED',
      'local_file_preview_failed',
    );
  }

  const previewId = `mdp_${crypto.randomBytes(12).toString('hex')}`;
  pendingMarkdownLocalFilePreview = {
    previewId,
    projectRoot: path.resolve(getProjectRootPath()),
    createdAtMs: Date.now(),
    previewPayload: cloneJsonSafe(preview.previewResult),
  };
  return {
    ok: 1,
    commandId: MARKDOWN_IMPORT_LOCAL_FILE_PREVIEW_COMMAND_ID,
    requestId,
    canceled: false,
    preview: true,
    previewId,
    sourceName,
    byteLength: loaded.bytes.length,
    scene: cloneJsonSafe(preview.scene),
    lossReport: cloneJsonSafe(preview.lossReport),
    previewResult: sanitizeMarkdownLocalFilePreviewForRenderer(preview.previewResult),
  };
}

async function handleMarkdownImportLocalFileAcceptCommandSurface(payload = {}) {
  const payloadState = validateMarkdownLocalFileIntentPayload(
    payload,
    new Set(['requestId', 'previewId']),
    MARKDOWN_IMPORT_LOCAL_FILE_ACCEPT_COMMAND_ID,
  );
  if (payloadState.ok !== 1) return payloadState;
  const requestId = normalizeMarkdownLocalFileRequestId(
    payload.requestId,
    'markdown-local-file-accept-request',
  );
  const previewId = typeof payload.previewId === 'string' ? payload.previewId.trim() : '';
  const pending = pendingMarkdownLocalFilePreview;
  const previewAgeMs = isPlainObjectValue(pending) ? Date.now() - pending.createdAtMs : -1;
  if (
    !/^mdp_[a-f0-9]{24}$/u.test(previewId)
    || !isPlainObjectValue(pending)
    || pending.previewId !== previewId
    || path.resolve(getProjectRootPath()) !== pending.projectRoot
    || !Number.isFinite(previewAgeMs)
    || previewAgeMs < 0
    || previewAgeMs > MARKDOWN_LOCAL_FILE_PREVIEW_TTL_MS
  ) {
    return makeTypedMarkdownError(
      MARKDOWN_IMPORT_LOCAL_FILE_ACCEPT_COMMAND_ID,
      'E_MD_IMPORT_PREVIEW_STALE',
      'local_file_preview_stale',
    );
  }

  pendingMarkdownLocalFilePreview = null;
  const result = await handleImportMarkdownV1({
    safeCreate: true,
    previewPayload: pending.previewPayload,
  });
  if (!result || result.ok !== 1) {
    return remapMarkdownLocalFileError(
      MARKDOWN_IMPORT_LOCAL_FILE_ACCEPT_COMMAND_ID,
      result,
      'E_MD_IMPORT_SAFE_CREATE_FAILED',
      'local_file_safe_create_failed',
    );
  }
  return {
    ok: 1,
    commandId: MARKDOWN_IMPORT_LOCAL_FILE_ACCEPT_COMMAND_ID,
    requestId,
    previewId,
    safeCreate: result.safeCreate === true,
    created: result.created === true,
    createdSceneIds: Array.isArray(result.createdSceneIds)
      ? result.createdSceneIds.filter((sceneId) => typeof sceneId === 'string')
      : [],
    receipt: sanitizeMarkdownLocalFileReceiptForRenderer(result.receipt),
  };
}

async function handleMarkdownExportLocalFileCommandSurface(payload = {}, options = {}) {
  const payloadState = validateMarkdownLocalFileIntentPayload(
    payload,
    new Set(['requestId']),
    MARKDOWN_EXPORT_LOCAL_FILE_COMMAND_ID,
  );
  if (payloadState.ok !== 1) return payloadState;
  const requestId = normalizeMarkdownLocalFileRequestId(
    payload.requestId,
    'markdown-local-file-export-request',
  );

  const readCanonicalSource = typeof options.readCanonicalSource === 'function'
    ? options.readCanonicalSource
    : readCanonicalMarkdownExportSource;
  let source;
  try {
    source = await readCanonicalSource();
  } catch (error) {
    return makeTypedMarkdownError(
      MARKDOWN_EXPORT_LOCAL_FILE_COMMAND_ID,
      'E_MD_EXPORT_SOURCE_UNAVAILABLE',
      'main_owned_editor_source_unavailable',
      { message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN' },
    );
  }
  if (!isPlainObjectValue(source?.scene) || !isPlainObjectValue(source?.artifact)) {
    return makeTypedMarkdownError(
      MARKDOWN_EXPORT_LOCAL_FILE_COMMAND_ID,
      'E_MD_EXPORT_SOURCE_INVALID',
      'canonical_saved_scene_source_invalid',
    );
  }
  const sourceLossReport = isPlainObjectValue(source.artifact.lossReport)
    ? source.artifact.lossReport
    : { count: 0, items: [] };
  const confirmLosses = typeof options.confirmLosses === 'function'
    ? options.confirmLosses
    : confirmMarkdownExportLosses;
  if (Number.isInteger(sourceLossReport.count) && sourceLossReport.count > 0) {
    let confirmed = false;
    try {
      confirmed = await confirmLosses(sourceLossReport);
    } catch {
      confirmed = false;
    }
    if (!confirmed) {
      return {
        ok: 1,
        commandId: MARKDOWN_EXPORT_LOCAL_FILE_COMMAND_ID,
        requestId,
        canceled: true,
        exported: false,
        bytesWritten: 0,
        snapshotCreated: false,
        canonicalSavedSceneSource: true,
        lossReport: cloneJsonSafe(sourceLossReport),
      };
    }
  }
  const result = await handleExportMarkdownV1({
    scene: source.scene,
    saveAs: true,
    defaultName: typeof source.defaultName === 'string' && source.defaultName
      ? source.defaultName
      : 'export.md',
    safetyMode: 'strict',
    snapshotLimit: 3,
  });
  if (!result || result.ok !== 1) {
    return remapMarkdownLocalFileError(
      MARKDOWN_EXPORT_LOCAL_FILE_COMMAND_ID,
      result,
      'E_MD_EXPORT_FAILED',
      'local_file_export_failed',
    );
  }
  return {
    ok: 1,
    commandId: MARKDOWN_EXPORT_LOCAL_FILE_COMMAND_ID,
    requestId,
    canceled: result.canceled === true,
    exported: result.canceled !== true && Boolean(result.outPath),
    bytesWritten: Number.isInteger(result.bytesWritten) ? result.bytesWritten : 0,
    snapshotCreated: result.snapshotCreated === true,
    canonicalSavedSceneSource: true,
    lossReport: isPlainObjectValue(result.lossReport)
      ? cloneJsonSafe(result.lossReport)
      : { count: 0, items: [] },
  };
}
// MARKDOWN_LOCAL_FILE_AUTHORITY_COMMAND_SURFACE_END

async function handleExportMarkdownV1(payloadRaw) {
  const payload = normalizeMarkdownExportPayload(payloadRaw);
  if (!payload) {
    return makeTypedMarkdownError(EXPORT_MARKDOWN_V1_CHANNEL, 'E_MD_PAYLOAD_INVALID', 'export_payload_invalid');
  }
  if (payload.pathBoundaryError) {
    return makeTypedMarkdownError(
      EXPORT_MARKDOWN_V1_CHANNEL,
      'E_PATH_BOUNDARY_VIOLATION',
      'path_boundary_violation',
      buildPathBoundaryDetails(payload.pathBoundaryError),
    );
  }
  if (payload.externalPathAuthorityDenied) {
    return makeTypedMarkdownError(
      EXPORT_MARKDOWN_V1_CHANNEL,
      'E_MD_RENDERER_AUTHORITY_DENIED',
      'renderer_target_path_authority_denied',
    );
  }

  let resolvedPath;
  try {
    resolvedPath = await resolveMarkdownExportPath(payload);
  } catch (error) {
    return makeTypedMarkdownError(
      EXPORT_MARKDOWN_V1_CHANNEL,
      'E_MD_EXPORT_SAVE_DIALOG_FAILED',
      'save_dialog_failed',
      { message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN' },
    );
  }
  if (resolvedPath && resolvedPath.canceled === true) {
    return {
      ok: 1,
      canceled: true,
      outPath: '',
      bytesWritten: 0,
      snapshotCreated: false,
      lossReport: { count: 0, items: [] },
    };
  }
  if (resolvedPath && resolvedPath.error) {
    return makeTypedMarkdownError(
      EXPORT_MARKDOWN_V1_CHANNEL,
      resolvedPath.error.code,
      resolvedPath.error.reason,
    );
  }
  if (resolvedPath && resolvedPath.pathBoundaryError) {
    return makeTypedMarkdownError(
      EXPORT_MARKDOWN_V1_CHANNEL,
      'E_PATH_BOUNDARY_VIOLATION',
      'path_boundary_violation',
      buildPathBoundaryDetails(resolvedPath.pathBoundaryError),
    );
  }
  const outPath = resolvedPath && typeof resolvedPath.outPath === 'string'
    ? resolvedPath.outPath
    : '';
  if (outPath) {
    try {
      await validateExternalWriteTarget(outPath, {
        projectRoot: getProjectRootPath(),
        sourcePaths: typeof currentFilePath === 'string' && currentFilePath ? [currentFilePath] : [],
        allowedExtensions: ['.md', '.markdown'],
      });
    } catch (error) {
      return makeTypedMarkdownError(
        EXPORT_MARKDOWN_V1_CHANNEL,
        'E_MD_EXPORT_TARGET_FORBIDDEN',
        typeof error?.reason === 'string' && error.reason
          ? error.reason
          : 'export_target_forbidden',
      );
    }
  }

  let transform;
  try {
    transform = await loadMarkdownTransformModule();
  } catch (error) {
    return makeTypedMarkdownError(
      EXPORT_MARKDOWN_V1_CHANNEL,
      'E_MD_TRANSFORM_LOAD_FAILED',
      'transform_module_load_failed',
      { message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN' },
    );
  }

  try {
    const serialized = transform.serializeMarkdownV1WithLossReport(payload.scene);
    const markdown = serialized.markdown;

    let writeResult = null;
    if (outPath) {
      const markdownIo = await loadMarkdownIoModule();
      writeResult = await queueDiskOperation(
        async () => {
          await validateExternalWriteTarget(outPath, {
            projectRoot: getProjectRootPath(),
            sourcePaths: typeof currentFilePath === 'string' && currentFilePath ? [currentFilePath] : [],
            allowedExtensions: ['.md', '.markdown'],
          });
          return markdownIo.writeMarkdownWithRecovery(outPath, markdown, {
            maxSnapshots: payload.snapshotLimit,
            safetyMode: payload.safetyMode,
          });
        },
        'export markdown v1',
      );
    }

    return {
      ok: 1,
      markdown,
      safetyMode: payload.safetyMode,
      outPath: writeResult && typeof writeResult.outPath === 'string' ? writeResult.outPath : '',
      bytesWritten: writeResult && Number.isInteger(writeResult.bytesWritten) ? writeResult.bytesWritten : 0,
      snapshotCreated: writeResult ? Boolean(writeResult.snapshotCreated) : false,
      snapshotPath: writeResult && typeof writeResult.snapshotPath === 'string' ? writeResult.snapshotPath : '',
      purgedSnapshots: writeResult && Array.isArray(writeResult.purgedSnapshots) ? writeResult.purgedSnapshots : [],
      lossReport: serialized && serialized.lossReport && typeof serialized.lossReport === 'object'
        ? serialized.lossReport
        : { count: 0, items: [] },
    };
  } catch (error) {
    let logRecord = null;
    let logPath = '';
    const mappedReason = error && typeof error.reason === 'string' ? error.reason : 'export_failed';
    const mappedCode = mappedReason.startsWith('EXTERNAL_TARGET_')
      ? 'E_MD_EXPORT_TARGET_FORBIDDEN'
      : error && typeof error.code === 'string'
        ? error.code
        : 'E_MD_EXPORT_FAILED';
    const recovery = getMarkdownRecoveryGuidance(mapMarkdownErrorCode(mappedCode, mappedReason));
    try {
      const markdownIo = await loadMarkdownIoModule();
      const log = await appendMarkdownReliabilityLog(markdownIo, {
        op: EXPORT_MARKDOWN_V1_CHANNEL,
        code: mappedCode,
        reason: mappedReason,
        safetyMode: payload.safetyMode,
        targetPath: outPath,
        snapshotPath: error && error.details && typeof error.details === 'object'
          ? error.details.snapshotPath
          : '',
        recoveryActions: recovery ? recovery.recoveryActions : [],
      });
      logRecord = log.logRecord;
      logPath = log.logPath;
    } catch {
      logRecord = null;
      logPath = '';
    }
    return makeTypedMarkdownError(
      EXPORT_MARKDOWN_V1_CHANNEL,
      mappedCode,
      mappedReason,
      {
        ...(error && error.details && typeof error.details === 'object' && !Array.isArray(error.details)
          ? error.details
          : {}),
        safetyMode: payload.safetyMode,
        ...(logRecord ? { logRecord } : {}),
        ...(logPath ? { logPath } : {}),
      },
    );
  }
}

function makeFlowModeError(op, code, reason, details = {}) {
  return {
    ok: 0,
    error: {
      op,
      code,
      reason,
      details: details && typeof details === 'object' && !Array.isArray(details) ? details : {},
    },
  };
}

async function getFlowBatchGuard(projectRoot) {
  const staleMarkers = await readFlowSceneBatchMarkers(projectRoot);
  return {
    hasBlockingBatchState: staleMarkers.length > 0,
    staleMarkers,
  };
}

async function buildFlowStableNodeIdMap() {
  const manifestPath = getProjectManifestPath(DEFAULT_PROJECT_NAME);
  const manifestRecord = await readProjectManifest(DEFAULT_PROJECT_NAME);
  const manifest = manifestRecord ? manifestRecord.manifest : null;
  const nodes = manifest && manifest.treeIdentity && manifest.treeIdentity.nodes
    && typeof manifest.treeIdentity.nodes === 'object'
    && !Array.isArray(manifest.treeIdentity.nodes)
    ? manifest.treeIdentity.nodes
    : {};
  const nodeIdsByBindingKey = new Map();
  for (const [nodeId, record] of Object.entries(nodes)) {
    if (
      /^tree-node-[a-f0-9]{32}$/u.test(nodeId)
      && record
      && record.present !== false
      && typeof record.bindingKey === 'string'
      && record.bindingKey.startsWith('file:')
    ) {
      nodeIdsByBindingKey.set(record.bindingKey, nodeId);
    }
  }
  return { manifestPath, nodeIdsByBindingKey };
}

function buildFlowSceneReadDescriptor(node, identity) {
  const filePath = typeof node?.path === 'string' ? node.path : '';
  const sceneId = getProjectRelativeFilePath(filePath, identity.manifestPath);
  const bindingKey = sceneId ? `file:${sceneId.split(path.sep).join('/')}` : '';
  const nodeId = typeof node?.nodeId === 'string' && node.nodeId
    ? node.nodeId
    : (identity.nodeIdsByBindingKey.get(bindingKey) || '');
  return {
    path: filePath,
    sceneId,
    nodeId,
    title: typeof node?.title === 'string' ? node.title : '',
    kind: typeof node?.kind === 'string' ? node.kind : 'scene',
  };
}

async function handleFlowOpenV1() {
  try {
    await ensureProjectStructure();
    const projectRoot = getProjectRootPath();
    const batchGuard = await getFlowBatchGuard(projectRoot);
    if (batchGuard.hasBlockingBatchState) {
      return makeFlowModeError(FLOW_OPEN_V1_CHANNEL, 'M7_FLOW_BATCH_STALE', 'flow_open_batch_recovery_required', {
        staleMarkers: batchGuard.staleMarkers,
      });
    }
    const romanRoot = await buildRomanTree();
    const flowNodes = collectFlowEditableNodes(romanRoot, []);
    const flowIdentity = await buildFlowStableNodeIdMap();

    const scenes = [];
    for (const node of flowNodes) {
      const descriptor = buildFlowSceneReadDescriptor(node, flowIdentity);
      const filePath = descriptor.path;
      let content = '';
      let missing = false;
      try {
        content = await fs.readFile(filePath, 'utf8');
      } catch (error) {
        if (error && error.code === 'ENOENT') {
          missing = true;
        } else {
          return makeFlowModeError(FLOW_OPEN_V1_CHANNEL, 'M7_FLOW_IO_READ_FAIL', 'flow_open_read_failed', {
            path: filePath,
            message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
          });
        }
      }

      scenes.push({
        path: descriptor.path,
        sceneId: descriptor.sceneId,
        nodeId: descriptor.nodeId,
        title: descriptor.title,
        kind: descriptor.kind,
        baselineHash: missing ? '' : computeHash(normalizeFlowTextInput(content)),
        missing,
        partial: missing,
        content: normalizeFlowTextInput(content),
      });
    }

    return {
      ok: 1,
      scenes,
    };
  } catch (error) {
    return makeFlowModeError(FLOW_OPEN_V1_CHANNEL, 'M7_FLOW_INTERNAL_ERROR', 'flow_open_failed', {
      message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
    });
  }
}

async function handleFlowSaveV1(payloadRaw) {
  const payload = payloadRaw && typeof payloadRaw === 'object' && !Array.isArray(payloadRaw) ? payloadRaw : null;
  const incomingScenes = payload && Array.isArray(payload.scenes) ? payload.scenes : null;
  if (!incomingScenes) {
    return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M7_FLOW_INVALID_PAYLOAD', 'flow_save_payload_invalid');
  }

  try {
    await ensureProjectStructure();
    const projectRoot = getProjectRootPath();
    const batchGuard = await getFlowBatchGuard(projectRoot);
    if (batchGuard.hasBlockingBatchState) {
      return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M7_FLOW_BATCH_STALE', 'flow_save_batch_recovery_required', {
        staleMarkers: batchGuard.staleMarkers,
      });
    }
    const romanRoot = await buildRomanTree();
    const allowedNodes = collectFlowEditableNodes(romanRoot, []);
    const allowed = new Map(allowedNodes.map((item) => [item.path, item]));
    const flowIdentity = await buildFlowStableNodeIdMap();

    const normalizedScenes = [];
    for (const item of incomingScenes) {
      if (!item || typeof item !== 'object' || Array.isArray(item)) {
        return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M7_FLOW_INVALID_SCENE_ITEM', 'flow_save_scene_invalid');
      }
      const scenePath = typeof item.path === 'string' ? item.path : '';
      const scenePathGuard = sanitizePayloadWithinProjectRoot({ path: scenePath }, ['path']);
      if (!scenePathGuard.ok || !scenePathGuard.payload) {
        return makeFlowModeError(
          FLOW_SAVE_V1_CHANNEL,
          'E_PATH_BOUNDARY_VIOLATION',
          'flow_save_path_boundary_violation',
          {
            path: scenePath,
            failReason: scenePathGuard.pathGuard && typeof scenePathGuard.pathGuard.failReason === 'string'
              ? scenePathGuard.pathGuard.failReason
              : 'PATH_BOUNDARY_VIOLATION',
          },
        );
      }
      const safeScenePath = scenePathGuard.payload.path;
      if (!safeScenePath || !allowed.has(safeScenePath)) {
        return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M7_FLOW_PATH_FORBIDDEN', 'flow_save_path_forbidden', {
          path: safeScenePath || scenePath,
        });
      }
      const descriptor = buildFlowSceneReadDescriptor(allowed.get(safeScenePath), flowIdentity);
      const sceneId = typeof item.sceneId === 'string' ? item.sceneId.trim() : '';
      const nodeId = typeof item.nodeId === 'string' ? item.nodeId.trim() : '';
      const baselineHash = typeof item.baselineHash === 'string' ? item.baselineHash.trim().toLowerCase() : '';
      if (!sceneId || sceneId !== descriptor.sceneId) {
        return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M15_FLOW_SCENE_ID_MISMATCH', 'flow_scene_id_mismatch', {
          sceneId,
        });
      }
      if (nodeId && descriptor.nodeId && nodeId !== descriptor.nodeId) {
        return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M15_FLOW_NODE_ID_MISMATCH', 'flow_node_id_mismatch', {
          sceneId,
          nodeId,
        });
      }
      if (!/^[a-f0-9]{64}$/u.test(baselineHash)) {
        return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M15_FLOW_BASELINE_HASH_MISSING', 'flow_scene_baseline_hash_missing', {
          sceneId,
        });
      }
      let currentContent = '';
      try {
        currentContent = await fs.readFile(safeScenePath, 'utf8');
      } catch (error) {
        return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M15_FLOW_SOURCE_MISSING', 'flow_scene_missing', {
          sceneId,
          message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
        });
      }
      const currentHash = computeHash(normalizeFlowTextInput(currentContent));
      if (currentHash !== baselineHash) {
        return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M15_FLOW_STALE_SOURCE', 'flow_stale_source', {
          sceneId,
          expectedHash: baselineHash,
          currentHash,
        });
      }
      const nextContent = normalizeFlowTextInput(item.content);
      normalizedScenes.push({
        path: safeScenePath,
        sceneId,
        nodeId: nodeId || descriptor.nodeId,
        baselineHash,
        contentHashAfter: computeHash(nextContent),
        content: nextContent,
      });
    }

    const writeResult = await queueDiskOperation(
      () => writeFlowSceneBatchAtomic({
        projectRoot,
        entries: normalizedScenes,
      }),
      'save flow scene batch',
    );
    if (!writeResult || writeResult.ok !== true) {
      const errorCode = writeResult && writeResult.error && typeof writeResult.error.code === 'string'
        ? writeResult.error.code
        : 'M7_FLOW_IO_WRITE_FAIL';
      const errorReason = writeResult && writeResult.error && typeof writeResult.error.reason === 'string'
        ? writeResult.error.reason
        : 'flow_save_write_failed';
      const errorDetails = writeResult && writeResult.error && writeResult.error.details && typeof writeResult.error.details === 'object'
        ? writeResult.error.details
        : {};
      return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, errorCode, errorReason, errorDetails);
    }

    const batchValue = writeResult && writeResult.value && typeof writeResult.value === 'object'
      ? writeResult.value
      : {};
    const reopenedScenes = [];
    for (const scene of normalizedScenes) {
      let reopenedContent = '';
      try {
        reopenedContent = await fs.readFile(scene.path, 'utf8');
      } catch {
        reopenedContent = scene.content;
      }
      reopenedScenes.push({
        sceneId: scene.sceneId,
        nodeId: scene.nodeId,
        title: typeof allowed.get(scene.path)?.title === 'string' ? allowed.get(scene.path).title : '',
        kind: typeof allowed.get(scene.path)?.kind === 'string' ? allowed.get(scene.path).kind : 'scene',
        baselineHash: computeHash(normalizeFlowTextInput(reopenedContent)),
        missing: false,
        partial: false,
        content: normalizeFlowTextInput(reopenedContent),
      });
    }
    const receiptEntries = normalizedScenes.map((scene) => ({
      sceneId: scene.sceneId,
      nodeId: scene.nodeId,
      baselineHashBefore: scene.baselineHash,
      contentHashAfter: scene.contentHashAfter,
    }));
    const receipt = {
      operation: 'flow.batch.save.v1',
      batchId: typeof batchValue.batchId === 'string' ? batchValue.batchId : '',
      savedCount: normalizedScenes.length,
      committed: true,
      markerCleared: batchValue.receipt && batchValue.receipt.markerCleared === true,
      scenes: receiptEntries,
    };

    updateStatus('Flow mode сохранен');
    return {
      ok: 1,
      savedCount: normalizedScenes.length,
      receipt,
      scenes: reopenedScenes,
    };
  } catch (error) {
    return makeFlowModeError(FLOW_SAVE_V1_CHANNEL, 'M7_FLOW_INTERNAL_ERROR', 'flow_save_failed', {
      message: error && typeof error.message === 'string' ? error.message : 'UNKNOWN',
    });
  }
}

function extractNumericPrefix(name) {
  const match = /^(\d+)_/.exec(name);
  if (!match) return null;
  const value = Number(match[1]);
  return Number.isFinite(value) ? value : null;
}

function stripNumericPrefix(name) {
  return name.replace(/^\d+_/, '');
}

function stripTxtExtension(name) {
  return name.replace(/\.txt$/i, '');
}

function getDisplayNameForEntry(entryName) {
  return stripNumericPrefix(stripTxtExtension(entryName));
}

function normalizeFlowTextInput(value) {
  return String(value ?? '').replaceAll('\r\n', '\n').replaceAll('\r', '\n');
}

function collectFlowEditableNodes(node, output = []) {
  if (!node || typeof node !== 'object') return output;
  const kind = typeof node.kind === 'string' ? node.kind : '';
  const nodePath = typeof node.path === 'string' ? node.path : '';
  if (
    nodePath &&
    nodePath.toLowerCase().endsWith('.txt') &&
    (kind === 'roman-section' || kind === 'scene' || kind === 'chapter-file')
  ) {
    output.push({
      path: nodePath,
      title: typeof node.label === 'string' ? node.label : getDisplayNameForEntry(path.basename(nodePath)),
      kind,
      nodeId: typeof node.nodeId === 'string' ? node.nodeId : '',
    });
  }
  if (Array.isArray(node.children)) {
    for (const child of node.children) {
      collectFlowEditableNodes(child, output);
    }
  }
  return output;
}

function formatPrefixedName(baseName, index) {
  const safeBase = sanitizeFilename(baseName);
  const prefix = String(index).padStart(2, '0');
  return `${prefix}_${safeBase}`;
}

function isPathInside(parentPath, childPath) {
  return isPathInsideBoundary(parentPath, childPath, { resolveSymlinks: false });
}

function makePathBoundaryViolationResult(pathGuard) {
  return {
    ok: false,
    error: 'Path boundary violation',
    code: 'E_PATH_BOUNDARY_VIOLATION',
    failSignal: 'E_PATH_BOUNDARY_VIOLATION',
    failReason: pathGuard && typeof pathGuard.failReason === 'string'
      ? pathGuard.failReason
      : 'PATH_BOUNDARY_VIOLATION',
  };
}

function sanitizePayloadWithinProjectRoot(payload, pathFieldNames) {
  const projectRoot = getProjectRootPath();
  const pathGuard = sanitizePathFieldsWithinRoot(payload, pathFieldNames, projectRoot, {
    mode: 'any',
    resolveSymlinks: true,
  });
  if (!pathGuard.ok || !pathGuard.payload) {
    return {
      ok: false,
      payload: null,
      pathGuard,
      error: makePathBoundaryViolationResult(pathGuard),
    };
  }
  return {
    ok: true,
    payload: pathGuard.payload,
    pathGuard,
    error: null,
  };
}

// Проверка существования файла
async function fileExists(filePath) {
  try {
    await fs.access(filePath);
    return true;
  } catch {
    return false;
  }
}

async function ensureProjectStructure(projectName = DEFAULT_PROJECT_NAME) {
  const projectRoot = getProjectRootPath(projectName);
  const romanPath = getProjectSectionPath('roman', projectName);
  const mindmapPath = getProjectSectionPath('mindmap', projectName);
  const printPath = getProjectSectionPath('print', projectName);
  const materialsPath = getProjectSectionPath('materials', projectName);
  const referencePath = getProjectSectionPath('reference', projectName);
  const trashPath = getProjectSectionPath('trash', projectName);
  const backupsPath = getProjectSectionPath('backups', projectName);

  await fs.mkdir(projectRoot, { recursive: true });
  await fs.mkdir(romanPath, { recursive: true });
  await fs.mkdir(mindmapPath, { recursive: true });
  await fs.mkdir(printPath, { recursive: true });
  await fs.mkdir(materialsPath, { recursive: true });
  await fs.mkdir(referencePath, { recursive: true });
  await fs.mkdir(trashPath, { recursive: true });
  await fs.mkdir(backupsPath, { recursive: true });

  for (const section of MATERIALS_SECTIONS) {
    await fs.mkdir(joinPathSegmentsWithinRoot(materialsPath, [section.dirName], { resolveSymlinks: false }), {
      recursive: true,
    });
  }

  for (const section of REFERENCE_SECTIONS) {
    await fs.mkdir(joinPathSegmentsWithinRoot(referencePath, [section.dirName], { resolveSymlinks: false }), {
      recursive: true,
    });
  }

  await ensureProjectManifest(projectName);

  return projectRoot;
}

async function readDirectoryEntries(folderPath) {
  let entries = [];
  try {
    entries = await fs.readdir(folderPath, { withFileTypes: true });
  } catch (error) {
    logDevError('readDirectoryEntries', error);
    return [];
  }

  return entries
    .filter((entry) => entry.name && !entry.name.startsWith('.'))
    .map((entry) => ({
      name: entry.name,
      path: joinPathSegmentsWithinRoot(folderPath, [entry.name], { resolveSymlinks: false }),
      isDirectory: entry.isDirectory(),
      isFile: entry.isFile(),
      prefix: extractNumericPrefix(entry.name),
      baseName: getDisplayNameForEntry(entry.name)
    }))
    .sort((a, b) => {
      const prefixA = a.prefix ?? Number.MAX_SAFE_INTEGER;
      const prefixB = b.prefix ?? Number.MAX_SAFE_INTEGER;
      if (prefixA !== prefixB) {
        return prefixA - prefixB;
      }
      return a.baseName.localeCompare(b.baseName, 'ru');
    });
}

function buildNode({ name, label, kind, nodePath, children = [], ...metadata }) {
  return {
    ...metadata,
    id: nodePath,
    name,
    label,
    kind,
    path: nodePath,
    children
  };
}

function toProjectTreeBindingKey(projectRoot, candidatePath) {
  if (typeof candidatePath !== 'string' || !candidatePath.trim()) return '';
  const relativePath = path.relative(projectRoot, candidatePath);
  if (!relativePath || relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
    return '';
  }
  return `file:${relativePath.split(path.sep).join('/')}`;
}

function getProjectTreeIdentityBindingKey(node, projectRoot) {
  if (!node || typeof node !== 'object') {
    return '';
  }
  if (node.kind === 'roman-tab-root') {
    return 'virtual:roman-tab-root';
  }
  if (typeof node.path !== 'string' || !node.path.trim()) {
    return '';
  }
  return toProjectTreeBindingKey(projectRoot, node.path);
}

function collectProjectTreeIdentityDescriptors(roots, projectRoot) {
  const descriptors = [];
  const visit = (node) => {
    if (!node || typeof node !== 'object') return;
    const bindingKey = getProjectTreeIdentityBindingKey(node, projectRoot);
    if (!bindingKey || typeof node.kind !== 'string' || !node.kind.trim()) {
      throw new Error('PROJECT_TREE_IDENTITY_DESCRIPTOR_INVALID');
    }
    descriptors.push({ bindingKey, kind: node.kind });
    if (Array.isArray(node.children)) {
      node.children.forEach(visit);
    }
  };
  roots.forEach(visit);
  return descriptors;
}

function annotateProjectTreeIdentities(roots, projectRoot, bindings) {
  const visit = (node) => {
    if (!node || typeof node !== 'object') return;
    const bindingKey = getProjectTreeIdentityBindingKey(node, projectRoot);
    const nodeId = bindingKey && bindings ? bindings[bindingKey] : '';
    if (!nodeId) {
      throw new Error('PROJECT_TREE_IDENTITY_BINDING_MISSING');
    }
    node.nodeId = nodeId;
    if (Array.isArray(node.children)) {
      node.children.forEach(visit);
    }
  };
  roots.forEach(visit);
}

async function persistProjectTreeIdentityMigration(manifestPath, projectRoot, sourceText, manifest) {
  const backupResult = await backupManager.createBackup(manifestPath, sourceText, { basePath: projectRoot });
  if (!backupResult || backupResult.success !== true) {
    throw new Error(backupResult?.error || 'PROJECT_TREE_IDENTITY_BACKUP_FAILED');
  }
  await persistProjectManifestAtPath(manifestPath, manifest, 'save project tree identity registry', {
    expectedText: sourceText,
  });
}

async function createProjectTreeMoveRecovery(manifestPath, projectRoot, sourceText, options = {}) {
  const manifestHash = computeHash(sourceText);
  let recovery = {
    snapshotCreated: false,
    snapshotReadable: false,
    snapshotHashMatchesInput: false,
    manifestHash,
  };
  try {
    const markdownIo = await loadMarkdownIoModule();
    if (!markdownIo || typeof markdownIo.createMarkdownRecoveryPack !== 'function') {
      return recovery;
    }
    const outputRoot = joinPathSegmentsWithinRoot(
      projectRoot,
      ['backups', 'tree-move-recovery'],
      { resolveSymlinks: false },
    );
    const pack = await markdownIo.createMarkdownRecoveryPack(manifestPath, {
      text: sourceText,
      outputRoot,
      sourceKind: 'project-tree-move-manifest',
      recoveryAction: 'OPEN_SNAPSHOT',
      ...(typeof options.now === 'function' ? { now: options.now } : {}),
    });
    if (pack && pack.ok === 1 && typeof pack.contentPath === 'string') {
      let recoveredText = '';
      try {
        recoveredText = await fs.readFile(pack.contentPath, 'utf8');
      } catch {}
      recovery = {
        snapshotCreated: true,
        snapshotReadable: recoveredText.length > 0 || sourceText.length === 0,
        snapshotHashMatchesInput: computeHash(recoveredText) === manifestHash,
        manifestHash,
        recoveryPackCreated: true,
      };
    }
  } catch (error) {
    logDevError('project tree move recovery', error);
  }
  return recovery;
}

async function reconcileProjectTreeIdentities(roots, projectName = currentProjectName || DEFAULT_PROJECT_NAME) {
  const { manifestPath, manifest } = await ensureProjectManifest(projectName);
  const projectRoot = path.dirname(manifestPath);
  const descriptors = collectProjectTreeIdentityDescriptors(roots, projectRoot);
  const identityModule = await loadProjectTreeIdentityModule();
  const result = identityModule.reconcileProjectTreeIdentity({
    projectId: manifest.projectId,
    registry: manifest.treeIdentity,
    descriptors,
  });
  if (!result.ok) {
    const error = new Error(result.error?.reason || 'PROJECT_TREE_IDENTITY_RECONCILE_FAILED');
    error.code = result.error?.code || 'E_TREE_IDENTITY_RECONCILE_FAILED';
    error.details = result.error?.details || {};
    throw error;
  }
  if (result.changed) {
    const sourceText = await fs.readFile(manifestPath, 'utf8');
    const nextManifest = {
      ...manifest,
      treeIdentity: result.value,
    };
    await persistProjectTreeIdentityMigration(manifestPath, projectRoot, sourceText, nextManifest);
  }
  annotateProjectTreeIdentities(Object.values(roots), projectRoot, result.bindings);
  return {
    projectId: manifest.projectId,
    roots,
  };
}

async function annotateProjectTreeDerivedCounters(roots, projectName = currentProjectName || DEFAULT_PROJECT_NAME) {
  const counterModule = await loadNavigatorCountersModule();
  if (!counterModule || typeof counterModule.annotateNavigatorDerivedCounters !== 'function') {
    return {
      changedSceneIds: [],
      affectedNodeIds: [],
    };
  }
  const readText = async (node) => {
    if (!node || typeof node !== 'object') return '';
    const nodePath = typeof node.path === 'string' ? node.path : '';
    const kind = typeof node.kind === 'string' ? node.kind : '';
    if (!nodePath || (kind !== 'scene' && kind !== 'chapter-file')) return '';
    const projectRoot = getProjectRootPath(projectName);
    const guard = sanitizePayloadWithinProjectRoot({ path: nodePath }, ['path'], projectRoot);
    if (!guard.ok || !guard.payload) return '';
    try {
      return await fs.readFile(guard.payload.path, 'utf8');
    } catch (error) {
      if (error && error.code !== 'ENOENT') logDevError('project tree derived counter read', error);
      return '';
    }
  };
  const changedSceneIds = new Set();
  const affectedNodeIds = new Set();
  for (const root of roots) {
    const result = await counterModule.annotateNavigatorDerivedCounters(root, { readText });
    for (const nodeId of result.changedSceneIds || []) changedSceneIds.add(nodeId);
    for (const nodeId of result.affectedNodeIds || []) affectedNodeIds.add(nodeId);
  }
  return {
    changedSceneIds: Array.from(changedSceneIds).sort(),
    affectedNodeIds: Array.from(affectedNodeIds).sort(),
  };
}

function serializeProjectTreeDerivedCounters(counters) {
  if (!counters || typeof counters !== 'object' || Array.isArray(counters)) {
    return null;
  }
  const wordCount = Number.isInteger(counters.wordCount) ? Math.max(0, counters.wordCount) : 0;
  const sceneCount = Number.isInteger(counters.sceneCount) ? Math.max(0, counters.sceneCount) : 0;
  const completedSceneCount = Number.isInteger(counters.completedSceneCount)
    ? Math.max(0, counters.completedSceneCount)
    : 0;
  const progressPercent = Number.isInteger(counters.progressPercent)
    ? Math.min(100, Math.max(0, counters.progressPercent))
    : 0;
  const affectedByChangedSceneIds = Array.isArray(counters.affectedByChangedSceneIds)
    ? counters.affectedByChangedSceneIds
      .filter((value) => typeof value === 'string' && /^tree-node-[a-f0-9]{32}$/u.test(value))
      .slice()
      .sort()
    : [];
  return {
    wordCount,
    sceneCount,
    completedSceneCount,
    progressPercent,
    affectedByChangedSceneIds,
  };
}

function serializeProjectTreeNode(node) {
  if (!node || typeof node !== 'object' || Array.isArray(node)) {
    throw new Error('PROJECT_TREE_PUBLIC_NODE_INVALID');
  }
  const nodeId = typeof node.nodeId === 'string' ? node.nodeId.trim() : '';
  const kind = typeof node.kind === 'string' ? node.kind.trim() : '';
  const label = typeof node.label === 'string'
    ? node.label
    : (typeof node.name === 'string' ? node.name : '');
  if (!nodeId || !kind) {
    throw new Error('PROJECT_TREE_PUBLIC_IDENTITY_MISSING');
  }
  const derivedCounters = serializeProjectTreeDerivedCounters(node.derivedCounters);
  return {
    id: nodeId,
    nodeId,
    name: label,
    label,
    kind,
    children: Array.isArray(node.children) ? node.children.map(serializeProjectTreeNode) : [],
    ...(derivedCounters ? { derivedCounters } : {}),
    ...(node.imported === true ? { imported: true } : {}),
  };
}

async function buildProjectTreeRootsWithIdentities(projectName = currentProjectName || DEFAULT_PROJECT_NAME) {
  const romanRoot = await buildRomanTree(projectName);
  const mindmapRoot = await buildMindMapTree(projectName);
  const printRoot = await buildPrintTree(projectName);
  const roots = {
    roman: buildNode({
      name: 'Roman tab',
      label: 'Roman',
      kind: 'roman-tab-root',
      nodePath: getProjectRootPath(projectName),
      children: [romanRoot, mindmapRoot, printRoot],
    }),
    materials: await buildMaterialsTree(projectName),
    reference: await buildReferenceTree(projectName),
  };
  const identity = await reconcileProjectTreeIdentities(Object.values(roots), projectName);
  await annotateProjectTreeDerivedCounters(Object.values(roots), projectName);
  return {
    projectId: identity.projectId,
    roots,
  };
}

async function buildProjectTreeRootsWithIdentitiesReadOnly() {
  const activeProjectName = currentProjectName || DEFAULT_PROJECT_NAME;
  const manifestRecord = await readProjectManifest(activeProjectName);
  if (!manifestRecord || !manifestRecord.manifest) {
    const error = new Error('PROJECT_MANIFEST_UNAVAILABLE');
    error.code = 'E_PROJECT_MANIFEST_UNAVAILABLE';
    throw error;
  }
  const manifestPath = getProjectManifestPath(activeProjectName);
  const projectRoot = path.dirname(manifestPath);
  const manifest = manifestRecord.manifest;
  const romanRoot = await buildRomanTree();
  const mindmapRoot = await buildMindMapTree();
  const printRoot = await buildPrintTree();
  const roots = {
    roman: buildNode({
      name: 'Roman tab',
      label: 'Roman',
      kind: 'roman-tab-root',
      nodePath: getProjectRootPath(),
      children: [romanRoot, mindmapRoot, printRoot],
    }),
    materials: await buildMaterialsTree(),
    reference: await buildReferenceTree(),
  };
  const descriptors = collectProjectTreeIdentityDescriptors(Object.values(roots), projectRoot);
  const identityModule = await loadProjectTreeIdentityModule();
  const result = identityModule.reconcileProjectTreeIdentity({
    projectId: manifest.projectId,
    registry: manifest.treeIdentity,
    descriptors,
  });
  if (!result.ok) {
    const error = new Error(result.error?.reason || 'PROJECT_TREE_IDENTITY_READ_FAILED');
    error.code = result.error?.code || 'E_TREE_IDENTITY_READ_FAILED';
    throw error;
  }
  const effectiveManifest = result.changed
    ? { ...manifest, treeIdentity: result.value }
    : manifest;
  annotateProjectTreeIdentities(Object.values(roots), projectRoot, result.bindings);
  await annotateProjectTreeDerivedCounters(Object.values(roots));
  return {
    projectId: manifest.projectId,
    roots,
    manifestPath,
    manifest: effectiveManifest,
    manifestRaw: manifestRecord.raw,
    readOnlyIdentityChanged: result.changed === true,
  };
}

async function resolveProjectTreeNodeIdentity(nodeId, expectedProjectId = '') {
  const normalizedNodeId = typeof nodeId === 'string' ? nodeId.trim() : '';
  if (!/^tree-node-[a-f0-9]{32}$/u.test(normalizedNodeId)) {
    const error = new Error('TREE_NODE_ID_INVALID');
    error.code = 'E_TREE_NODE_ID_INVALID';
    throw error;
  }
  const { manifestPath, manifest, manifestRaw } = await ensureProjectManifest(DEFAULT_PROJECT_NAME);
  const normalizedExpectedProjectId = typeof expectedProjectId === 'string' ? expectedProjectId.trim() : '';
  if (normalizedExpectedProjectId && normalizedExpectedProjectId !== manifest.projectId) {
    const error = new Error('TREE_NODE_PROJECT_MISMATCH');
    error.code = 'E_TREE_NODE_PROJECT_MISMATCH';
    throw error;
  }
  const identityModule = await loadProjectTreeIdentityModule();
  const normalized = identityModule.normalizeProjectTreeIdentity(manifest.treeIdentity);
  if (!normalized.ok) {
    const error = new Error(normalized.error?.reason || 'TREE_IDENTITY_INVALID');
    error.code = normalized.error?.code || 'E_TREE_IDENTITY_INVALID';
    throw error;
  }
  const record = normalized.value.nodes[normalizedNodeId];
  if (!record || record.present === false || !record.bindingKey.startsWith('file:')) {
    const error = new Error('TREE_NODE_NOT_FOUND');
    error.code = 'E_TREE_NODE_NOT_FOUND';
    throw error;
  }
  const projectRoot = path.dirname(manifestPath);
  const relativePath = record.bindingKey.slice('file:'.length);
  const nodePath = joinPathSegmentsWithinRoot(projectRoot, relativePath.split('/'), {
    resolveSymlinks: false,
  });
  const pathGuard = sanitizePathFieldsWithinRoot({ path: nodePath }, ['path'], projectRoot, {
    mode: 'any',
    resolveSymlinks: true,
  });
  if (!pathGuard.ok || !pathGuard.payload) {
    const error = new Error('TREE_NODE_PATH_BOUNDARY_VIOLATION');
    error.code = 'E_PATH_BOUNDARY_VIOLATION';
    throw error;
  }
  return {
    projectId: manifest.projectId,
    projectRoot,
    manifestPath,
    manifest,
    manifestRaw,
    nodeId: normalizedNodeId,
    nodePath: pathGuard.payload.path,
    kind: record.kind,
  };
}

function normalizeProjectRelativeSceneId(value) {
  const normalized = typeof value === 'string'
    ? value.trim().replace(/\\/g, '/').replace(/^\/+/u, '')
    : '';
  if (
    !normalized
    || normalized.length > 512
    || /[\u0000-\u001F]/u.test(normalized)
    || !normalized.startsWith('roman/')
    || !normalized.toLowerCase().endsWith('.txt')
  ) {
    return '';
  }
  const segments = normalized.split('/');
  if (
    segments.some((segment) => !segment || segment === '.' || segment === '..')
    || segments.some((segment) => segment.startsWith('.'))
  ) {
    return '';
  }
  return normalized;
}

async function resolveProjectTreeSceneIdentity(sceneId, expectedProjectId = '') {
  const normalizedSceneId = normalizeProjectRelativeSceneId(sceneId);
  if (!normalizedSceneId) {
    const error = new Error('TREE_SCENE_ID_INVALID');
    error.code = 'E_TREE_SCENE_ID_INVALID';
    throw error;
  }
  const { manifestPath, manifest } = await ensureProjectManifest(currentProjectName || DEFAULT_PROJECT_NAME);
  const normalizedExpectedProjectId = typeof expectedProjectId === 'string' ? expectedProjectId.trim() : '';
  if (normalizedExpectedProjectId && normalizedExpectedProjectId !== manifest.projectId) {
    const error = new Error('TREE_NODE_PROJECT_MISMATCH');
    error.code = 'E_TREE_NODE_PROJECT_MISMATCH';
    throw error;
  }
  const projectRoot = path.dirname(manifestPath);
  const nodePath = joinPathSegmentsWithinRoot(projectRoot, normalizedSceneId.split('/'), {
    resolveSymlinks: false,
  });
  const pathGuard = sanitizePathFieldsWithinRoot({ path: nodePath }, ['path'], projectRoot, {
    mode: 'any',
    resolveSymlinks: true,
  });
  if (!pathGuard.ok || !pathGuard.payload) {
    const error = new Error('TREE_SCENE_PATH_BOUNDARY_VIOLATION');
    error.code = 'E_PATH_BOUNDARY_VIOLATION';
    throw error;
  }
  const identity = await upsertProjectTreeIdentityForPath(pathGuard.payload.path, 'scene');
  return {
    projectId: manifest.projectId,
    projectRoot,
    manifestPath,
    manifest,
    nodeId: identity.nodeId,
    nodePath: pathGuard.payload.path,
    kind: 'scene',
    sceneId: normalizedSceneId,
  };
}

async function getProjectDocumentIdentityPayload(filePath) {
  const projectRoot = getProjectRootPath();
  if (typeof filePath !== 'string' || !filePath.trim() || !isPathInside(projectRoot, filePath)) {
    const normalizedPath = typeof filePath === 'string' && filePath.trim()
      ? path.resolve(filePath)
      : '';
    return {
      documentId: normalizedPath
        ? `external-document-${computeHash(normalizedPath).slice(0, 32)}`
        : '',
    };
  }
  try {
    const projectTree = await buildProjectTreeRootsWithIdentitiesReadOnly();
    const { manifestPath, manifest } = projectTree;
    const normalizedPath = path.basename(filePath).toLowerCase() === '.index.txt'
      ? path.dirname(filePath)
      : filePath;
    const bindingKey = toProjectTreeBindingKey(path.dirname(manifestPath), normalizedPath);
    const identityModule = await loadProjectTreeIdentityModule();
    const normalized = identityModule.normalizeProjectTreeIdentity(manifest.treeIdentity);
    if (!normalized.ok) throw new Error(normalized.error?.reason || 'TREE_IDENTITY_INVALID');
    const existing = Object.entries(normalized.value.nodes)
      .find(([, record]) => record.present !== false && record.bindingKey === bindingKey);
    if (existing) return { documentId: existing[0] };
    const documentId = identityModule.createDeterministicTreeNodeId(manifest.projectId, bindingKey);
    if (documentId) return { documentId };
    const resolutionError = new Error('PROJECT_DOCUMENT_IDENTITY_READONLY_UNBOUND');
    resolutionError.code = 'E_PROJECT_DOCUMENT_IDENTITY_READONLY_UNBOUND';
    throw resolutionError;
  } catch (error) {
    logDevError('project document identity payload', error);
    try {
      const activeProjectName = currentProjectName || DEFAULT_PROJECT_NAME;
      const manifestRecord = await readProjectManifest(activeProjectName);
      const manifest = manifestRecord && manifestRecord.manifest ? manifestRecord.manifest : null;
      const manifestPath = getProjectManifestPath(activeProjectName);
      const projectRoot = path.dirname(manifestPath);
      const normalizedPath = path.basename(filePath).toLowerCase() === '.index.txt'
        ? path.dirname(filePath)
        : filePath;
      const bindingKey = toProjectTreeBindingKey(projectRoot, normalizedPath);
      if (manifest && bindingKey) {
        const identityModule = await loadProjectTreeIdentityModule();
        const documentId = identityModule.createDeterministicTreeNodeId(manifest.projectId, bindingKey);
        if (documentId) {
          return { documentId };
        }
      }
    } catch (fallbackError) {
      logDevError('project document identity payload fallback', fallbackError);
    }
    const resolutionError = new Error('PROJECT_DOCUMENT_IDENTITY_UNAVAILABLE');
    resolutionError.code = 'E_PROJECT_DOCUMENT_IDENTITY_UNAVAILABLE';
    throw resolutionError;
  }
}

function getResolvedTreeDocumentTarget(resolvedNode) {
  const kind = resolvedNode.kind;
  if (kind === 'materials-category' || kind === 'reference-category') {
    return {
      filePath: joinPathSegmentsWithinRoot(resolvedNode.nodePath, ['.index.txt'], {
        resolveSymlinks: false,
      }),
      kind: kind === 'materials-category' ? 'material' : 'reference',
    };
  }
  const openableKinds = new Set([
    'chapter-file',
    'scene',
    'material',
    'reference',
    'roman-section',
    'mindmap-section',
    'print-section',
  ]);
  if (!openableKinds.has(kind)) {
    const error = new Error('TREE_NODE_NOT_DOCUMENT');
    error.code = 'E_TREE_NODE_NOT_DOCUMENT';
    throw error;
  }
  return { filePath: resolvedNode.nodePath, kind };
}

async function upsertProjectTreeIdentityForPath(candidatePath, kind) {
  const { manifestPath, manifest } = await ensureProjectManifest(currentProjectName || DEFAULT_PROJECT_NAME);
  const projectRoot = path.dirname(manifestPath);
  const identityModule = await loadProjectTreeIdentityModule();
  const result = identityModule.upsertProjectTreeIdentityNode({
    projectId: manifest.projectId,
    registry: manifest.treeIdentity,
    bindingKey: toProjectTreeBindingKey(projectRoot, candidatePath),
    kind,
  });
  if (!result.ok) {
    const error = new Error(result.error?.reason || 'PROJECT_TREE_IDENTITY_UPSERT_FAILED');
    error.code = result.error?.code || 'E_TREE_IDENTITY_UPSERT_FAILED';
    throw error;
  }
  if (result.changed) {
    const sourceText = await fs.readFile(manifestPath, 'utf8');
    await persistProjectTreeIdentityMigration(
      manifestPath,
      projectRoot,
      sourceText,
      { ...manifest, treeIdentity: result.value },
    );
  }
  return { nodeId: result.nodeId, projectId: manifest.projectId };
}

async function rebindProjectTreeIdentityForPaths(fromPath, toPath) {
  const { manifestPath, manifest } = await ensureProjectManifest(currentProjectName || DEFAULT_PROJECT_NAME);
  if (!manifest.treeIdentity) {
    return { changed: false, movedNodeIds: [] };
  }
  const projectRoot = path.dirname(manifestPath);
  const identityModule = await loadProjectTreeIdentityModule();
  const result = identityModule.rebindProjectTreeIdentity({
    registry: manifest.treeIdentity,
    fromBindingKey: toProjectTreeBindingKey(projectRoot, fromPath),
    toBindingKey: toProjectTreeBindingKey(projectRoot, toPath),
  });
  if (!result.ok) {
    const error = new Error(result.error?.reason || 'PROJECT_TREE_IDENTITY_REBIND_FAILED');
    error.code = result.error?.code || 'E_TREE_IDENTITY_REBIND_FAILED';
    throw error;
  }
  if (result.changed) {
    const sourceText = await fs.readFile(manifestPath, 'utf8');
    await persistProjectTreeIdentityMigration(
      manifestPath,
      projectRoot,
      sourceText,
      { ...manifest, treeIdentity: result.value },
    );
  }
  return {
    changed: result.changed,
    movedNodeIds: result.movedNodeIds,
  };
}

async function rebindProjectTreeIdentityForMoves(pathMoves) {
  const moves = Array.isArray(pathMoves)
    ? pathMoves.filter((move) => move && move.fromPath !== move.toPath)
    : [];
  if (moves.length === 0) return { changed: false, movedNodeIds: [] };
  const { manifestPath, manifest } = await ensureProjectManifest(currentProjectName || DEFAULT_PROJECT_NAME);
  if (!manifest.treeIdentity) return { changed: false, movedNodeIds: [] };
  const projectRoot = path.dirname(manifestPath);
  const identityModule = await loadProjectTreeIdentityModule();
  const result = identityModule.rebindProjectTreeIdentityBatch({
    registry: manifest.treeIdentity,
    moves: moves.map((move) => ({
      fromBindingKey: toProjectTreeBindingKey(projectRoot, move.fromPath),
      toBindingKey: toProjectTreeBindingKey(projectRoot, move.toPath),
    })),
  });
  if (!result.ok) {
    const error = new Error(result.error?.reason || 'PROJECT_TREE_IDENTITY_REBIND_FAILED');
    error.code = result.error?.code || 'E_TREE_IDENTITY_REBIND_FAILED';
    throw error;
  }
  if (result.changed) {
    const sourceText = await fs.readFile(manifestPath, 'utf8');
    await persistProjectTreeIdentityMigration(
      manifestPath,
      projectRoot,
      sourceText,
      { ...manifest, treeIdentity: result.value },
    );
  }
  return { changed: result.changed, movedNodeIds: result.movedNodeIds };
}

function getTreeParentNodeIdFromResolvedPath(parentPath, manifest) {
  if (!manifest || !manifest.treeIdentity || !parentPath) return '';
  const projectRoot = getProjectRootPath();
  const bindingKey = toProjectTreeBindingKey(projectRoot, parentPath);
  if (!bindingKey) return '';
  const nodes = manifest.treeIdentity.nodes && typeof manifest.treeIdentity.nodes === 'object'
    ? manifest.treeIdentity.nodes
    : {};
  const match = Object.entries(nodes).find(([, record]) => (
    record
    && typeof record === 'object'
    && record.present !== false
    && record.bindingKey === bindingKey
  ));
  return match ? match[0] : '';
}

function getTreeNodeIdsForOrderedEntries(parentPath, entries, manifest) {
  if (!manifest || !manifest.treeIdentity || !parentPath || !Array.isArray(entries)) return [];
  const projectRoot = getProjectRootPath();
  const nodes = manifest.treeIdentity.nodes && typeof manifest.treeIdentity.nodes === 'object'
    ? manifest.treeIdentity.nodes
    : {};
  const byBindingKey = new Map();
  for (const [nodeId, record] of Object.entries(nodes)) {
    if (
      typeof nodeId === 'string'
      && record
      && typeof record === 'object'
      && record.present !== false
      && typeof record.bindingKey === 'string'
    ) {
      byBindingKey.set(record.bindingKey, nodeId);
    }
  }
  return entries
    .map((entry) => byBindingKey.get(toProjectTreeBindingKey(projectRoot, entry.path)) || '')
    .filter((nodeId) => typeof nodeId === 'string' && nodeId.trim());
}

async function buildImportedRomanTree(romanPath) {
  const importedPath = joinPathSegmentsWithinRoot(romanPath, ['Imported'], {
    resolveSymlinks: false,
  });
  if (!(await fileExists(importedPath))) {
    return null;
  }

  const entries = await readDirectoryEntries(importedPath);
  const children = entries
    .filter((entry) => entry.isFile && entry.name.toLowerCase().endsWith('.txt'))
    .map((entry) => buildNode({
      name: entry.baseName,
      label: entry.baseName,
      kind: 'scene',
      nodePath: entry.path,
      children: [],
    }));

  if (children.length === 0) {
    return null;
  }

  return buildNode({
    name: 'Imported',
    label: 'Imported',
    kind: 'chapter-folder',
    nodePath: importedPath,
    children,
    imported: true,
  });
}

async function buildRomanTree(projectName = DEFAULT_PROJECT_NAME) {
  const romanPath = getProjectSectionPath('roman', projectName);
  const childNodes = ROMAN_SECTION_LABELS.map((label) =>
    buildNode({
      name: label,
      label,
      kind: 'roman-section',
      nodePath: joinPathSegmentsWithinRoot(romanPath, [`${sanitizeFilename(label)}.txt`], {
        resolveSymlinks: false,
      }),
      children: []
    })
  );
  const importedNode = await buildImportedRomanTree(romanPath);
  if (importedNode) {
    childNodes.push(importedNode);
  }

  return buildNode({
    name: 'Роман',
    label: 'Роман',
    kind: 'roman-root',
    nodePath: romanPath,
    children: childNodes
  });
}

async function buildMindMapTree(projectName = DEFAULT_PROJECT_NAME) {
  const mindmapPath = getProjectSectionPath('mindmap', projectName);
  const childNodes = ROMAN_MIND_MAP_SECTION_LABELS.map((label) =>
    buildNode({
      name: label,
      label,
      kind: 'mindmap-section',
      nodePath: joinPathSegmentsWithinRoot(mindmapPath, [`${sanitizeFilename(label)}.txt`], {
        resolveSymlinks: false,
      }),
      children: []
    })
  );

  return buildNode({
    name: 'Mind map',
    label: 'Mind map',
    kind: 'mindmap-root',
    nodePath: mindmapPath,
    children: childNodes
  });
}

async function buildPrintTree(projectName = DEFAULT_PROJECT_NAME) {
  const printPath = getProjectSectionPath('print', projectName);
  const childNodes = PRINT_SECTION_LABELS.map((label) =>
    buildNode({
      name: label,
      label,
      kind: 'print-section',
      nodePath: joinPathSegmentsWithinRoot(printPath, [`${sanitizeFilename(label)}.txt`], {
        resolveSymlinks: false,
      }),
      children: []
    })
  );

  return buildNode({
    name: 'Печать',
    label: 'Печать',
    kind: 'print-root',
    nodePath: printPath,
    children: childNodes
  });
}

async function buildGenericTree(rootPath, kind) {
  const entries = await readDirectoryEntries(rootPath);
  const nodes = [];
  for (const entry of entries) {
    if (entry.isDirectory) {
      const children = await buildGenericTree(entry.path, kind);
      nodes.push(
        buildNode({
          name: entry.baseName,
          label: entry.baseName,
          kind: 'folder',
          nodePath: entry.path,
          children: children.children || []
        })
      );
      continue;
    }
    if (entry.isFile && entry.name.toLowerCase().endsWith('.txt')) {
      nodes.push(
        buildNode({
          name: entry.baseName,
          label: entry.baseName,
          kind: kind === 'materials' ? 'material' : 'reference',
          nodePath: entry.path,
          children: []
        })
      );
    }
  }

  return buildNode({
    name: rootPath,
    label: path.basename(rootPath),
    kind: 'folder',
    nodePath: rootPath,
    children: nodes
  });
}

async function buildMaterialsTree(projectName = DEFAULT_PROJECT_NAME) {
  const materialsPath = getProjectSectionPath('materials', projectName);
  const categoryNodes = [];
  for (const section of MATERIALS_SECTIONS) {
    const folderPath = joinPathSegmentsWithinRoot(materialsPath, [section.dirName], { resolveSymlinks: false });
    const subtree = await buildGenericTree(folderPath, 'materials');
    categoryNodes.push(
      buildNode({
        name: section.label,
        label: section.label,
        kind: 'materials-category',
        nodePath: folderPath,
        children: subtree.children || []
      })
    );
  }

  return buildNode({
    name: 'Материалы',
    label: 'Материалы',
    kind: 'materials-root',
    nodePath: materialsPath,
    children: categoryNodes
  });
}

async function buildReferenceTree(projectName = DEFAULT_PROJECT_NAME) {
  const referencePath = getProjectSectionPath('reference', projectName);
  const categoryNodes = [];
  for (const section of REFERENCE_SECTIONS) {
    const folderPath = joinPathSegmentsWithinRoot(referencePath, [section.dirName], { resolveSymlinks: false });
    const subtree = await buildGenericTree(folderPath, 'reference');
    categoryNodes.push(
      buildNode({
        name: section.label,
        label: section.label,
        kind: 'reference-category',
        nodePath: folderPath,
        children: subtree.children || []
      })
    );
  }

  return buildNode({
    name: 'Справочник',
    label: 'Справочник',
    kind: 'reference-root',
    nodePath: referencePath,
    children: categoryNodes
  });
}

function getDocumentContextFromPath(filePath) {
  const projectRoot = getProjectRootPath();
  const relative = path.relative(projectRoot, filePath);
  const baseTitle = getDisplayNameForEntry(path.basename(filePath));
  const lowerBaseName = path.basename(filePath).toLowerCase();

  if (!relative || relative.startsWith('..')) {
    return { title: baseTitle, kind: 'external', metaEnabled: false };
  }

  const parts = relative.split(path.sep);
  if (parts[0] === PROJECT_SUBFOLDERS.roman) {
    if (parts.length >= 2) {
      if (parts.length === 2 && parts[1].toLowerCase().endsWith('.txt')) {
        const normalizedName = sanitizeFilename(stripTxtExtension(parts[1])).toLowerCase();
        if (ROMAN_SECTION_FILENAME_SET.has(normalizedName)) {
          return { title: baseTitle, kind: 'roman-section', metaEnabled: false };
        }
        return { title: baseTitle, kind: 'chapter-file', metaEnabled: true };
      }
      if (
        parts.length === 3
        && parts[1].toLowerCase() === 'imported'
        && parts[2].toLowerCase().endsWith('.txt')
      ) {
        return { title: baseTitle, kind: 'scene', metaEnabled: true };
      }
      if (parts.length === 3 && parts[2].toLowerCase().endsWith('.txt')) {
        return { title: baseTitle, kind: 'chapter-file', metaEnabled: true };
      }
      if (parts.length >= 4 && parts[3].toLowerCase().endsWith('.txt')) {
        return { title: baseTitle, kind: 'scene', metaEnabled: true };
      }
    }
  }

  if (parts[0] === PROJECT_SUBFOLDERS.mindmap) {
    if (parts.length === 2 && parts[1].toLowerCase().endsWith('.txt')) {
      return { title: baseTitle, kind: 'mindmap-section', metaEnabled: false };
    }
  }

  if (parts[0] === PROJECT_SUBFOLDERS.print) {
    if (parts.length === 2 && parts[1].toLowerCase().endsWith('.txt')) {
      return { title: baseTitle, kind: 'print-section', metaEnabled: false };
    }
  }

  if (parts[0] === PROJECT_SUBFOLDERS.materials) {
    if (lowerBaseName === '.index.txt' && parts.length >= 3) {
      const category = MATERIALS_SECTIONS.find((section) => section.dirName === parts[1]);
      return { title: category ? category.label : baseTitle, kind: 'material', metaEnabled: false };
    }
    return { title: baseTitle, kind: 'material', metaEnabled: false };
  }

  if (parts[0] === PROJECT_SUBFOLDERS.reference) {
    if (lowerBaseName === '.index.txt' && parts.length >= 3) {
      const category = REFERENCE_SECTIONS.find((section) => section.dirName === parts[1]);
      return { title: category ? category.label : baseTitle, kind: 'reference', metaEnabled: false };
    }
    return { title: baseTitle, kind: 'reference', metaEnabled: false };
  }

  return { title: baseTitle, kind: 'external', metaEnabled: false };
}

function getBackupBasePathForFile(filePath) {
  if (!filePath) return null;
  const projectRoot = getProjectRootPath();
  return isPathInside(projectRoot, filePath) ? projectRoot : null;
}

async function safeRenameSequence(renames) {
  const timestamp = Date.now();
  const tempSuffix = `.tmp-${timestamp}`;
  const tempMappings = [];
  for (const rename of renames) {
    const tempPath = `${rename.from}${tempSuffix}`;
    await fs.rename(rename.from, tempPath);
    tempMappings.push({ tempPath, finalPath: rename.to });
  }
  for (const mapping of tempMappings) {
    await fs.rename(mapping.tempPath, mapping.finalPath);
  }
}

async function reorderEntriesWithPrefixes(parentPath, orderedEntries) {
  const renames = [];
  orderedEntries.forEach((entry, index) => {
    const baseName = entry.baseName;
    const prefixed = formatPrefixedName(baseName, index + 1);
    const finalName = entry.isFile ? `${prefixed}.txt` : prefixed;
    const finalPath = joinPathSegmentsWithinRoot(parentPath, [finalName], { resolveSymlinks: false });
    if (entry.path !== finalPath) {
      renames.push({ from: entry.path, to: finalPath });
    }
    entry.nextPath = finalPath;
  });

  if (!renames.length) {
    return orderedEntries;
  }

  await safeRenameSequence(renames);
  return orderedEntries;
}

const TREE_MOVE_ALLOWED_NODE_KINDS = new Set([
  'part',
  'chapter-folder',
  'chapter-file',
  'scene',
]);
const TREE_MOVE_ALLOWED_PARENT_KINDS = new Set([
  'roman-root',
  'part',
  'chapter-folder',
]);
const TREE_MOVE_ALLOWED_PAYLOAD_KEYS = Object.freeze([
  'projectId',
  'nodeId',
  'targetParentNodeId',
  'targetIndex',
]);
const TREE_MOVE_FORBIDDEN_AUTHORITY_KEYS = Object.freeze([
  'fromPath',
  'path',
  'projectRoot',
  'receipt',
  'recovery',
  'scenePath',
  'targetPath',
  'toPath',
]);

function makeTreeMoveError(code, reason, details = {}) {
  return {
    ok: false,
    error: code,
    code,
    reason,
    ...(details && typeof details === 'object' && !Array.isArray(details) ? { details } : {}),
  };
}

function normalizeTreeMovePayload(payload = {}) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return makeTreeMoveError('E_TREE_MOVE_PAYLOAD_INVALID', 'TREE_MOVE_PAYLOAD_REQUIRED');
  }
  const keys = Object.keys(payload);
  const forbidden = keys.filter((key) => TREE_MOVE_FORBIDDEN_AUTHORITY_KEYS.includes(key)).sort();
  if (forbidden.length > 0) {
    return makeTreeMoveError('E_TREE_MOVE_PAYLOAD_INVALID', 'TREE_MOVE_RENDERER_AUTHORITY_DENIED', {
      fields: forbidden,
    });
  }
  const unsupported = keys.filter((key) => !TREE_MOVE_ALLOWED_PAYLOAD_KEYS.includes(key)).sort();
  if (unsupported.length > 0) {
    return makeTreeMoveError('E_TREE_MOVE_PAYLOAD_INVALID', 'TREE_MOVE_PAYLOAD_UNSUPPORTED_FIELDS', {
      fields: unsupported,
    });
  }
  const projectId = typeof payload.projectId === 'string' ? payload.projectId.trim() : '';
  const nodeId = typeof payload.nodeId === 'string' ? payload.nodeId.trim() : '';
  const targetParentNodeId = typeof payload.targetParentNodeId === 'string'
    ? payload.targetParentNodeId.trim()
    : '';
  const targetIndex = Number.isInteger(payload.targetIndex) ? payload.targetIndex : -1;
  if (!projectId || !nodeId || !targetParentNodeId || targetIndex < 0) {
    return makeTreeMoveError('E_TREE_MOVE_PAYLOAD_INVALID', 'TREE_MOVE_PAYLOAD_INVALID');
  }
  return {
    ok: true,
    value: {
      projectId,
      nodeId,
      targetParentNodeId,
      targetIndex,
    },
  };
}

function buildOrderedTreeMoveRenames(parentPath, orderedEntries) {
  const renames = [];
  orderedEntries.forEach((entry, index) => {
    const prefixed = formatPrefixedName(entry.baseName, index + 1);
    const finalName = entry.isFile ? `${prefixed}.txt` : prefixed;
    const finalPath = joinPathSegmentsWithinRoot(parentPath, [finalName], { resolveSymlinks: false });
    entry.nextPath = finalPath;
    if (entry.path !== finalPath) {
      renames.push({ from: entry.path, to: finalPath });
    }
  });
  return renames;
}

function dedupeRenames(renames) {
  const seen = new Set();
  const result = [];
  for (const rename of renames) {
    if (!rename || rename.from === rename.to) continue;
    const key = `${rename.from}\u0000${rename.to}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(rename);
  }
  return result;
}

async function buildTreeMovePlan(nodePath, targetParentPath, targetIndex) {
  const sourceParentPath = path.dirname(nodePath);
  const sameParent = sourceParentPath === targetParentPath;
  const sourceEntries = await readDirectoryEntries(sourceParentPath);
  const movingEntry = sourceEntries.find((entry) => entry.path === nodePath);
  if (!movingEntry) {
    return makeTreeMoveError('E_TREE_MOVE_NODE_NOT_FOUND', 'TREE_MOVE_NODE_NOT_FOUND');
  }

  if (sameParent) {
    const withoutMoving = sourceEntries.filter((entry) => entry.path !== nodePath);
    if (targetIndex > withoutMoving.length) {
      return makeTreeMoveError('E_TREE_MOVE_TARGET_INDEX_INVALID', 'TREE_MOVE_TARGET_INDEX_INVALID');
    }
    const ordered = withoutMoving.slice();
    ordered.splice(targetIndex, 0, movingEntry);
    const renames = buildOrderedTreeMoveRenames(sourceParentPath, ordered);
    const moved = ordered.find((entry) => entry.path === nodePath);
    return {
      ok: true,
      value: {
        renames: dedupeRenames(renames),
        nextNodePath: moved?.nextPath || nodePath,
        targetIndex,
      },
    };
  }

  const targetEntries = await readDirectoryEntries(targetParentPath);
  if (targetIndex > targetEntries.length) {
    return makeTreeMoveError('E_TREE_MOVE_TARGET_INDEX_INVALID', 'TREE_MOVE_TARGET_INDEX_INVALID');
  }
  const sourceOrdered = sourceEntries.filter((entry) => entry.path !== nodePath);
  const movingTargetEntry = {
    ...movingEntry,
    path: nodePath,
  };
  const targetOrdered = targetEntries.slice();
  targetOrdered.splice(targetIndex, 0, movingTargetEntry);
  const sourceRenames = buildOrderedTreeMoveRenames(sourceParentPath, sourceOrdered);
  const targetRenames = buildOrderedTreeMoveRenames(targetParentPath, targetOrdered);
  const moved = targetOrdered.find((entry) => entry.path === nodePath);
  return {
    ok: true,
    value: {
      renames: dedupeRenames([...sourceRenames, ...targetRenames]),
      nextNodePath: moved?.nextPath || nodePath,
      targetIndex,
    },
  };
}

// Автоматическое открытие последнего файла
async function openLastFile() {
  if (!mainWindow) return 'noFile';
  
  const lastFilePath = await loadLastFile();
  if (!lastFilePath) return 'noFile';
  if (!isAllowedFilePath(lastFilePath)) return 'noFile';
  
  const exists = await fileExists(lastFilePath);
  if (!exists) return 'noFile';
  
  const fileResult = await fileManager.readFile(lastFilePath);
    if (fileResult.success) {
      currentFilePath = lastFilePath;
      await saveLastFile();
      const context = getDocumentContextFromPath(lastFilePath);
      const documentIdentity = await getProjectDocumentIdentityPayload(lastFilePath);
      sendEditorText(await attachProjectIdToEditorPayload({
        content: fileResult.content,
        title: context.title,
        ...documentIdentity,
        kind: context.kind,
        metaEnabled: context.metaEnabled
      }, lastFilePath));
      setDirtyState(false);
      const contentHash = computeHash(fileResult.content);
      lastAutosaveHash = contentHash;
      backupHashes.set(lastFilePath, contentHash);
      updateStatus('Готово');
      return 'loaded';
    }

  updateStatus('Ошибка');
  return 'error';
}

// Применение сохранённого размера шрифта
async function loadSavedFontSize() {
  if (!mainWindow) return;
  
  try {
    const settings = await loadSettings();
    if (Number.isFinite(settings.fontSize)) {
      currentFontSize = clampFontSize(settings.fontSize);
    }
  } catch (error) {
    // Тихая обработка ошибок
  }

  sendEditorFontSize(currentFontSize);
}

async function restoreAutosaveIfExists() {
  if (!mainWindow) return false;
  await ensureAutosaveDirectory();

  const autosavePath = getAutosavePath();
  try {
    const content = await fs.readFile(autosavePath, 'utf-8');
    if (!content) {
      return false;
    }

    sendEditorText(await attachProjectIdToEditorPayload({
      content,
      title: 'Автосохранение',
      documentId: 'autosave-document',
      kind: 'autosave',
      metaEnabled: false,
    }));

    setDirtyState(true); // восстановленный черновик считается несохранённым
    const autosaveHash = computeHash(content);
    lastAutosaveHash = autosaveHash;
    backupHashes.set(autosavePath, autosaveHash);
    updateStatus('Восстановлено из автосохранения');
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('ui:recovery-restored', {
        message: 'Recovered autosave on reopen path',
        source: 'autosave',
      });
    }
    return true;
  } catch (error) {
    logDevError('restoreAutosaveIfExists', error);
    return false;
  }
}

// Сохранение и восстановление размеров окна
const DEFAULT_WINDOW_SIZE = {
  width: 3456,
  height: 2234
};

const windowState = {
  width: DEFAULT_WINDOW_SIZE.width,
  height: DEFAULT_WINDOW_SIZE.height,
  x: undefined,
  y: undefined
};

async function loadWindowStateFromSettings() {
  try {
    const settings = await loadSettings();
    if (Number.isFinite(settings.windowWidth) && settings.windowWidth > 0) {
      windowState.width = settings.windowWidth;
    }
    if (Number.isFinite(settings.windowHeight) && settings.windowHeight > 0) {
      windowState.height = settings.windowHeight;
    }
    if (Number.isFinite(settings.windowX)) {
      windowState.x = settings.windowX;
    }
    if (Number.isFinite(settings.windowY)) {
      windowState.y = settings.windowY;
    }
  } catch {
    // Игнорируем ошибки
  }
}

async function persistWindowState(bounds) {
  try {
    const settings = await loadSettings();
    settings.windowWidth = bounds.width;
    settings.windowHeight = bounds.height;
    settings.windowX = bounds.x;
    settings.windowY = bounds.y;
    await saveSettings(settings);
  } catch {
    // Тихо игнорируем
  }
}

function getAutosaveDir() {
  const documentsPath = fileManager.getDocumentsPath();
  return path.join(documentsPath, '.autosave');
}

function getAutosavePath() {
  return path.join(getAutosaveDir(), 'autosave.txt');
}

async function ensureAutosaveDirectory() {
  const dir = getAutosaveDir();
  try {
    await fs.mkdir(dir, { recursive: true });
  } catch {
    // Папка может уже существовать
  }
  return dir;
}

async function deleteAutosaveFile() {
  const autosavePath = getAutosavePath();
  try {
    await fs.unlink(autosavePath);
  } catch {
    // Игнорируем, если файла нет
  }
}

async function writeAutosaveFile(content, revision) {
  const autosavePath = getAutosavePath();
  await ensureAutosaveDirectory();
  return durableSaveWithCoordinator(autosavePath, content, revision);
}

// R2.4 P2: the durable save transaction wrapper used by the autosave
// lifecycle: exact-revision capture, unique temp, fsync, atomic publish,
// parent fsync, exact readback and phase-bound ACK.
async function durableSaveWithCoordinator(filePath, content, revision) {
  try {
    return await durableSaveTransaction({ filePath, content, revision });
  } catch (error) {
    return {
      success: false,
      error: error && typeof error.message === 'string' ? error.message : 'unknown',
      phase: error && typeof error.phase === 'string' ? error.phase : null,
      code: error && typeof error.code === 'string' ? error.code : null,
    };
  }
}

function updateStatus(status) {
  if (mainWindow) {
    mainWindow.webContents.send('status-update', status);
  }
}

function setDirtyState(state, ack = null) {
  isDirty = state;
  if (mainWindow) {
    // R2.4 P1: the push carries the typed acknowledgement so the renderer can
    // fence dirty clears by exact generation instead of trusting a boolean.
    mainWindow.webContents.send('set-dirty', { state, ack });
  }
}

function sendRuntimeCommand(command, payload = {}) {
  if (!mainWindow || mainWindow.isDestroyed()) {
    return false;
  }
  mainWindow.webContents.send('ui:runtime-command', {
    command,
    payload: payload && typeof payload === 'object' && !Array.isArray(payload) ? payload : {},
  });
  return true;
}

function sendCanonicalRuntimeCommand(commandId, payload = {}, legacyCommand = '') {
  if (!mainWindow || mainWindow.isDestroyed()) {
    return false;
  }
  const safePayload = payload && typeof payload === 'object' && !Array.isArray(payload) ? payload : {};
  const envelope = {
    commandId,
    payload: safePayload,
  };
  if (typeof legacyCommand === 'string' && legacyCommand.length > 0) {
    envelope.command = legacyCommand;
  }
  mainWindow.webContents.send('ui:runtime-command', envelope);
  return true;
}

function resolveCollabScopeLocalState() {
  const rawValue = typeof process.env.COLLAB_SCOPE_LOCAL === 'string'
    ? process.env.COLLAB_SCOPE_LOCAL.trim().toLowerCase()
    : '';
  if (rawValue === '1' || rawValue === 'true' || rawValue === 'yes' || rawValue === 'on') {
    return true;
  }
  const aliasValue = typeof process.env.COLLAB_SCOPE_FLAG_ACTIVE === 'string'
    ? process.env.COLLAB_SCOPE_FLAG_ACTIVE.trim().toLowerCase()
    : '';
  return aliasValue === '1' || aliasValue === 'true' || aliasValue === 'yes' || aliasValue === 'on';
}

guardedOn('editor:text-response', (_, payload) => {
  const requestId = payload && payload.requestId;
  if (!requestId) {
    return;
  }

  const pending = pendingTextRequests.get(requestId);
  if (!pending) {
    return;
  }

  clearTimeout(pending.timeoutId);
  pendingTextRequests.delete(requestId);
  pending.resolve(typeof payload?.text === 'string' ? payload.text : '');
});

guardedOn('editor:snapshot-response', (_, payload) => {
  const requestId = typeof payload?.requestId === 'string' ? payload.requestId : '';
  if (!requestId) {
    return;
  }

  const pending = pendingSnapshotRequests.get(requestId);
  if (!pending) {
    return;
  }

  clearTimeout(pending.timeoutId);
  pendingSnapshotRequests.delete(requestId);
  pending.resolve(normalizeEditorSnapshotPayload(payload ? payload.snapshot : null));
});

