guardedProtocolHandle('ui:command-bridge', async (_, request) => {
  // R2.4 S1: the versioned envelope is validated before any interpretation.
  const envelopeVerdict = validateIpcEnvelope(request, 'ui:command-bridge');
  if (!envelopeVerdict.ok) {
    return { ok: false, reason: envelopeVerdict.code };
  }
  const safeRequest = request && typeof request === 'object' && !Array.isArray(request)
    ? request
    : {};
  const route = typeof safeRequest.route === 'string' ? safeRequest.route : '';
  const commandId = typeof safeRequest.commandId === 'string' ? safeRequest.commandId : '';
  const payload = safeRequest.payload && typeof safeRequest.payload === 'object' && !Array.isArray(safeRequest.payload)
    ? safeRequest.payload
    : {};

  if (route !== COMMAND_BUS_ROUTE) {
    return { ok: false, reason: 'COMMAND_ROUTE_UNSUPPORTED' };
  }
  if (!UI_COMMAND_BRIDGE_ALLOWED_COMMAND_IDS.has(commandId)) {
    return { ok: false, reason: 'COMMAND_ID_NOT_ALLOWED' };
  }

  try {
    const result = PRODUCT_COMMAND_ID_SET.has(commandId)
      ? await dispatchProductCommandBridge(commandId, payload)
      : await dispatchMenuCommand(commandId, payload, { route: COMMAND_BUS_ROUTE });
    if (result && result.ok === true) return makeCommandBridgeSuccess(result);
    const reason = findCommandBridgeFailureReason(result) || 'COMMAND_EXECUTION_FAILED';
    return makeCommandBridgeFailure(reason, result);
  } catch (error) {
    return makeCommandBridgeException(error);
  }
});

