guardedProtocolHandle('ui:workspace-query-bridge', async (_, request) => {
  // R2.4 S1: the versioned envelope is validated before any interpretation.
  const envelopeVerdict = validateIpcEnvelope(request, 'ui:workspace-query-bridge');
  if (!envelopeVerdict.ok) {
    return { ok: false, error: envelopeVerdict.code };
  }
  const safeRequest = request && typeof request === 'object' && !Array.isArray(request)
    ? request
    : {};
  const queryId = typeof safeRequest.queryId === 'string' ? safeRequest.queryId : '';
  const payload = safeRequest.payload && typeof safeRequest.payload === 'object' && !Array.isArray(safeRequest.payload)
    ? safeRequest.payload
    : {};

  if (!WORKSPACE_QUERY_BRIDGE_ALLOWED_QUERY_IDS.has(queryId)) {
    return { ok: false, error: 'QUERY_ID_NOT_ALLOWED' };
  }

  const handler = WORKSPACE_QUERY_BRIDGE_HANDLERS.get(queryId);
  if (typeof handler !== 'function') {
    return { ok: false, error: 'QUERY_HANDLER_UNAVAILABLE' };
  }
  return ATLAS_ANALYTICS_QUERY_IDS.has(queryId)
    ? runScheduledAtlasAnalyticsQuery(queryId, payload, handler)
    : handler(payload);
});

guardedProtocolHandle('ui:save-lifecycle-signal-bridge', async (_, request) => {
  // R2.4 S1: the versioned envelope is validated before any interpretation.
  const envelopeVerdict = validateIpcEnvelope(request, 'ui:save-lifecycle-signal-bridge');
  if (!envelopeVerdict.ok) {
    return { ok: false, error: envelopeVerdict.code };
  }
  const safeRequest = request && typeof request === 'object' && !Array.isArray(request)
    ? request
    : {};
  const signalId = typeof safeRequest.signalId === 'string' ? safeRequest.signalId : '';
  const payload = safeRequest.payload && typeof safeRequest.payload === 'object' && !Array.isArray(safeRequest.payload)
    ? safeRequest.payload
    : {};

  if (!SAVE_LIFECYCLE_SIGNAL_BRIDGE_ALLOWED_SIGNAL_IDS.has(signalId)) {
    return { ok: false, error: 'SIGNAL_ID_NOT_ALLOWED' };
  }

  if (signalId === 'signal.localDirty.set') {
    if (typeof payload.state !== 'boolean') {
      return { ok: false, error: 'SIGNAL_PAYLOAD_INVALID' };
    }
    if (payload.state === true) {
      // R2.4 P0: a dirty signal carries the renderer's local edit generation;
      // merge it monotonically so autosave acknowledgements can be fenced.
      lastSignaledEditGeneration = mergeSignaledGeneration(lastSignaledEditGeneration, payload.generation);
    }
    isDirty = payload.state;
    return { ok: true };
  }
  if (signalId === 'signal.autoSave.request') {
    return autoSave();
  }
  return { ok: false, error: 'SIGNAL_ID_NOT_ALLOWED' };
});

