async function handleUiDeleteNodeCommand(payload) {
  const safePayload = normalizeLegacyUiBridgePayload(payload);
  let resolvedNode;
  try {
    resolvedNode = await resolveProjectTreeNodeIdentity(safePayload.nodeId, safePayload.projectId);
  } catch (error) {
    return {
      ok: false,
      error: error && typeof error.code === 'string' ? error.code : 'E_TREE_NODE_RESOLUTION_FAILED',
    };
  }
  const nodePathGuard = sanitizePayloadWithinProjectRoot({ path: resolvedNode.nodePath }, ['path']);
  if (!nodePathGuard.ok || !nodePathGuard.payload) return nodePathGuard.error;
  const nodePath = nodePathGuard.payload.path;
  let deletedSceneIds = [];
  try {
    deletedSceneIds = await collectFreeEditDeletedSceneIds(nodePath);
  } catch (error) {
    logDevError('delete node collect pro data invalidation', error);
  }

  const trashPath = getProjectSectionPath('trash');
  await fs.mkdir(trashPath, { recursive: true });
  const baseName = path.basename(nodePath);
  let targetPath = joinPathSegmentsWithinRoot(trashPath, [baseName], { resolveSymlinks: false });
  if (await fileExists(targetPath)) {
    const stamped = `${Date.now()}_${baseName}`;
    targetPath = joinPathSegmentsWithinRoot(trashPath, [stamped], { resolveSymlinks: false });
  }

  try {
    await fs.rename(nodePath, targetPath);
  } catch (error) {
    logDevError('delete node', error);
    return { ok: false, error: error.message || 'Failed to move to trash' };
  }

  if (deletedSceneIds.length > 0) {
    try {
      await persistFreeEditProDataInvalidationForSceneIds(deletedSceneIds, {
        changedSceneIds: [],
        deletedSceneIds,
        staleReason: 'FREE_SCENE_DELETED',
        operationLabel: 'delete pro data invalidation',
      });
    } catch (error) {
      logDevError('delete node pro data invalidation', error);
    }
  }

  if (currentFilePath && isPathInside(nodePath, currentFilePath)) {
    currentFilePath = null;
    await saveLastFile();
    sendEditorText(await attachProjectIdToEditorPayload({ content: '', title: '', documentId: '', kind: 'empty', metaEnabled: false }));
    setDirtyState(false);
    updateStatus('Готово');
  }

  return { ok: true, nodeId: resolvedNode.nodeId, removed: true };
}

