guardedHandle('ui:open-section', async (_, payload) => {
  if (!mainWindow) {
    return { ok: false, error: 'No active window' };
  }

  const sectionName = payload && payload.sectionName;
  if (typeof sectionName !== 'string' || !sectionName.trim()) {
    return { ok: false, error: 'Invalid section name' };
  }

  const canProceed = await confirmDiscardChanges();
  if (!canProceed) {
    return { ok: false, cancelled: true };
  }

  const filePath = getSectionDocumentPath(sectionName);
  try {
    await fs.mkdir(path.dirname(filePath), { recursive: true });
  } catch (error) {
    logDevError('open section mkdir', error);
    return { ok: false, error: error.message || 'Failed to create folder' };
  }

  let content = '';
  try {
    content = await fs.readFile(filePath, 'utf8');
  } catch (error) {
    if (error && error.code !== 'ENOENT') {
      logDevError('open section read', error);
      return { ok: false, error: error.message || 'Failed to read file' };
    }

    const created = await queueDiskOperation(
      () => fileManager.writeFileAtomic(filePath, ''),
      'create section file'
    );
    if (!created.success) {
      return { ok: false, error: created.error || 'Failed to create file' };
    }
  }

  currentFilePath = filePath;
  await saveLastFile();
  const documentIdentity = await getProjectDocumentIdentityPayload(filePath);
  sendEditorText(await attachProjectIdToEditorPayload({
    content,
    title: sectionName,
    ...documentIdentity,
    kind: 'legacy-section',
    metaEnabled: false,
  }, filePath));
  setDirtyState(false);
  const contentHash = computeHash(content);
  lastAutosaveHash = contentHash;
  backupHashes.set(filePath, contentHash);
  updateStatus('Готово');
  return { ok: true, documentId: documentIdentity.documentId };
});

function createWindow() {
  // Восстановление размеров и позиции окна
  const { screen } = require('electron');
  const primaryDisplay = screen.getPrimaryDisplay();
  const { width: screenWidth, height: screenHeight } = primaryDisplay.workAreaSize;
  const desiredWidth = Number.isFinite(windowState.width) ? windowState.width : DEFAULT_WINDOW_SIZE.width;
  const desiredHeight = Number.isFinite(windowState.height) ? windowState.height : DEFAULT_WINDOW_SIZE.height;
  const width = Math.min(desiredWidth, screenWidth);
  const height = Math.min(desiredHeight, screenHeight);

  mainWindow = new BrowserWindow({
    width,
    height,
    x: windowState.x,
    y: windowState.y,
    backgroundColor: '#dbd4ca',
    titleBarStyle: process.platform === 'darwin' ? 'hiddenInset' : 'default',
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
      sandbox: true
    }
  });

  mainWindow.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));
  mainWindow.webContents.on('will-navigate', blockExternalNavigation);
  mainWindow.webContents.on('will-redirect', blockExternalNavigation);

  logPerfStage('create-window');

  const useLegacyEditor = process.env.USE_LEGACY_EDITOR === '1';
  const useTiptap = !useLegacyEditor;
  editorStartupReadyPromise = mainWindow.loadFile(path.join(__dirname, 'renderer', 'index.html'), {
    query: { USE_TIPTAP: (useTiptap ? '1' : '0') },
  }).then(async () => {
    mainWindow.webContents.setZoomFactor(1);
    logPerfStage('did-finish-load');
    await loadSavedFontSize();
    const restored = await restoreAutosaveIfExists();
    if (!restored) {
      const openResult = await openLastFile();
      if (openResult !== 'loaded' && openResult !== 'error') {
        updateStatus('Готово');
      }
    }
  }).catch((error) => {
    logDevError('editor startup bootstrap', error);
  });

  mainWindow.webContents.on('before-input-event', (event, input) => {
    if (input.key === 'Escape' && mainWindow && mainWindow.isFullScreen()) {
      event.preventDefault();
      mainWindow.setFullScreen(false);
      return;
    }

    handlePrimaryPasteShortcut(event, input, mainWindow);
  });
  mainWindow.on('blur', () => {
    isEditorPasteTargetFocused = false;
  });

  // Сохранение размеров и позиции окна + запрос при несохранённых изменениях
  mainWindow.on('close', (event) => {
    if (isWindowClosing || isQuitting) {
      return;
    }

    event.preventDefault();

    (async () => {
      const canClose = await confirmDiscardChanges();
      if (!canClose) {
        return;
      }

      if (mainWindow) {
        const bounds = mainWindow.getBounds();
        await persistWindowState(bounds);
      }

      isWindowClosing = true;
      mainWindow.close();
    })().catch(() => {});
  });

  mainWindow.on('closed', () => {
    clearPendingTextRequests('Window closed');
    mainWindow = null;
    isWindowClosing = false;
  });

  mainWindow.on('resize', () => {
    if (mainWindow) {
      persistWindowState(mainWindow.getBounds()).catch(() => {});
    }
  });

  mainWindow.on('move', () => {
    if (mainWindow) {
      persistWindowState(mainWindow.getBounds()).catch(() => {});
    }
  });

  // Открыть DevTools только в режиме разработки (опционально)
  // mainWindow.webContents.openDevTools();
}

async function handleNew() {
  if (!mainWindow) return;
  currentFilePath = null;
  await saveLastFile();
  sendEditorText(await attachProjectIdToEditorPayload({
    content: '',
    title: '',
    documentId: '',
    kind: 'empty',
    metaEnabled: false,
  }));
  setDirtyState(false);
  lastAutosaveHash = null;
  updateStatus('Готово');
}

async function handleOpen() {
  const result = await dialog.showOpenDialog(mainWindow, {
    title: 'Открыть файл',
    defaultPath: fileManager.getDocumentsPath(),
    filters: [
      { name: 'Текстовые файлы', extensions: ['txt'] },
      { name: 'Все файлы', extensions: ['*'] }
    ],
    properties: ['openFile']
  });

  if (!result.canceled && result.filePaths.length > 0) {
    const filePath = result.filePaths[0];
    if (!isAllowedFilePath(filePath)) {
      updateStatus('Ошибка');
      return makeAllowlistReject('FILE_OPEN_PATH_NOT_ALLOWED', filePath);
    }
    const fileResult = await fileManager.readFile(filePath);
    
    if (fileResult.success) {
      currentFilePath = filePath;
      await saveLastFile();
      const context = getDocumentContextFromPath(filePath);
      const documentIdentity = await getProjectDocumentIdentityPayload(filePath);
      sendEditorText(await attachProjectIdToEditorPayload({
        content: fileResult.content,
        title: context.title,
        ...documentIdentity,
        kind: context.kind,
        metaEnabled: context.metaEnabled
      }, filePath));
      setDirtyState(false);
      const contentHash = computeHash(fileResult.content);
      lastAutosaveHash = contentHash;
      backupHashes.set(filePath, contentHash);
      updateStatus('Готово');
    } else {
      updateStatus('Ошибка');
    }
  }
}

async function autoSave() {
  if (!mainWindow || autoSaveInProgress) {
    return { ok: true, ack: null };
  }

  if (!isDirty) {
    return { ok: true, ack: null };
  }

  autoSaveInProgress = true;
  try {
    const snapshot = await requestEditorSnapshot();
    const content = snapshot.content;
    const currentHash = computeHash(content);
    // R2.4 R1: the per-project shadow cell evaluates this same admission as
    // advisory telemetry only. It holds no authority, and its verdict can
    // never alter the lifecycle.
    let shadowVerdict;
    try {
      shadowVerdict = shadowCell.shadowEvaluateWriteAdmission({
        capturedGeneration: snapshot.generation,
        latestEditGeneration: lastSignaledEditGeneration,
      });
    } catch (shadowError) {
      shadowVerdict = { advice: 'E_SHADOW_EVALUATION_UNAVAILABLE' };
    }
    logShadowAdvice('autosave', shadowVerdict);
    // R2.4 P1: every autosave acknowledgement is explicit — SAVED, PROTECTED
    // or AT_RISK — classified from the P0 generation fence and the write.
    const classify = (writeSucceeded, ackOutcome) => classifySaveAck({
      writeSucceeded,
      ackOutcome,
      savedGeneration: snapshot.generation,
      latestEditGeneration: lastSignaledEditGeneration,
    });

    if (currentFilePath) {
      if (currentHash !== lastAutosaveHash) {
        // R2.4 P3: scene and manifest commit as one transaction — the marker
        // is the only commit point and a partial publication can never be
        // ACKed. Manifest state is captured first so a scene-publish failure
        // can roll the manifest back.
        let preCommitManifest = null;
        let preCommitManifestText = null;
        try {
          const bindingBefore = await resolveProjectBindingForFile(currentFilePath);
          if (bindingBefore && isPlainObjectValue(bindingBefore.manifest)) {
            preCommitManifest = bindingBefore.manifest;
            preCommitManifestText = typeof bindingBefore.manifestRaw === 'string' ? bindingBefore.manifestRaw : null;
          }
        } catch (error) {
          logDevError('autoSave:preCommitManifestCapture', error);
        }
        let pairNextManifestText = null;
        const saveResult = await queueDiskOperation(
          async () => {
            try {
              return await commitProjectTextAndManifest({
                scenePath: currentFilePath,
                sceneContent: content,
                revision: snapshot.generation,
                persistManifest: async () => {
                  const outcome = await persistBookProfileForFile(currentFilePath, snapshot.bookProfile, 'autosave project manifest');
                  if (outcome && outcome.persisted === true && outcome.manifest) {
                    pairNextManifestText = JSON.stringify(outcome.manifest, null, 2);
                  }
                  return outcome;
                },
                rollbackManifest: preCommitManifest
                  ? async () => {
                      if (pairNextManifestText) {
                        await rollbackBookProfileForFile(currentFilePath, preCommitManifest, pairNextManifestText);
                      }
                    }
                  : undefined,
              });
            } catch (error) {
              return {
                success: false,
                error: error && typeof error.message === 'string' ? error.message : 'unknown',
                code: error && typeof error.code === 'string' ? error.code : null,
                rolledBack: error && error.rolledBack === true,
              };
            }
          },
          'autosave file'
        );
        if (!saveResult.success) {
          updateStatus('Ошибка сохранения');
          return { ok: false, ack: classify(false, null) };
        }
        try {
          await persistFreeEditProDataInvalidationForFile(currentFilePath, {
            operationLabel: 'autosave pro data invalidation',
          });
        } catch (error) {
          logDevError('autoSave:proDataInvalidation', error);
        }
      } else {
        await persistBookProfileForFile(currentFilePath, snapshot.bookProfile, 'autosave project manifest');
      }

      lastAutosaveHash = currentHash;
      const fileDecision = decideAutosaveAck({
        capturedGeneration: snapshot.generation,
        latestEditGeneration: lastSignaledEditGeneration,
      });
      const fileAck = classify(true, fileDecision.outcome);
      if (fileAck.kind === SAVE_ACK_KINDS.SAVED) {
        setDirtyState(false, fileAck);
        updateStatus('Автосохранено');
      }
      await saveLastFile({ selectionRange: snapshot.selectionRange });
      return { ok: true, ack: fileAck };
    }

    if (currentHash === lastAutosaveHash) {
      const idleDecision = decideAutosaveAck({
        capturedGeneration: snapshot.generation,
        latestEditGeneration: lastSignaledEditGeneration,
      });
      const idleAck = classify(true, idleDecision.outcome);
      if (idleAck.kind === SAVE_ACK_KINDS.SAVED) {
        setDirtyState(false, idleAck);
      }
      return { ok: true, ack: idleAck };
    }

    const autosaveResult = await queueDiskOperation(
      () => writeAutosaveFile(content, snapshot.generation),
      'autosave temporary'
    );
    if (!autosaveResult.success) {
      updateStatus('Ошибка сохранения');
      return { ok: false, ack: classify(false, null) };
    }

    lastAutosaveHash = currentHash;
    const tempDecision = decideAutosaveAck({
      capturedGeneration: snapshot.generation,
      latestEditGeneration: lastSignaledEditGeneration,
    });
    const tempAck = classify(true, tempDecision.outcome);
    if (tempAck.kind === SAVE_ACK_KINDS.SAVED) {
      setDirtyState(false, tempAck);
      updateStatus('Автосохранено');
    }
    return { ok: true, ack: tempAck };
  } catch (error) {
    updateStatus('Ошибка сохранения');
    logDevError('autoSave', error);
    return { ok: false, ack: { kind: SAVE_ACK_KINDS.AT_RISK, reason: 'EXCEPTION', savedGeneration: null, latestEditGeneration: lastSignaledEditGeneration } };
  } finally {
    autoSaveInProgress = false;
  }
}

// Создание бэкапа раз в минуту
async function createBackup() {
  if (!mainWindow) {
    return;
  }

  try {
    if (currentFilePath) {
      const snapshot = await requestEditorSnapshot();
      const content = snapshot.content;
      const hash = computeHash(content);
      if (backupHashes.get(currentFilePath) === hash) {
        return;
      }

      const result = await queueDiskOperation(
        () => backupManager.createBackup(currentFilePath, content, { basePath: getBackupBasePathForFile(currentFilePath) }),
        'backup current file'
      );
      if (!result.success) {
        updateStatus('Ошибка');
        return;
      }

      backupHashes.set(currentFilePath, hash);
      return;
    }

    const autosavePath = getAutosavePath();
    const autosaveExists = await fileExists(autosavePath);
    if (!autosaveExists) {
      return;
    }

    const autosaveResult = await fileManager.readFile(autosavePath);
    if (!autosaveResult.success) {
      updateStatus('Ошибка');
      return;
    }

    const autosaveHash = computeHash(autosaveResult.content);
    if (backupHashes.get(autosavePath) === autosaveHash) {
      return;
    }

    const backupResult = await queueDiskOperation(
      () => backupManager.createBackup(autosavePath, autosaveResult.content),
      'backup autosave'
    );
    if (!backupResult.success) {
      updateStatus('Ошибка');
      return;
    }

    backupHashes.set(autosavePath, autosaveHash);
  } catch (error) {
    updateStatus('Ошибка');
    logDevError('createBackup', error);
  }
}

async function handleSave() {
  if (!mainWindow) {
    return false;
  }

  let snapshot;
  try {
    snapshot = await requestEditorSnapshot();
  } catch (error) {
    updateStatus('Ошибка');
    logDevError('handleSave', error);
    return false;
  }
  const content = snapshot.content;
  const wasUntitled = currentFilePath === null;

  if (currentFilePath) {
    if (!isAllowedFilePath(currentFilePath)) {
      updateStatus('Ошибка');
      return false;
    }
    const contentHash = computeHash(content);
    const textChanged = contentHash !== lastAutosaveHash;
    const saveResult = await queueDiskOperation(
      () => fileManager.writeFileAtomic(currentFilePath, content),
      'save existing file'
    );
    if (saveResult.success) {
      if (textChanged) {
        try {
          await persistFreeEditProDataInvalidationForFile(currentFilePath, {
            operationLabel: 'save pro data invalidation',
          });
        } catch (error) {
          logDevError('handleSave:proDataInvalidation', error);
        }
      }
      await persistBookProfileForFile(currentFilePath, snapshot.bookProfile, 'save project manifest');
      lastAutosaveHash = contentHash;
      setDirtyState(false);
      updateStatus('Сохранено');
      await saveLastFile({ selectionRange: snapshot.selectionRange });
      return true;
    }
    updateStatus('Ошибка');
    return false;
  }

  const result = await dialog.showSaveDialog(mainWindow, {
    title: 'Сохранить файл',
    defaultPath: fileManager.getDocumentsPath(),
    filters: [
      { name: 'Текстовые файлы', extensions: ['txt'] },
      { name: 'Все файлы', extensions: ['*'] }
    ]
  });

  if (!result.canceled && result.filePath) {
    let filePath = result.filePath;
    if (!filePath.endsWith('.txt')) {
      filePath += '.txt';
    }
    if (!isAllowedFilePath(filePath)) {
      updateStatus('Ошибка');
      return false;
    }

    const saveResult = await queueDiskOperation(
      () => fileManager.writeFileAtomic(filePath, content),
      'save new file'
    );
    if (saveResult.success) {
      await persistBookProfileForFile(filePath, snapshot.bookProfile, 'save project manifest');
      lastAutosaveHash = computeHash(content);
      currentFilePath = filePath;
      await saveLastFile({ selectionRange: snapshot.selectionRange });
      setDirtyState(false);
      updateStatus('Сохранено');
      if (wasUntitled) {
        await deleteAutosaveFile();
        backupHashes.delete(getAutosavePath());
      }
      return true;
    }
    updateStatus('Ошибка');
  }

  return false;
}

async function handleSaveAs() {
  if (!mainWindow) {
    return false;
  }

  let snapshot;
  try {
    snapshot = await requestEditorSnapshot();
  } catch (error) {
    updateStatus('Ошибка');
    logDevError('handleSaveAs', error);
    return false;
  }
  const content = snapshot.content;

  const wasUntitled = currentFilePath === null;
  const result = await dialog.showSaveDialog(mainWindow, {
    title: 'Сохранить файл',
    defaultPath: currentFilePath || fileManager.getDocumentsPath(),
    filters: [
      { name: 'Текстовые файлы', extensions: ['txt'] },
      { name: 'Все файлы', extensions: ['*'] }
    ]
  });

  if (!result.canceled && result.filePath) {
    let filePath = result.filePath;
    if (!filePath.endsWith('.txt')) {
      filePath += '.txt';
    }
    if (!isAllowedFilePath(filePath)) {
      updateStatus('Ошибка');
      return false;
    }

    const saveResult = await queueDiskOperation(
      () => fileManager.writeFileAtomic(filePath, content),
      'save as file'
    );
    if (saveResult.success) {
      await persistBookProfileForFile(filePath, snapshot.bookProfile, 'save project manifest');
      lastAutosaveHash = computeHash(content);
      currentFilePath = filePath;
      await saveLastFile({ selectionRange: snapshot.selectionRange });
      setDirtyState(false);
      updateStatus('Сохранено');
      if (wasUntitled) {
        await deleteAutosaveFile();
        backupHashes.delete(getAutosavePath());
      }
      return true;
    }
    updateStatus('Ошибка');
  }

  return false;
}

async function confirmDiscardChanges() {
  if (!isDirty || !mainWindow) {
    return true;
  }

  // R2.4 P1: discard proceeds only on an explicit SAVED acknowledgement.
  // PROTECTED (newer work unsaved) and AT_RISK (write failed or unbound)
  // block the discard instead of trusting a false-clean boolean.
  const result = await autoSave();
  if (!result || result.ok !== true) {
    return false;
  }
  if (result.ack === null) {
    return true;
  }
  return result.ack.kind === SAVE_ACK_KINDS.SAVED;
}

async function ensureCleanAction(actionFn) {
  const canProceed = await confirmDiscardChanges();
  if (!canProceed) {
    return;
  }

  await actionFn();
}

function handleFontChange(fontFamily) {
  if (mainWindow) {
    mainWindow.webContents.send('font-changed', fontFamily);
  }
}

function handleThemeChange(theme) {
  if (mainWindow) {
    mainWindow.webContents.send('theme-changed', theme);
  }
}

// Обработка изменения размера шрифта
async function handleFontSizeChange(action) {
  if (!mainWindow) return;
  
  try {
    let newSize = currentFontSize;
    const minSize = 12;
    const maxSize = 28;
    
    if (action === 'increase') {
      newSize = Math.min(currentFontSize + 1, maxSize);
    } else if (action === 'decrease') {
      newSize = Math.max(currentFontSize - 1, minSize);
    } else if (action === 'reset') {
      newSize = 16;
    }
    
    if (newSize !== currentFontSize) {
      currentFontSize = clampFontSize(newSize);
      sendEditorFontSize(currentFontSize);

      const settings = await loadSettings();
      settings.fontSize = currentFontSize;
      await saveSettings(settings);
    }
  } catch (error) {
    logDevError('handleFontSizeChange', error);
  }
}

