function shouldFailHardOnMenuConfigError() {
  return process.env.MENU_CONFIG_CONTRACT_MODE === '1' || process.argv.includes('--menu-config-contract');
}

function resolveRuntimeMenuArtifactMode() {
  const promotionArg = process.argv.find((arg) => String(arg || '').startsWith('--promotionMode='));
  if (promotionArg) {
    const value = String(promotionArg.split('=').slice(1).join('=') || '').trim().toLowerCase();
    if (value === '1' || value === 'true' || value === 'yes' || value === 'on') {
      return 'promotion';
    }
  }
  return resolveMenuArtifactModeFromInput('');
}

function verifyMenuArtifactLockAtRuntime() {
  const mode = resolveRuntimeMenuArtifactMode();
  const state = evaluateMenuArtifactLockState({
    mode,
    expectedSnapshotId: 'menu-default-desktop-minimal',
  });

  if (state.result === MENU_ARTIFACT_RESULT_FAIL) {
    const error = new Error(`Menu artifact verification failed (${state.failSignalCode || 'E_MENU_ARTIFACT_TAMPER_OR_DRIFT'})`);
    error.failSignalCode = state.failSignalCode || 'E_MENU_ARTIFACT_TAMPER_OR_DRIFT';
    error.details = state;
    throw error;
  }

  if (state.mismatch === true) {
    const issues = Array.isArray(state.issues) ? state.issues.map((row) => row.code).join(',') : '';
    console.warn(`[menu-artifact] advisory mismatch in ${mode}: ${issues}`);
  }
}

function normalizeRuntimeString(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function isRuntimeRecord(value) {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function createRuntimeMenuPolicyError(message, details = {}, mode = 'release') {
  const error = new Error(message);
  error.code = 'MENU_RUNTIME_POLICY_VIOLATION';
  error.failSignalCode = FAIL_SIGNAL_MENU_RUNTIME_ARTIFACT_DIVERGENCE;
  error.details = details;
  error.menuRuntimeBlocking = mode === 'promotion';
  return error;
}

function emitRuntimeMenuAdvisory(message, details = {}) {
  let detailsText = '';
  try {
    detailsText = Object.keys(details).length > 0 ? ` ${JSON.stringify(details)}` : '';
  } catch {
    detailsText = '';
  }
  console.warn(
    `[menu-runtime] advisory ${FAIL_SIGNAL_MENU_RUNTIME_ARTIFACT_DIVERGENCE}: ${message}${detailsText}`,
  );
}

function parseRuntimeJsonInput(pathEnvKey, jsonEnvKey, label) {
  const inlineJson = normalizeRuntimeString(process.env[jsonEnvKey]);
  if (inlineJson) {
    try {
      return JSON.parse(inlineJson);
    } catch (error) {
      throw new Error(`Invalid ${label} JSON in ${jsonEnvKey}: ${error.message}`);
    }
  }

  const payloadPathRaw = normalizeRuntimeString(process.env[pathEnvKey]);
  if (!payloadPathRaw) return null;
  const payloadPath = resolveValidatedPath(payloadPathRaw, { mode: 'any' });
  let rawText = '';
  try {
    rawText = fsSync.readFileSync(payloadPath, 'utf8');
  } catch (error) {
    throw new Error(`Cannot read ${label} payload from ${payloadPath}: ${error.message}`);
  }

  try {
    return JSON.parse(rawText);
  } catch (error) {
    throw new Error(`Invalid ${label} JSON in ${payloadPath}: ${error.message}`);
  }
}

function resolveRuntimeMenuLocaleCatalog(artifactDoc) {
  if (isRuntimeRecord(artifactDoc) && isRuntimeRecord(artifactDoc.localeCatalog)) {
    return artifactDoc.localeCatalog;
  }
  return {
    version: 'v1',
    locales: [MENU_LOCALE_MODE_BASE, MENU_LOCALE_MODE_RU, MENU_LOCALE_MODE_EN],
    entries: {},
  };
}

function normalizeRuntimeOverlayPayload(payload) {
  if (payload === null || payload === undefined) return [];
  if (Array.isArray(payload)) return payload;
  if (isRuntimeRecord(payload) && Array.isArray(payload.overlays)) {
    return payload.overlays;
  }
  throw new Error('Runtime overlays payload must be an array or an object with overlays[].');
}

function normalizeRuntimeContextPayload(payload) {
  if (payload === null || payload === undefined) return {};
  if (isRuntimeRecord(payload) && isRuntimeRecord(payload.context)) {
    return payload.context;
  }
  if (isRuntimeRecord(payload)) return payload;
  throw new Error('Runtime context payload must be an object.');
}

function resolveRuntimeMenuArtifactPath() {
  const explicitPath = normalizeRuntimeString(process.env[MENU_RUNTIME_ARTIFACT_ENV_PATH]);
  if (!explicitPath) return DEFAULT_MENU_ARTIFACT_PATH;
  return path.resolve(explicitPath);
}

function resolveRawConfigMixAttempt() {
  const explicit = normalizeRuntimeString(process.env[MENU_RUNTIME_RAW_CONFIG_ENV_PATH]);
  if (explicit) return explicit;
  return normalizeRuntimeString(process.env[MENU_RUNTIME_LEGACY_RAW_CONFIG_ENV_PATH]);
}

function readMenuArtifactDocument(artifactPath) {
  let parsed;
  try {
    parsed = JSON.parse(fsSync.readFileSync(artifactPath, 'utf8'));
  } catch (error) {
    throw new Error(`Cannot read runtime menu artifact (${artifactPath}): ${error.message}`);
  }

  if (!isRuntimeRecord(parsed)) {
    throw new Error(`Runtime menu artifact must be an object: ${artifactPath}`);
  }
  if (!Array.isArray(parsed.menus)) {
    throw new Error(`Runtime menu artifact must contain menus[]: ${artifactPath}`);
  }
  return parsed;
}

function resolveRuntimeMenuBuildConfig(mode) {
  const artifactPath = resolveRuntimeMenuArtifactPath();
  const artifactDoc = readMenuArtifactDocument(artifactPath);
  const sourcePolicy = evaluateRuntimeMenuSourcePolicy({
    mode,
    usesArtifact: true,
    usesRawConfig: Boolean(resolveRawConfigMixAttempt()),
  });

  if (!sourcePolicy.ok) {
    throw createRuntimeMenuPolicyError(
      'Runtime menu source policy failed.',
      {
        reason: sourcePolicy.reason,
        result: sourcePolicy.result,
      },
      mode,
    );
  }

  if (sourcePolicy.result === 'WARN') {
    emitRuntimeMenuAdvisory('Runtime menu source mix rejected; fallback to artifact-only.', {
      reason: sourcePolicy.reason,
    });
  }

  const artifactOnlyConfig = {
    fonts: Array.isArray(artifactDoc.fonts) ? artifactDoc.fonts : [],
    localeCatalog: resolveRuntimeMenuLocaleCatalog(artifactDoc),
    menus: artifactDoc.menus,
  };
  if (sourcePolicy.fallbackToArtifactOnly) {
    return artifactOnlyConfig;
  }

  let overlayPayload;
  let contextPayload;
  try {
    overlayPayload = parseRuntimeJsonInput(
      MENU_RUNTIME_OVERLAYS_ENV_PATH,
      MENU_RUNTIME_OVERLAYS_ENV_JSON,
      'runtime overlays',
    );
    contextPayload = parseRuntimeJsonInput(
      MENU_RUNTIME_CONTEXT_ENV_PATH,
      MENU_RUNTIME_CONTEXT_ENV_JSON,
      'runtime context',
    );
  } catch (error) {
    if (mode === 'promotion') {
      throw createRuntimeMenuPolicyError(error.message, { reason: 'RUNTIME_MENU_INPUT_PARSE_FAILED' }, mode);
    }
    emitRuntimeMenuAdvisory(error.message, { reason: 'RUNTIME_MENU_INPUT_PARSE_FAILED' });
    return artifactOnlyConfig;
  }

  let overlays;
  let contextInput = {};
  try {
    overlays = normalizeRuntimeOverlayPayload(overlayPayload);
    contextInput = normalizeRuntimeContextPayload(contextPayload);
  } catch (error) {
    if (mode === 'promotion') {
      throw createRuntimeMenuPolicyError(error.message, { reason: 'RUNTIME_MENU_INPUT_INVALID' }, mode);
    }
    emitRuntimeMenuAdvisory(error.message, { reason: 'RUNTIME_MENU_INPUT_INVALID' });
    return artifactOnlyConfig;
  }
  if (overlays.length === 0) {
    return artifactOnlyConfig;
  }

  const contextState = validateMenuContext(contextInput, { mode });
  if (!contextState.ok) {
    const details = {
      reason: 'RUNTIME_MENU_CONTEXT_INVALID',
      contextErrors: contextState.errors,
    };
    if (mode === 'promotion') {
      throw createRuntimeMenuPolicyError('Runtime menu context validation failed.', details, mode);
    }
    emitRuntimeMenuAdvisory('Runtime menu context validation failed; fallback to artifact-only.', details);
    return artifactOnlyConfig;
  }

  const normalizerState = normalizeMenuConfigPipeline({
    baseConfig: {
      version: 'v2',
      menus: artifactDoc.menus,
      fonts: Array.isArray(artifactDoc.fonts) ? artifactDoc.fonts : [],
    },
    overlays,
    context: toMenuRuntimeNormalizerContext(contextState.normalizedCtx),
    mode,
    baseSourceRef: artifactPath,
  });

  if (!normalizerState.ok || !normalizerState.normalizedConfig) {
    const details = {
      reason: 'RUNTIME_MENU_NORMALIZATION_FAILED',
      diagnostics: normalizerState.diagnostics,
    };
    if (mode === 'promotion') {
      throw createRuntimeMenuPolicyError('Runtime overlay normalization failed.', details, mode);
    }
    emitRuntimeMenuAdvisory('Runtime overlay normalization failed; fallback to artifact-only.', details);
    return artifactOnlyConfig;
  }

  return {
    fonts: Array.isArray(artifactDoc.fonts) ? artifactDoc.fonts : [],
    localeCatalog: isRuntimeRecord(normalizerState.normalizedConfig.localeCatalog)
      ? normalizerState.normalizedConfig.localeCatalog
      : resolveRuntimeMenuLocaleCatalog(artifactDoc),
    menus: normalizerState.normalizedConfig.menus,
  };
}

function resolveMenuAccelerator(value) {
  if (typeof value !== 'string' || !value.startsWith('$')) {
    return value;
  }

  const token = value.slice(1);
  if (!Object.prototype.hasOwnProperty.call(MENU_ACCELERATOR_TOKENS, token)) {
    throw new Error(`Unsupported menu accelerator token: ${value}`);
  }
  return MENU_ACCELERATOR_TOKENS[token];
}

function resolveMenuActionToCommand(actionId) {
  if (typeof actionId !== 'string' || actionId.length === 0) {
    throw new Error(`Invalid menu action id: ${String(actionId)}`);
  }
  const commandId = MENU_ACTION_ALIAS_TO_COMMAND[actionId];
  if (typeof commandId !== 'string' || commandId.length === 0) {
    throw new Error(`Unknown menu action id: ${String(actionId)}`);
  }
  if (isMenuLocalCustomizationCommandId(commandId)) {
    return commandId;
  }
  const resolved = resolveMenuCommandId(commandId, { enforceSunset: false });
  if (!resolved.ok) {
    throw new Error(`Menu action namespace resolution failed: ${resolved.reason || 'COMMAND_NAMESPACE_RESOLUTION_FAILED'}`);
  }
  return resolved.commandId;
}

function dispatchMenuCommand(commandId, payload = {}, options = {}) {
  const route = typeof options.route === 'string' && options.route.length > 0
    ? options.route
    : COMMAND_BUS_ROUTE;
  if (route !== COMMAND_BUS_ROUTE) {
    throw new Error(`Unsupported menu command route: ${route}`);
  }

  // R2.4 ENT0: the entitlement decision comes from the single product-plane
  // table with a product-owned tier. Renderer or menu hints never decide.
  const entitlement = decideCommandEntitlement(commandId, getProductEntitlementTier());
  if (!entitlement.available) {
    return {
      ok: false,
      code: E_COMMAND_DISABLED_FOR_ENTITLEMENT,
      reason: entitlement.reason,
      commandId,
    };
  }

  if (isMenuLocalCustomizationCommandId(commandId)) {
    const handler = MENU_COMMAND_HANDLERS[commandId];
    if (typeof handler !== 'function') {
      throw new Error(`Unknown menu command id: ${String(commandId)}`);
    }
    return handler(payload);
  }

  const resolved = resolveMenuCommandId(commandId, { enforceSunset: false });
  if (!resolved.ok) {
    throw new Error(`Unknown menu command namespace: ${String(commandId)}`);
  }

  const handler = MENU_COMMAND_HANDLERS[resolved.commandId];
  if (typeof handler !== 'function') {
    throw new Error(`Unknown menu command id: ${String(resolved.commandId)}`);
  }

  return handler(payload);
}

function buildCommandClickHandler(commandId, payload = {}) {
  return () => {
    try {
      const result = dispatchMenuCommand(commandId, payload, { route: COMMAND_BUS_ROUTE });
      if (result && typeof result.catch === 'function') {
        result.catch((error) => {
          logDevError(`menu-command:${commandId}`, error);
        });
      }
    } catch (error) {
      logDevError(`menu-command:${commandId}`, error);
    }
  };
}

function normalizeUiBridgeMenuResult(result) {
  if (!isPlainObjectValue(result) || result.ok !== 1) {
    return result;
  }
  return {
    ...result,
    ok: true,
  };
}

function findCommandBridgeFailureReason(value, depth = 0) {
  if (!isPlainObjectValue(value) || depth > 4) return '';
  if (typeof value.reason === 'string' && value.reason) return value.reason;
  if (isPlainObjectValue(value.error)) {
    const errorReason = findCommandBridgeFailureReason(value.error, depth + 1);
    if (errorReason) return errorReason;
  }
  if (isPlainObjectValue(value.value)) {
    const valueReason = findCommandBridgeFailureReason(value.value, depth + 1);
    if (valueReason) return valueReason;
  }
  if (isPlainObjectValue(value.details)) {
    const detailReason = findCommandBridgeFailureReason(value.details, depth + 1);
    if (detailReason) return detailReason;
  }
  if (typeof value.error === 'string' && value.error) return value.error;
  return '';
}

function makeProductCommandBridgeError(commandId, code, reason, details = undefined) {
  const error = {
    code,
    op: commandId,
    reason,
  };
  if (isPlainObjectValue(details) && Object.keys(details).length > 0) {
    error.details = cloneJsonSafe(details);
  }
  return { ok: false, error };
}

function readAuthorityCapabilityMatrixDoc() {
  const matrixPath = path.join(__dirname, '..', 'docs', 'OPS', 'CAPABILITIES_MATRIX.json');
  try {
    const parsed = JSON.parse(fsSync.readFileSync(matrixPath, 'utf8'));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

const productCommandTransactionQueues = new Map();

const PRODUCT_AUTHOR_DOMAIN_SCHEMAS = Object.freeze({
  atlas: Object.freeze({ manifestKey: 'atlas', schemaVersion: 'atlas.author.v1', collectionKey: 'entities' }),
  manualMap: Object.freeze({ manifestKey: 'manualMaps', schemaVersion: 'manualMap.author.v1', collectionKey: 'maps' }),
  idea: Object.freeze({ manifestKey: 'ideas', schemaVersion: 'idea.author.v1', collectionKey: 'ideas' }),
  meaning: Object.freeze({ manifestKey: 'meanings', schemaVersion: 'meaning.author.v1', collectionKey: 'meanings' }),
});

function validateProductCommandAuthorDomain(binding, commandId, record) {
  const spec = PRODUCT_AUTHOR_DOMAIN_SCHEMAS[record.domain];
  if (!spec) return null;
  const manifest = binding.manifest;
  if (!Object.prototype.hasOwnProperty.call(manifest, spec.manifestKey)) return null;
  const value = manifest[spec.manifestKey];
  if (
    isPlainObjectValue(value)
    && value.schemaVersion === spec.schemaVersion
    && isPlainObjectValue(value[spec.collectionKey])
  ) {
    return null;
  }
  return makeProductCommandBridgeError(
    commandId,
    'E_PRODUCT_COMMAND_AUTHOR_SCHEMA_UNSUPPORTED',
    'PRODUCT_COMMAND_AUTHOR_SCHEMA_UNSUPPORTED',
    {
      commandAuthority: record.commandAuthority,
      capabilityId: record.capabilityId,
      domain: record.domain,
      projectId: binding.projectId,
      manifestKey: spec.manifestKey,
      expectedSchemaVersion: spec.schemaVersion,
      actualSchemaVersion: isPlainObjectValue(value) && typeof value.schemaVersion === 'string'
        ? value.schemaVersion
        : null,
      mutationApplied: false,
      storageWritten: false,
      recoveryWritten: false,
    },
  );
}

function getProjectAuthorDomainForPersistence(project, manifestKey, createEmpty) {
  if (isPlainObjectValue(project) && Object.prototype.hasOwnProperty.call(project, manifestKey)) {
    return cloneJsonSafe(project[manifestKey]);
  }
  return createEmpty();
}

const MANUAL_MAP_LOCAL_FILE_MAX_BYTES = 8 * 1024 * 1024;

function manualMapPortabilityError(commandId, code, reason, details = {}) {
  return {
    ok: false,
    error: {
      code,
      op: commandId,
      reason,
      details: isPlainObjectValue(details) ? cloneJsonSafe(details) : {},
    },
  };
}

async function buildManualMapExternalArtifactMutation({ targetPath, content, format, mediaType }) {
  const nextText = typeof content === 'string' ? content : '';
  const nextHash = computeHash(nextText);
  let previousExists = false;
  let previousText = '';
  try {
    previousText = await fs.readFile(targetPath, 'utf8');
    previousExists = true;
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error;
  }
  if (Buffer.byteLength(previousText, 'utf8') > MANUAL_MAP_LOCAL_FILE_MAX_BYTES) {
    throw Object.assign(new Error('MANUAL_MAP_EXPORT_TARGET_TOO_LARGE'), {
      code: 'E_MANUAL_MAP_EXPORT_TARGET_TOO_LARGE',
      reason: 'MANUAL_MAP_EXPORT_TARGET_TOO_LARGE',
    });
  }
  return {
    schemaVersion: 'yalken.stage10.externalArtifactMutation.v1',
    targetPath,
    format,
    mediaType,
    nextText,
    nextHash,
    previousExists,
    previousText,
    previousHash: previousExists ? computeHash(previousText) : '',
  };
}

async function prepareManualMapPortabilityCommand(commandId, payload, binding, record) {
  const safePayload = normalizeManualMapPortabilityPayload(payload);
  if (commandId === 'manualMap.import.jsonRepeat') {
    const selection = await showOpenDialogWithAutonomousPath(mainWindow, {
      title: 'Import Manual Map JSON',
      defaultPath: fileManager.getDocumentsPath(),
      filters: [{ name: 'Manual Map JSON', extensions: ['json'] }],
      properties: ['openFile'],
    }, 'YALKEN_AUTONOMOUS_FILE_DIALOG_OPEN_MANUAL_MAP_JSON');
    const sourcePath = !selection?.canceled && Array.isArray(selection.filePaths)
      ? selection.filePaths[0]
      : '';
    if (!sourcePath) {
      return manualMapPortabilityError(commandId, 'E_MANUAL_MAP_IMPORT_CANCELED', 'MANUAL_MAP_IMPORT_CANCELED');
    }
    let loaded;
    try {
      loaded = await readExternalFileBounded(sourcePath, {
        projectRoot: binding.projectRoot,
        allowedExtensions: ['.json'],
        allowEmpty: false,
        maxBytes: MANUAL_MAP_LOCAL_FILE_MAX_BYTES,
      });
    } catch (error) {
      return manualMapPortabilityError(
        commandId,
        error?.code || 'E_MANUAL_MAP_IMPORT_READ_FAILED',
        error?.reason || 'MANUAL_MAP_IMPORT_READ_FAILED',
      );
    }
    const importModule = await loadManualMapImportModule();
    const targetMapId = safePayload.targetMapId || `${safePayload.mapId || 'manual-map'}-imported`;
    let exportJson;
    try {
      exportJson = new TextDecoder('utf-8', { fatal: true }).decode(loaded.bytes);
    } catch {
      return manualMapPortabilityError(
        commandId,
        'E_MANUAL_MAP_IMPORT_UTF8_INVALID',
        'MANUAL_MAP_IMPORT_UTF8_INVALID',
      );
    }
    const importPlan = importModule.buildManualMapJsonRepeatImportPlan({
      exportJson,
      initialState: binding.coreState,
      targetProjectId: binding.projectId,
      targetMapId,
      title: safePayload.title || targetMapId,
    });
    if (!importPlan?.ok) {
      return manualMapPortabilityError(
        commandId,
        importPlan?.error?.code || 'E_MANUAL_MAP_IMPORT_PLAN_FAILED',
        importPlan?.error?.reason || 'MANUAL_MAP_IMPORT_PLAN_FAILED',
      );
    }
    return {
      ok: true,
      payload: {
        projectId: binding.projectId,
        mapId: targetMapId,
        importPlan: importPlan.value,
        sourceArtifact: {
          schemaVersion: 'manualMap.localArtifactSource.v1',
          sourceName: path.basename(loaded.filePath),
          sha256: computeHash(loaded.bytes),
          byteLength: loaded.byteLength,
        },
      },
      publicResult: {
        import: {
          mapId: targetMapId,
          commandPlanHash: importPlan.value.meta?.planHash || '',
          appliedCommandCount: importPlan.value.commands.length,
          sourceSha256: computeHash(loaded.bytes),
          sourceByteLength: loaded.byteLength,
          localFileIntake: true,
        },
      },
      externalArtifactMutation: null,
    };
  }

  const derived = await deriveManualMapGraphForProductCommand(binding, safePayload, commandId, record);
  if (!derived.ok) return { ok: false, error: derived.error?.error || derived.error };
  let content;
  let format;
  let mediaType;
  let publicResult;
  if (commandId === 'manualMap.export.json') {
    const exportModule = await loadManualMapExportModule();
    const exported = exportModule.serializeManualMapExportJsonV1WithLossReport(derived.value.graph);
    content = exported.json;
    format = 'json';
    mediaType = 'application/json';
    publicResult = {
      export: {
        format,
        jsonSha256: computeHash(content),
        byteLength: Buffer.byteLength(content, 'utf8'),
        lossCount: exported.lossReport?.count ?? -1,
        lossReport: cloneJsonSafe(exported.lossReport || {}),
        localFileWritten: true,
      },
    };
  } else {
    if (typeof payload?.requestedFormat === 'string' && payload.requestedFormat.trim().toLowerCase() === 'pdf') {
      return manualMapPortabilityError(
        commandId,
        'E_MANUAL_MAP_PDF_BINARY_ADAPTER_UNAVAILABLE',
        'LOCAL_PRINT_TO_PDF_PORT_NOT_BOUND_FOR_MANUAL_MAP_EXPORT',
        { binaryGenerated: false, typedLoss: true },
      );
    }
    const exportModule = await loadManualMapExportModule();
    const evidence = exportModule.buildManualMapImagePdfExportEvidence(derived.value.graph);
    if (!evidence?.ok || typeof evidence.value?.image?.content !== 'string') {
      return manualMapPortabilityError(
        commandId,
        evidence?.error?.code || 'E_MANUAL_MAP_SVG_EXPORT_FAILED',
        evidence?.error?.reason || 'MANUAL_MAP_SVG_EXPORT_FAILED',
      );
    }
    content = evidence.value.image.content;
    format = 'svg';
    mediaType = 'image/svg+xml';
    publicResult = {
      export: {
        format,
        svgSha256: computeHash(content),
        byteLength: Buffer.byteLength(content, 'utf8'),
        evidenceHash: evidence.value.meta?.evidenceHash || '',
        localFileWritten: true,
        pdf: {
          binaryGenerated: false,
          typedLoss: {
            code: 'E_MANUAL_MAP_PDF_BINARY_ADAPTER_UNAVAILABLE',
            reason: 'LOCAL_PRINT_TO_PDF_PORT_NOT_BOUND_FOR_MANUAL_MAP_EXPORT',
          },
        },
      },
    };
  }
  const extension = format === 'json' ? 'json' : 'svg';
  const save = await showSaveDialogWithAutonomousPath(mainWindow, {
    title: format === 'json' ? 'Export Manual Map JSON' : 'Export Manual Map SVG',
    defaultPath: `manual-map.${extension}`,
    filters: [{ name: format === 'json' ? 'Manual Map JSON' : 'Scalable Vector Graphics', extensions: [extension] }],
  }, `manual-map.${extension}`);
  if (!save || save.canceled || !save.filePath) {
    return manualMapPortabilityError(commandId, 'E_MANUAL_MAP_EXPORT_CANCELED', 'MANUAL_MAP_EXPORT_CANCELED');
  }
  let validated;
  try {
    validated = await validateExternalWriteTarget(save.filePath, {
      projectRoot: binding.projectRoot,
      sourcePaths: [binding.manifestPath],
      allowedExtensions: [`.${extension}`],
    });
  } catch (error) {
    return manualMapPortabilityError(
      commandId,
      error?.code || 'E_MANUAL_MAP_EXPORT_TARGET_INVALID',
      error?.reason || 'MANUAL_MAP_EXPORT_TARGET_INVALID',
    );
  }
  const externalArtifactMutation = await buildManualMapExternalArtifactMutation({
    targetPath: validated.targetPath,
    content,
    format,
    mediaType,
  });
  return {
    ok: true,
    payload: {
      projectId: binding.projectId,
      mapId: derived.value.mapId,
      artifact: {
        schemaVersion: 'manualMap.localArtifactIntent.v1',
        format,
        mediaType,
        sha256: externalArtifactMutation.nextHash,
        byteLength: Buffer.byteLength(content, 'utf8'),
      },
    },
    publicResult,
    externalArtifactMutation,
  };
}

async function prepareCanonicalProjectTruthCommand(commandId, payload) {
  const record = getProductCommandRecord(commandId);
  const spec = record ? PRODUCT_AUTHOR_DOMAIN_SCHEMAS[record.domain] : null;
  if (!record || !spec) {
    const error = new Error('CANONICAL_PROJECT_TRUTH_COMMAND_NOT_SUPPORTED');
    error.code = 'E_STAGE10_CANONICAL_PROJECT_TRUTH_COMMAND_NOT_SUPPORTED';
    throw error;
  }
  const binding = await buildProductCoreStateForCurrentProject();
  const requestedProjectId = typeof payload?.projectId === 'string' ? payload.projectId.trim() : '';
  if (requestedProjectId && requestedProjectId !== binding.projectId) {
    const error = new Error('CANONICAL_PROJECT_TRUTH_PROJECT_MISMATCH');
    error.code = 'E_STAGE10_CANONICAL_PROJECT_TRUTH_PROJECT_MISMATCH';
    throw error;
  }
  const schemaFailure = validateProductCommandAuthorDomain(binding, commandId, record);
  if (schemaFailure) return schemaFailure;
  const rawRecord = await readProjectManifestRawAtPath(binding.manifestPath);
  const previousHash = computeHash(rawRecord.raw);
  const portability = [
    'manualMap.export.json',
    'manualMap.export.imagePdf',
    'manualMap.import.jsonRepeat',
  ].includes(commandId)
    ? await prepareManualMapPortabilityCommand(commandId, payload, binding, record)
    : null;
  if (portability && portability.ok !== true) return portability;
  return {
    schemaVersion: 'yalken.stage10.canonicalProjectTruthCommand.v1',
    projectId: binding.projectId,
    sourceHash: previousHash,
    sourceRevision: Number(binding.manifest?.lastCommandId || 0),
    coreState: cloneJsonSafe(binding.coreState),
    payload: portability?.payload || cloneJsonSafe(payload),
    publicResult: portability?.publicResult || null,
    async prepareMutation(result = {}) {
      const nextProject = result.nextCoreState?.data?.projects?.[binding.projectId];
      if (!isPlainObjectValue(nextProject)) {
        const error = new Error('CANONICAL_PROJECT_TRUTH_NEXT_PROJECT_MISSING');
        error.code = 'E_STAGE10_CANONICAL_PROJECT_TRUTH_NEXT_PROJECT_MISSING';
        throw error;
      }
      const unchanged = await assertProductCommandManifestUnchanged(
        binding,
        previousHash,
        commandId,
        record,
      );
      if (!unchanged.ok) {
        const failure = unchanged.error?.error || unchanged.error;
        const error = new Error(failure?.reason || 'PRODUCT_COMMAND_REVISION_CONFLICT');
        error.code = failure?.code || 'E_PRODUCT_COMMAND_REVISION_CONFLICT';
        error.reason = failure?.reason || 'PRODUCT_COMMAND_REVISION_CONFLICT';
        error.details = failure?.details || {};
        throw error;
      }
      const nextManifest = {
        ...binding.manifest,
        [spec.manifestKey]: getProjectAuthorDomainForPersistence(
          nextProject,
          spec.manifestKey,
          () => cloneJsonSafe(binding.manifest?.[spec.manifestKey] || {}),
        ),
        lastCommandId: Number.isInteger(result.nextCoreState?.data?.lastCommandId)
          ? result.nextCoreState.data.lastCommandId
          : Number(binding.manifest?.lastCommandId || 0),
      };
      const nextText = JSON.stringify(nextManifest, null, 2);
      return {
        schemaVersion: 'yalken.stage10.projectTruthMutation.v1',
        projectId: binding.projectId,
        relativePath: PROJECT_MANIFEST_FILENAME,
        previousText: rawRecord.raw,
        nextText,
        previousHash,
        nextHash: computeHash(nextText),
        externalArtifactMutation: portability?.externalArtifactMutation || null,
      };
    },
  };
}

async function enqueueProductCommandTransaction(projectKey, operation) {
  const key = typeof projectKey === 'string' && projectKey.trim()
    ? projectKey.trim()
    : DEFAULT_PROJECT_NAME;
  const previous = productCommandTransactionQueues.get(key) || Promise.resolve();
  let release = () => {};
  const current = new Promise((resolve) => {
    release = resolve;
  });
  const queuedTail = previous.then(() => current, () => current);
  productCommandTransactionQueues.set(key, queuedTail);
  try {
    await previous.catch(() => {});
    return await operation();
  } finally {
    release();
    if (productCommandTransactionQueues.get(key) === queuedTail) {
      productCommandTransactionQueues.delete(key);
    }
  }
}

async function assertProductCommandManifestUnchanged(binding, expectedManifestHash, commandId, record) {
  const latest = await readProjectManifestRawAtPath(binding.manifestPath);
  const latestHash = computeHash(latest.raw);
  if (latestHash === expectedManifestHash) {
    return { ok: true, latest, latestHash };
  }
  return {
    ok: false,
    error: makeProductCommandBridgeError(
      commandId,
      'E_PRODUCT_COMMAND_REVISION_CONFLICT',
      'PRODUCT_COMMAND_REVISION_CONFLICT',
      {
        commandAuthority: record.commandAuthority,
        capabilityId: record.capabilityId,
        domain: record.domain,
        projectId: binding.projectId,
        expectedManifestHash,
        actualManifestHash: latestHash,
        mutationApplied: false,
        storageWritten: false,
        transactionSerialized: true,
      },
    ),
  };
}

function normalizeManualMapPortabilityPayload(payload = {}) {
  const source = isPlainObjectValue(payload) ? payload : {};
  return {
    projectId: typeof source.projectId === 'string' ? source.projectId.trim() : '',
    mapId: typeof source.mapId === 'string' ? source.mapId.trim() : '',
    targetMapId: typeof source.targetMapId === 'string' ? source.targetMapId.trim() : '',
    title: typeof source.title === 'string' ? source.title.trim() : '',
  };
}

async function deriveManualMapGraphForProductCommand(binding, payload, commandId, record) {
  const safePayload = normalizeManualMapPortabilityPayload(payload);
  const project = binding.coreState?.data?.projects?.[binding.projectId];
  const maps = isPlainObjectValue(project?.manualMaps?.maps) ? project.manualMaps.maps : {};
  const mapId = safePayload.mapId || Object.keys(maps).sort()[0] || '';
  if (!mapId || !isPlainObjectValue(maps[mapId])) {
    return {
      ok: false,
      error: makeProductCommandBridgeError(
        commandId,
        'E_MANUAL_MAP_PORTABILITY_MAP_NOT_FOUND',
        'MANUAL_MAP_PORTABILITY_MAP_NOT_FOUND',
        {
          commandAuthority: record.commandAuthority,
          capabilityId: record.capabilityId,
          domain: record.domain,
          projectId: binding.projectId,
          mapId,
          mutationApplied: false,
          storageWritten: false,
        },
      ),
    };
  }
  const graphModule = await loadManualMapGraphModule();
  const derived = graphModule.deriveManualMapGraph({
    coreState: binding.coreState,
    params: { projectId: binding.projectId, mapId },
    capabilitySnapshot: {
      platformId: DEFAULT_AUTHORITY_PLATFORM_ID,
      capabilities: { 'manualMap.view': true, manualMapView: true },
    },
  });
  if (!derived || derived.ok !== true) {
    return {
      ok: false,
      error: makeProductCommandBridgeError(
        commandId,
        derived?.error?.code || 'E_MANUAL_MAP_PORTABILITY_DERIVE_FAILED',
        derived?.error?.reason || 'MANUAL_MAP_PORTABILITY_DERIVE_FAILED',
        {
          commandAuthority: record.commandAuthority,
          capabilityId: record.capabilityId,
          domain: record.domain,
          projectId: binding.projectId,
          mapId,
          mutationApplied: false,
          storageWritten: false,
          deriveError: derived?.error || null,
        },
      ),
    };
  }
  return { ok: true, value: { mapId, graph: derived.value } };
}

async function dispatchBlackBoxProductCommandBridge(commandId, payload = {}, record = null) {
  const blackBoxModule = await loadBlackBoxProductCommandModule();
  if (commandId !== blackBoxModule.BLACK_BOX_PRODUCT_COMMAND_EXPORT_MANUAL_CORE_V1_COMMAND_ID) {
    return makeProductCommandBridgeError(
      commandId,
      'E_BLACK_BOX_PRODUCT_COMMAND_NOT_REGISTERED',
      'BLACK_BOX_PRODUCT_COMMAND_NOT_REGISTERED',
      {
        commandAuthority: record?.commandAuthority || 'CommandKernel',
        capabilityId: record?.capabilityId || '',
        domain: record?.domain || 'blackBox',
        mutationApplied: false,
        storageWritten: false,
      },
    );
  }

  const productFlagEnabled = process.env.YALKEN_ENABLE_BLACK_BOX_MANUAL_CORE_CAPSULE_COMMAND_V1 === '1';
  let runtimeProviderAuditBindingPromise = null;
  async function getRuntimeProviderAuditBinding() {
    if (!runtimeProviderAuditBindingPromise) {
      runtimeProviderAuditBindingPromise = loadBlackBoxStrictCapsuleRecoverModule()
        .then((strictCapsuleRecoverModule) => createBlackBoxRuntimeProviderAuditBindingV1({
          env: process.env,
          strictCapsuleRecoverModule,
          tempRoot: os.tmpdir(),
        }))
        .catch(() => ({
          providerPin: null,
          auditRecipient: null,
          auditIdentity: null,
          ageProvider: null,
        }));
    }
    return runtimeProviderAuditBindingPromise;
  }
  let runtimeSourceRevisionBindingPromise = null;
  async function getRuntimeSourceRevisionBinding() {
    if (!runtimeSourceRevisionBindingPromise) {
      runtimeSourceRevisionBindingPromise = buildProjectTreeRootsWithIdentitiesReadOnly()
        .then((projectTree) => createBlackBoxRuntimeSourceRevisionBindingV1({
          projectRoot: getProjectRootPath(),
          projectTree,
          isDirty: () => Boolean(isDirty),
          autoSaveInProgress: () => Boolean(autoSaveInProgress),
        }))
        .catch(() => createBlackBoxRuntimeSourceRevisionBindingV1({
          projectRoot: getProjectRootPath(),
          projectTree: null,
          isDirty: true,
          autoSaveInProgress: true,
        }));
    }
    return runtimeSourceRevisionBindingPromise;
  }
  let runtimeCreateOnlyTargetBinding = null;
  function getRuntimeCreateOnlyTargetBinding() {
    if (!runtimeCreateOnlyTargetBinding) {
      runtimeCreateOnlyTargetBinding = createBlackBoxRuntimeCreateOnlyTargetBindingV1({
        env: process.env,
        projectRoot: getProjectRootPath(),
        platform: process.platform,
      });
    }
    return runtimeCreateOnlyTargetBinding;
  }

  return blackBoxModule.executeBlackBoxProductCommandExportManualCoreV1(payload, {
    ports: {
      getFeatureFlags: async () => ({
        'yalken.blackBox.coreSourceAdapter.p0aV1': productFlagEnabled,
        'yalken.blackBox.darwinDurablePublisher.p0bV1': productFlagEnabled,
        'yalken.blackBox.strictCapsuleRecover.p0cV1': productFlagEnabled,
        'yalken.blackBox.manualCoreCapsuleKit.v1': productFlagEnabled,
      }),
      getExpectedSourceIdentity: async () => (await getRuntimeSourceRevisionBinding()).expected,
      getProjectRoot: async () => getProjectRootPath(),
      observeRevision: async (input) => (await getRuntimeSourceRevisionBinding()).observeRevision(input),
      getProviderPin: async () => (await getRuntimeProviderAuditBinding()).providerPin,
      getAuditRecipient: async () => (await getRuntimeProviderAuditBinding()).auditRecipient,
      getAuditIdentity: async () => (await getRuntimeProviderAuditBinding()).auditIdentity,
      getAgeProvider: async () => (await getRuntimeProviderAuditBinding()).ageProvider,
      selectCreateOnlyTarget: async (context) => (await getRuntimeCreateOnlyTargetBinding()).selectCreateOnlyTarget(context),
    },
  });
}

async function dispatchProductCommandBridge(commandId, payload = {}) {
  const record = getProductCommandRecord(commandId);
  if (!record) {
    return makeProductCommandBridgeError(
      commandId,
      'E_PRODUCT_COMMAND_NOT_ALLOWED',
      'PRODUCT_COMMAND_NOT_ALLOWED',
    );
  }

  // R2.4 ENT0: the same single table gates this port too, with the
  // product-owned tier; the renderer payload is never consulted.
  const entitlement = decideCommandEntitlement(commandId, getProductEntitlementTier());
  if (!entitlement.available) {
    return makeProductCommandBridgeError(
      commandId,
      E_COMMAND_DISABLED_FOR_ENTITLEMENT,
      entitlement.reason,
      {
        commandAuthority: record.commandAuthority,
        capabilityId: record.capabilityId,
        domain: record.domain,
        mutationApplied: false,
        storageWritten: false,
      },
    );
  }

  if (!isPlainObjectValue(payload)) {
    return makeProductCommandBridgeError(
      commandId,
      'E_PRODUCT_COMMAND_PAYLOAD_INVALID',
      'PRODUCT_COMMAND_PAYLOAD_REQUIRED',
      {
        commandAuthority: record.commandAuthority,
        capabilityId: record.capabilityId,
        domain: record.domain,
        runtimeBacked: record.runtimeBacked === true,
        payloadAccepted: false,
        mutationApplied: false,
        storageWritten: false,
      },
    );
  }

  const capability = evaluateCommandCapabilityAuthority({
    commandId,
    capabilityId: record.capabilityId,
    platformId: DEFAULT_AUTHORITY_PLATFORM_ID,
    matrixDoc: readAuthorityCapabilityMatrixDoc(),
  });
  if (!capability.ok) {
    return makeProductCommandBridgeError(
      commandId,
      capability.error?.code || 'E_CAPABILITY_ENFORCEMENT_FAILED',
      capability.error?.reason || 'CAPABILITY_ENFORCEMENT_FAILED',
      {
        commandAuthority: record.commandAuthority,
        capabilityId: record.capabilityId,
        domain: record.domain,
        platformId: DEFAULT_AUTHORITY_PLATFORM_ID,
        mutationApplied: false,
        storageWritten: false,
        capabilityError: capability.error || null,
      },
    );
  }

  if (record.domain === 'blackBox') {
    return dispatchBlackBoxProductCommandBridge(commandId, payload, record);
  }

  const canonicalAuthorCommand = Object.prototype.hasOwnProperty.call(PRODUCT_AUTHOR_DOMAIN_SCHEMAS, record.domain);
  if (record.domain === 'stage10' || canonicalAuthorCommand) {
    if (!activeStage10ApplicationCommandRoute || typeof activeStage10ApplicationCommandRoute.dispatch !== 'function') {
      return makeProductCommandBridgeError(
        commandId,
        'E_STAGE10_APPLICATION_BOOTSTRAP_MISSING',
        'STAGE10_APPLICATION_BOOTSTRAP_MISSING',
        {
          commandAuthority: record.commandAuthority,
          capabilityId: record.capabilityId,
          domain: record.domain,
          mutationApplied: false,
          storageWritten: false,
        },
      );
    }
    return enqueueProductCommandTransaction(currentProjectName || DEFAULT_PROJECT_NAME, async () => {
      try {
        return await activeStage10ApplicationCommandRoute.dispatch(commandId, payload);
      } catch (error) {
        return makeProductCommandBridgeError(
          commandId,
          error?.code || 'E_PRODUCT_COMMAND_KERNEL_ROUTE_FAILED',
          error?.reason || error?.message || 'PRODUCT_COMMAND_KERNEL_ROUTE_FAILED',
          {
            commandAuthority: record.commandAuthority,
            capabilityId: record.capabilityId,
            domain: record.domain,
            mutationApplied: false,
            storageWritten: false,
          },
        );
      }
    });
  }

  return makeProductCommandBridgeError(
    commandId,
    'E_PRODUCT_COMMAND_CANONICAL_KERNEL_ROUTE_REQUIRED',
    'PRODUCT_COMMAND_CANONICAL_KERNEL_ROUTE_REQUIRED',
    {
      commandAuthority: record.commandAuthority,
      capabilityId: record.capabilityId,
      domain: record.domain,
      mutationApplied: false,
      storageWritten: false,
    },
  );
}

function buildFontSubmenu(config) {
  return config.fonts.map((font, index) => {
    if (!font || typeof font !== 'object') {
      throw new Error(`Invalid font config at fonts[${index}]`);
    }
    if (typeof font.label !== 'string' || typeof font.value !== 'string') {
      throw new Error(`Invalid font config at fonts[${index}]: label/value are required`);
    }

    return {
      id: typeof font.id === 'string' ? font.id : `font-${index}`,
      label: font.label,
      click: buildCommandClickHandler('cmd.ui.font.set', { fontFamily: font.value })
    };
  });
}

function cloneMenuTemplateItem(item) {
  if (!item || typeof item !== 'object') {
    return item;
  }

  const cloned = { ...item };
  if (Array.isArray(item.items)) {
    cloned.items = item.items.map((child) => cloneMenuTemplateItem(child));
  }
  if (Array.isArray(item.submenu)) {
    cloned.submenu = item.submenu.map((child) => cloneMenuTemplateItem(child));
  }
  return cloned;
}

function buildMenuCustomizationVisibilitySectionsSubmenu(config) {
  const sections = resolveOrderedCustomizableMenuSections(config);
  const hiddenSet = new Set(normalizeCustomizationStateForCurrentSections(currentMenuCustomization).hiddenMenuIds);

  return sections.map((section) => ({
    id: `view-menu-customization-visibility-${section.id}`,
    label: section.label,
    type: 'checkbox',
    checked: !hiddenSet.has(section.id),
    click: buildCommandClickHandler(MENU_CUSTOMIZATION_COMMAND_TOGGLE_VISIBILITY, {
      actionArg: section.id,
    }),
  }));
}

function buildMenuCustomizationOrderSectionsSubmenu(config) {
  const sections = resolveOrderedCustomizableMenuSections(config);
  const localeCatalog = resolveRuntimeMenuLocaleCatalog(config);
  const moveEarlierLabel = resolveLocalizedMenuLabel(
    localeCatalog,
    MENU_CUSTOMIZATION_MOVE_EARLIER_LABEL_KEY,
    'Move Earlier',
  );
  const moveLaterLabel = resolveLocalizedMenuLabel(
    localeCatalog,
    MENU_CUSTOMIZATION_MOVE_LATER_LABEL_KEY,
    'Move Later',
  );

  return sections.flatMap((section, index) => ([
    {
      id: `view-menu-customization-order-${section.id}-earlier`,
      label: `${moveEarlierLabel}: ${section.label}`,
      enabled: index > 0,
      click: buildCommandClickHandler(MENU_CUSTOMIZATION_COMMAND_MOVE_EARLIER, {
        actionArg: section.id,
      }),
    },
    {
      id: `view-menu-customization-order-${section.id}-later`,
      label: `${moveLaterLabel}: ${section.label}`,
      enabled: index < sections.length - 1,
      click: buildCommandClickHandler(MENU_CUSTOMIZATION_COMMAND_MOVE_LATER, {
        actionArg: section.id,
      }),
    },
  ]));
}

function applyMenuCustomization(template, config) {
  const clonedTemplate = Array.isArray(template)
    ? template.map((item) => cloneMenuTemplateItem(item))
    : [];
  const sections = resolveCustomizableMenuSections(config);
  const canonicalIds = sections.map((section) => section.id);
  currentMenuCustomizationSectionIds = canonicalIds;
  currentMenuCustomization = normalizeMenuCustomizationState(currentMenuCustomization, canonicalIds);

  if (clonedTemplate.length === 0 || canonicalIds.length === 0) {
    return clonedTemplate;
  }

  const topLevelById = new Map();
  clonedTemplate.forEach((item) => {
    if (item && typeof item.id === 'string' && item.id.length > 0) {
      topLevelById.set(item.id, item);
    }
  });

  const orderedOptionalIds = currentMenuCustomization.menuOrder.filter((id) => canonicalIds.includes(id));
  const hiddenSet = new Set(currentMenuCustomization.hiddenMenuIds);
  const projected = [];

  MENU_CUSTOMIZATION_FIXED_PREFIX_IDS.forEach((id) => {
    const fixedItem = topLevelById.get(id);
    if (fixedItem) {
      projected.push(fixedItem);
    }
  });

  orderedOptionalIds.forEach((id) => {
    if (hiddenSet.has(id)) {
      return;
    }
    const optionalItem = topLevelById.get(id);
    if (optionalItem) {
      projected.push(optionalItem);
    }
  });

  const helpItem = topLevelById.get(MENU_CUSTOMIZATION_FIXED_TAIL_ID);
  if (helpItem) {
    projected.push(helpItem);
  }

  return projected;
}

function mergeCompactDuplicateMenuItem(existingItem, nextItem) {
  const existingSubmenu = Array.isArray(existingItem?.submenu) ? existingItem.submenu : [];
  const nextSubmenu = Array.isArray(nextItem?.submenu) ? nextItem.submenu : [];

  if (existingSubmenu.length === 0 && nextSubmenu.length > 0) {
    return nextItem;
  }
  if (nextSubmenu.length === 0 && existingSubmenu.length > 0) {
    return existingItem;
  }
  if (nextSubmenu.length > existingSubmenu.length) {
    return nextItem;
  }
  return existingItem;
}

function dedupeCompactRootSubmenu(items) {
  const deduped = [];
  const idToIndex = new Map();

  items.forEach((item) => {
    if (!item || typeof item !== 'object' || typeof item.id !== 'string' || item.id.length === 0) {
      deduped.push(item);
      return;
    }

    if (!idToIndex.has(item.id)) {
      idToIndex.set(item.id, deduped.length);
      deduped.push(item);
      return;
    }

    const index = idToIndex.get(item.id);
    deduped[index] = mergeCompactDuplicateMenuItem(deduped[index], item);
  });

  return deduped;
}

function extractCompactRootPinnedItems(nestedGroups) {
  const pinnedItems = [];
  const projectedGroups = nestedGroups.map((item) => {
    if (!item || item.id !== 'view' || !Array.isArray(item.submenu)) {
      return item;
    }

    const projectedSubmenu = [];
    item.submenu.forEach((child) => {
      if (child && child.id === 'view-presentation-mode') {
        pinnedItems.push(cloneMenuTemplateItem(child));
        return;
      }
      projectedSubmenu.push(child);
    });

    return {
      ...item,
      submenu: projectedSubmenu,
    };
  });

  return {
    pinnedItems,
    projectedGroups,
  };
}

function buildCompactMenuTemplate(template) {
  const fileMenu = template.find((item) => item && item.id === 'file');
  if (!fileMenu || !Array.isArray(fileMenu.submenu)) {
    return template.map((item) => cloneMenuTemplateItem(item));
  }

  const compactRootSubmenu = [];
  const nestedGroups = template
    .filter((item) => item && item.id !== 'file')
    .map((item) => cloneMenuTemplateItem(item));
  const { pinnedItems, projectedGroups } = extractCompactRootPinnedItems(nestedGroups);

  compactRootSubmenu.push(...pinnedItems);
  if (pinnedItems.length > 0 && fileMenu.submenu.length > 0) {
    compactRootSubmenu.push({ type: 'separator' });
  }

  compactRootSubmenu.push(...fileMenu.submenu.map((item) => cloneMenuTemplateItem(item)));

  if (compactRootSubmenu.length > 0 && projectedGroups.length > 0) {
    compactRootSubmenu.push({ type: 'separator' });
  }
  compactRootSubmenu.push(...projectedGroups);

  const compactRoot = {
    id: MENU_PRESENTATION_COMPACT_ROOT_ID,
    label: fileMenu.label,
    submenu: dedupeCompactRootSubmenu(compactRootSubmenu),
  };

  if (process.platform === 'darwin') {
    return [
      { role: 'appMenu' },
      compactRoot,
    ];
  }

  return [compactRoot];
}

function applyMenuPresentation(template) {
  if (currentMenuPresentationMode !== MENU_PRESENTATION_MODE_COMPACT) {
    return template;
  }
  return buildCompactMenuTemplate(template);
}

function resolveLocalizedMenuLabel(localeCatalog, labelKey, fallbackLabel) {
  const entries = isRuntimeRecord(localeCatalog) && isRuntimeRecord(localeCatalog.entries)
    ? localeCatalog.entries
    : {};
  const entry = isRuntimeRecord(entries) ? entries[labelKey] : null;
  if (!entry || typeof entry !== 'object') {
    return fallbackLabel;
  }

  const localeValue = typeof entry[currentMenuLocale] === 'string' && entry[currentMenuLocale].trim().length > 0
    ? entry[currentMenuLocale].trim()
    : '';
  if (localeValue) return localeValue;

  const baseValue = typeof entry.base === 'string' && entry.base.trim().length > 0
    ? entry.base.trim()
    : '';
  return baseValue || fallbackLabel;
}

function localizeMenuConfigNode(node, localeCatalog) {
  if (!node || typeof node !== 'object' || Array.isArray(node)) {
    return node;
  }

  const localized = { ...node };
  if (typeof node.label === 'string' && typeof node.labelKey === 'string') {
    localized.label = resolveLocalizedMenuLabel(localeCatalog, node.labelKey, node.label);
  }
  if (Array.isArray(node.items)) {
    localized.items = node.items.map((entry) => localizeMenuConfigNode(entry, localeCatalog));
  }
  return localized;
}

function applyMenuLocale(config) {
  if (!config || typeof config !== 'object' || Array.isArray(config)) {
    return config;
  }

  const localeCatalog = resolveRuntimeMenuLocaleCatalog(config);
  return {
    ...config,
    localeCatalog,
    fonts: Array.isArray(config.fonts) ? config.fonts.map((font) => ({ ...font })) : [],
    menus: Array.isArray(config.menus)
      ? config.menus.map((entry) => localizeMenuConfigNode(entry, localeCatalog))
      : [],
  };
}

function resolveAboutLicensesMenuLabel() {
  try {
    const artifactDoc = readMenuArtifactDocument(resolveRuntimeMenuArtifactPath());
    return resolveLocalizedMenuLabel(
      resolveRuntimeMenuLocaleCatalog(artifactDoc),
      MENU_LOCALE_ABOUT_LICENSES_LABEL_KEY,
      'О программе и лицензии',
    );
  } catch {
    return 'О программе и лицензии';
  }
}

function buildConfiguredMenuCommandPayload(item) {
  return typeof item?.actionArg === 'string' && item.actionArg.length > 0
    ? { actionArg: item.actionArg }
    : {};
}

function buildMenuItemFromConfig(item, config, location) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    throw new Error(`Invalid menu item at ${location}`);
  }

  if (item.type === 'separator') {
    return { type: 'separator' };
  }

  if (typeof item.role === 'string') {
    if (!ALLOWED_MENU_ROLES.has(item.role)) {
      throw new Error(`Unsupported menu role "${item.role}" at ${location}`);
    }

    const roleTemplate = MENU_ROLE_TEMPLATES[item.role];
    const roleItem = {
      ...roleTemplate
    };

    if (typeof item.id === 'string') {
      roleItem.id = item.id;
    }
    if (typeof item.enabled === 'boolean') {
      roleItem.enabled = item.enabled;
    }
    if (typeof item.visible === 'boolean') {
      roleItem.visible = item.visible;
    }
    if (item.visibilityPolicy === 'hidden') {
      roleItem.visible = false;
    } else if (item.visibilityPolicy === 'visible_disabled') {
      roleItem.visible = true;
      roleItem.enabled = false;
    } else if (item.visibilityPolicy === 'visible_enabled') {
      roleItem.visible = true;
      roleItem.enabled = true;
    }

    return roleItem;
  }

  if (typeof item.label !== 'string' || item.label.length === 0) {
    throw new Error(`Menu item label is required at ${location}`);
  }

  const built = {
    label: item.label
  };

  if (typeof item.id === 'string') {
    built.id = item.id;
  }
  if (typeof item.accelerator === 'string') {
    built.accelerator = resolveMenuAccelerator(item.accelerator);
  }
  if (typeof item.enabled === 'boolean') {
    built.enabled = item.enabled;
  }
  if (typeof item.visible === 'boolean') {
    built.visible = item.visible;
  }
  if (item.visibilityPolicy === 'hidden') {
    built.visible = false;
  } else if (item.visibilityPolicy === 'visible_disabled') {
    built.visible = true;
    built.enabled = false;
  } else if (item.visibilityPolicy === 'visible_enabled') {
    built.visible = true;
    built.enabled = true;
  }
  if (typeof item.type === 'string' && item.type !== 'separator') {
    built.type = item.type;
  }
  if (typeof item.checked === 'boolean') {
    built.checked = item.checked;
  }

  if (item.submenuFrom !== undefined) {
    if (item.submenuFrom === 'fonts') {
      built.submenu = buildFontSubmenu(config);
    } else if (item.submenuFrom === MENU_CUSTOMIZATION_SUBMENU_FROM_VISIBILITY_SECTIONS) {
      built.submenu = buildMenuCustomizationVisibilitySectionsSubmenu(config);
    } else if (item.submenuFrom === MENU_CUSTOMIZATION_SUBMENU_FROM_ORDER_SECTIONS) {
      built.submenu = buildMenuCustomizationOrderSectionsSubmenu(config);
    } else {
      throw new Error(`Unknown submenuFrom "${String(item.submenuFrom)}" at ${location}`);
    }
  } else if (Array.isArray(item.items)) {
    built.submenu = item.items.map((child, index) =>
      buildMenuItemFromConfig(child, config, `${location}.items[${index}]`)
    );
  }

  const hasCanonicalCmdId = typeof item.canonicalCmdId === 'string' && item.canonicalCmdId.length > 0;
  const hasCommandField = item.command !== undefined || hasCanonicalCmdId;
  if (hasCommandField && item.actionId !== undefined) {
    throw new Error(`Menu item cannot declare both command and actionId at ${location}`);
  }

  if (hasCommandField) {
    if (item.command !== undefined && typeof item.command !== 'string') {
      throw new Error(`Menu command must be string at ${location}`);
    }
    const sourceCommandId = hasCanonicalCmdId
      ? item.canonicalCmdId
      : item.command;
    if (isMenuLocalCustomizationCommandId(sourceCommandId)) {
      if (sourceCommandId !== MENU_CUSTOMIZATION_COMMAND_RESET
        && (typeof item.actionArg !== 'string' || item.actionArg.length === 0)) {
        throw new Error(`Menu customization command requires actionArg at ${location}`);
      }
      if (sourceCommandId === MENU_CUSTOMIZATION_COMMAND_TOGGLE_VISIBILITY) {
        built.type = 'checkbox';
        built.checked = isMenuCustomizationSectionVisible(item.actionArg);
      }
      built.click = buildCommandClickHandler(sourceCommandId, buildConfiguredMenuCommandPayload(item));
      return built;
    }
    const resolved = resolveMenuCommandId(sourceCommandId, { enforceSunset: false });
    if (!resolved.ok) {
      throw new Error(`Menu command namespace validation failed at ${location}`);
    }
    if (resolved.commandId === MENU_PRESENTATION_COMMAND_CLASSIC
      || resolved.commandId === MENU_PRESENTATION_COMMAND_COMPACT) {
      built.type = 'radio';
      built.checked = resolved.commandId === MENU_PRESENTATION_COMMAND_CLASSIC
        ? currentMenuPresentationMode === MENU_PRESENTATION_MODE_CLASSIC
        : currentMenuPresentationMode === MENU_PRESENTATION_MODE_COMPACT;
    } else if (resolved.commandId === MENU_LOCALE_COMMAND_BASE
      || resolved.commandId === MENU_LOCALE_COMMAND_RU
      || resolved.commandId === MENU_LOCALE_COMMAND_EN) {
      built.type = 'radio';
      built.checked = resolved.commandId === MENU_LOCALE_COMMAND_BASE
        ? currentMenuLocale === MENU_LOCALE_MODE_BASE
        : resolved.commandId === MENU_LOCALE_COMMAND_RU
          ? currentMenuLocale === MENU_LOCALE_MODE_RU
          : currentMenuLocale === MENU_LOCALE_MODE_EN;
    }
    built.click = buildCommandClickHandler(resolved.commandId, buildConfiguredMenuCommandPayload(item));
  } else if (item.actionId !== undefined) {
    if (typeof item.actionId !== 'string') {
      throw new Error(`Menu actionId must be string at ${location}`);
    }
    const commandId = resolveMenuActionToCommand(item.actionId);
    if (isMenuLocalCustomizationCommandId(commandId)) {
      if (commandId !== MENU_CUSTOMIZATION_COMMAND_RESET
        && (typeof item.actionArg !== 'string' || item.actionArg.length === 0)) {
        throw new Error(`Menu customization command requires actionArg at ${location}`);
      }
      if (commandId === MENU_CUSTOMIZATION_COMMAND_TOGGLE_VISIBILITY) {
        built.type = 'checkbox';
        built.checked = isMenuCustomizationSectionVisible(item.actionArg);
      }
    }
    built.click = buildCommandClickHandler(commandId, buildConfiguredMenuCommandPayload(item));
  }

  return built;
}

function buildMenuTemplateFromConfig(config) {
  return config.menus.map((menuItem, index) =>
    buildMenuItemFromConfig(menuItem, config, `menus[${index}]`)
  );
}

function buildSafeFallbackMenuTemplate() {
  return [
    {
      id: 'safe-file',
      label: 'Файл',
      submenu: [
        {
          id: 'safe-quit',
          label: 'Выход',
          accelerator: MENU_ACCELERATOR_TOKENS.platformQuit,
          click: buildCommandClickHandler('cmd.app.quit')
        }
      ]
    }
  ];
}

function applySafeFallbackMenu() {
  const fallbackMenu = Menu.buildFromTemplate(buildSafeFallbackMenuTemplate());
  Menu.setApplicationMenu(fallbackMenu);
}

function createMenu() {
  const mode = resolveRuntimeMenuArtifactMode();
  try {
    const runtimeConfig = resolveRuntimeMenuBuildConfig(mode);
    const localizedConfig = applyMenuLocale(runtimeConfig);
    syncCurrentMenuCustomization(localizedConfig);
    const template = buildMenuTemplateFromConfig(localizedConfig);
    const customizedTemplate = applyMenuCustomization(template, localizedConfig);
    ensureAboutLicensesMenuEntry(customizedTemplate);
    const menu = Menu.buildFromTemplate(applyMenuPresentation(customizedTemplate));
    Menu.setApplicationMenu(menu);
  } catch (error) {
    logDevError('createMenu', error);
    applySafeFallbackMenu();

    if (error && error.menuRuntimeBlocking === true) {
      throw error;
    }
    if (shouldFailHardOnMenuConfigError()) {
      throw error;
    }
  }
}

// Подготовка локальных директорий (Documents/craftsman + autosave) при запуске
async function initializeApp() {
  await fileManager.migrateDocumentsFolder();
  await fileManager.ensureDocumentsFolder();
  await ensureAutosaveDirectory();
  await ensureProjectStructure();
  await buildProjectTreeRootsWithIdentities();
  await bootstrapStage10ApplicationAtStartup();
  await reconcileReviewFormattingReturnAtStartup();
  await reconcileReviewStructuralReturnAtStartup();
  await reconcileReviewExactTextApplyJournalsAtStartup();
  // ROUND-01 (V3): reconcile the docx-review return authority store rounds at
  // startup alongside the existing journal reconciliations. Covers ALL rounds
  // (not only lastRoundId) with a typed report.
  await reconcileRoundRecordV3StoreAtStartup();
}

// ROUND-01 (V3): startup reconciliation of the docx-review return authority
// store. Reads the durable store (all rounds) and runs the revision-bridge V3
// reconcile API so a stale / terminal / pending round is surfaced in a typed
// report rather than silently ignored.
async function reconcileRoundRecordV3StoreAtStartup() {
  try {
    const bridge = await loadRevisionBridgeModule();
    if (!bridge || typeof bridge.reconcileRoundRecordV3Store !== 'function') return null;
    const durableStore = readDurableDocxReviewReturnAuthorityStore({ projectRoot: getProjectRootPath() });
    if (!durableStore) return null;
    const roundsById = isPlainObjectValue(durableStore.roundsById) ? durableStore.roundsById : {};
    const rounds = {};
    for (const [roundId, round] of Object.entries(roundsById)) {
      if (!isPlainObjectValue(round)) continue;
      rounds[roundId] = {
        roundId,
        lifecycleState: docxReviewPreviewSessionDetailString(round.lifecycleState) || 'ALLOCATED',
        keyRef: docxReviewPreviewSessionDetailString(round.keyRef),
        recordVersion: Number(round.recordVersion) || 1,
      };
    }
    return bridge.reconcileRoundRecordV3Store(
      { schemaVersion: 'yalken.rtk.round-record-v3.store.v1', lastRoundId: durableStore.lastRoundId, rounds },
      { projectRoot: getProjectRootPath() },
    );
  } catch (error) {
    logDevError('reconcileRoundRecordV3StoreAtStartup', error);
    return null;
  }
}

app.whenReady().then(async () => {
  if (!singleInstanceLockAcquired) {
    return;
  }
  logPerfStage('when-ready');
  app.setName('Yalken');
  await ensureUserDataFolder();
  installContentSecurityPolicy();
  const windowStatePromise = loadWindowStateFromSettings();
  const menuPresentationModePromise = loadMenuPresentationModeFromSettings();
  const menuLocalePromise = loadMenuLocaleFromSettings();
  const menuCustomizationPromise = loadMenuCustomizationFromSettings();
  let appInitializationError = null;
  appInitializationPromise = initializeApp()
    .then(() => {
      logPerfStage('init-complete');
    })
    .catch((error) => {
      appInitializationError = error;
      logDevError('initializeApp', error);
    });

  await windowStatePromise;
  await menuPresentationModePromise;
  await menuLocalePromise;
  await menuCustomizationPromise;
  await appInitializationPromise;
  if (appInitializationError) {
    dialog.showErrorBox(
      'Yalken recovery required',
      `Project recovery failed safely: ${appInitializationError.code || appInitializationError.message || 'UNKNOWN'}`,
    );
    app.quit();
    return;
  }
  logPerfStage('window-state-loaded');
  createWindow();
  try {
    verifyMenuArtifactLockAtRuntime();
  } catch (error) {
    logDevError('verifyMenuArtifactLockAtRuntime', error);
    app.exit(1);
    return;
  }
  try {
    createMenu();
  } catch (error) {
    logDevError('createMenu', error);
    app.exit(1);
    return;
  }
  logPerfStage('window-visible');

  // Запуск автосохранения каждые 15 секунд
  setInterval(() => {
    autoSave().catch((error) => {
      logDevError('autoSave interval', error);
    });
  }, 15000);

  // Запуск создания бэкапов каждую минуту
  setInterval(() => {
    createBackup();
  }, 60000);

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on('before-quit', (event) => {
  if (isQuitting) {
    return;
  }

  event.preventDefault();

  (async () => {
    const canQuit = await confirmDiscardChanges();
    if (!canQuit) {
      return;
    }

    if (mainWindow) {
      const bounds = mainWindow.getBounds();
      await persistWindowState(bounds);
    }

    isQuitting = true;
    app.quit();
  })().catch(() => {});
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

